window.__D("text/maamarim-melukatim/c010",{"p":[[1500370046,"<h3>בס\"ד. יו\"ד שבט ה'תש\"מ<sup data-n=\"3417\">*</sup></h3>\nהנחה\n<b>באתי</b> לגני אחותי כלה<sup data-n=\"3418\">1</sup>, ומביא ע\"ז כ\"ק מו\"ח אדמו\"ר בעל ההילולא במאמרו ליום ההסתלקות וההילולא שלו, דאיתא במדרש רבה<sup data-n=\"3419\">2</sup> לגני לגנוני, למקום שהי' עיקרי [היינו עיקר דירתי] בתחלה, דעיקר שכינה בתחתונים היתה, וע\"י ז' הענינים הבלתי רצויים נסתלקה השכינה מלמטה למעלה, קוב\"ה סליק לעילא ולעילא<sup data-n=\"3420\">3</sup>, עד לרקיע השביעי, ואח\"כ עמדו שבעה צדיקים והורידו את השכינה מלמעלה למטה, עד שבא משה שהוא השביעי וכל השביעין חביבין<sup data-n=\"3421\">4</sup> והורידה למטה בארץ. וזהו צדיקים יירשו ארץ וישכנו לעד עלי'<sup data-n=\"3422\">5</sup>, דעבודת הצדיקים היא להשכין ולהמשיך את השכינה מלמעלה למטה, בחי' עד (כמו שהיא בבחי' שוכן עד מרום וקדוש) ישכינו עלי', למטה בארץ, בעוה\"ז התחתון שאין תחתון למטה ממנו. והנה התחלת ההמשכה למטה שע\"י משה היתה בעת מ\"ת כמ\"ש<sup data-n=\"3423\">6</sup> וירד הוי' על הר סיני, אבל בקביעות<sup data-n=\"3424\">7</sup> ובגילוי הי' זה בעשיית המשכן כמ\"ש<sup data-n=\"3425\">8</sup> ועשו לי מקדש ושכנתי בתוכם. וממשיך בהמאמר, שהמשכת עיקר שכינה בתחתונים (ושכנתי בתוכם) נעשית ע\"י העבודה דאתהפכא חשוכא לנהורא. וזהו מה שהמשכן הי' מעצי שטים, שמהם נעשו הקרשים, כמ\"ש<sup data-n=\"3426\">9</sup> ועשית את הקרשים למשכן עצי שטים עומדים, קרש הוא אותיות שקר והוא השקר דעולם, הבא מהשטות דלעו\"ז, אין אדם עובר עבירה אא\"כ נכנס בו רוח שטות<sup data-n=\"3427\">10</sup>, וע\"י העבודה דועשית את הקרשים למשכן עצי שטים עומדים, שמהפכים השטות דלעו\"ז לשטות דקדושה (עצי שטים), את השקר דעולם לקרש המשכן (קרשים למשכן), עי\"ז נעשה ושכנתי בתוכם, המשכת (עיקר) שכינה בתחתונים. ומוסיף בהמאמר דיוק לשון הכתוב ושכנתי בתוכם, בתוכו לא נאמר אלא בתוכם בתוך כל אחד ואחד<sup data-n=\"3428\">11</sup>, דבכאו\"א מישראל ע\"י העבודה דאתהפכא חשוכא לנהורא, עי\"ז שוכן בו עיקר שכינה כמו שהי' בתחלת הבריאה, באתי לגני לגנוני, למקום שהי' עיקרו בתחלה, ונעשה עיקר דירה בתחתונים.ב) <b>והנה</b> מכיון שהתורה היא נצחית<sup data-n=\"3429\">12</sup>, הרי מובן, שענין זה (ועשו לי מקדש ושכנתי בתוכם) הוא נצחי במשך כל הדורות, גם בזמן הגלות, כאשר מפני חטאינו גלינו מארצנו ונתרחקנו מעל אדמתנו, שגם אז ישנם (ברוחניות) כל ההוראות והמצוות (דכתיב בהו וחי בהם<sup data-n=\"3430\">13</sup>) התלויות במשכן ומקדש. ועד\"ז הוא גם בנוגע לכל הפרטים שהיו ביציאת מצרים, וגם לפנ\"ז בגלות מצרים, שהם הוראות נצחיות בכל דור ודור, עד היום הזה. וכמו שידוע<sup data-n=\"3431\">14</sup> בענין וימררו את חייהם בעבודה קשה בחומר ובלבנים גו'<sup data-n=\"3432\">15</sup>, שגם עכשיו בגלות האחרון ישנה העבודה בחומר ובלבנים (כמו שהיא ברוחניות), בחומר דא ק\"ו ובלבנים דא לבון הלכתא<sup data-n=\"3433\">16</sup>, ועי\"ז יזכו אח\"כ לגאולה העתידה, בדוגמת הגאולה דיציאת מצרים (לאחרי העבודה קשה בחומר ובלבנים גו'), ובני ישראל יוצאים ביד רמה<sup data-n=\"3434\">17</sup>.\nג) <b>והנה</b> גודל העילוי דעסק התורה בזמן הגלות, מבאר בעל ההילולא בסעיף העשירי [העשירי יהי' קודש<sup data-n=\"3435\">18</sup>] דהמשך המאמרים דיום ההילולא, שסעיף זה הוא הסיום והחותם של מאמר השני דההמשך, ד\"ה היושבת בגנים חברים מקשיבים לקולך השמיעני<sup data-n=\"3436\">19</sup> (ע\"פ פרש\"י על הפסוק), אמר הקב\"ה לכנסת ישראל את הפזורה בגולה ורועה בגנים של אחרים כו' ובכ\"ז יושבת בבתי כנסיות ובתי מדרשות לעסוק בתורה, הנה החברים שהם מלאכי השרת (וגם הקב\"ה, כביכול<sup data-n=\"3437\">20</sup>) מקשיבים לקולך.\n<b>וממשיך</b> בהמאמר, דעש\"ז נקראים ישראל צבאות הוי' כמ\"ש<sup data-n=\"3438\">21</sup> ויהי בעצם היום הזה יצאו כל צבאות הוי' מארץ מצרים. דשם זה (צבאות הוי') ניתן לישראל ביציאתם ממצרים דוקא<sup data-n=\"3439\">22</sup>. ויש לבאר קישור הענינים, כי מה שבזמן יציאת מצרים נקראו ישראל צבאות הוי' הוא מצד הניצוצות (הצבאות) שנתבררו בגלות מצרים (כמשי\"ת לקמן<sup data-n=\"3440\">23</sup>). וזהו הקשר דענין מה שישראל נקראים צבאות הוי' לענין היושבת בגנים, כי ע\"י העבודה דכנס\"י בעסק התורה וקיום מצוותי' כשהיא פזורה בגולה ורועה בגנים של אחרים, עי\"ז מבררים את הניצוצות שבגלות, בדוגמת וינצלו<sup data-n=\"3441\">24</sup> את מצרים.<b>והנה</b> נוסף למה שישראל נקראים בשם צבאות הוי' נקראים הם גם צבאות<sup data-n=\"3442\">25</sup> (כמו שמביא בהמאמר הפסוקים<sup data-n=\"3443\">26</sup> ויהי בעצם היום הזה הוציא הוי' את בני ישראל מארץ מצרים על צבאותם, כי בעצם היום הזה הוצאתי את צבאותיכם מארץ מצרים). וההפרש בין צבאות הוי' לצבאות הוא<sup data-n=\"3444\">27</sup>, שצִבאות הוי' (צבאות בחיריק) הוא לשון סמוך, שהצבאות נטפל להוי', וצְבאות (צבאות בשוא) הוא ענין בפני עצמו.\nד) <b>והנה</b> ידוע דמה שישראל נק' אדם הוא על שם אדמה לעליון<sup data-n=\"3445\">28</sup>. שמזה מובן, דמה שישראל נק' (גם) בשם צבאות שייך זה להשם צבאות, שהוא מז' השמות שאינן נמחקין<sup data-n=\"3446\">29</sup>. ויובן זה ע\"פ מ\"ש כ\"ק אדמו\"ר הזקן<sup data-n=\"3447\">30</sup> ששם צבאות נתגלה ע\"י הנביאים, כדאיתא<sup data-n=\"3448\">31</sup> שמיום שברא הקב\"ה את עולמו לא הי' אדם שקראו להקב\"ה צבאות עד שבאתה חנה וקראתו צבאות ואמר הקב\"ה<sup data-n=\"3449\">32</sup> עתיד בן שלך לפתוח בנבואה בשם זה. ועיקר הנבואה בשם זה הי' בנביאים האחרונים שהיו בסוף זמן בית ראשון ובהתחלת הגלות, שרוב נבואתם הי' בשם זה. והנה הגם שדברי הנביאים, דברי קבלה, הם למטה במדריגה מדברי תורה [ואפילו בנוגע לנבואת משה כתיב<sup data-n=\"3450\">33</sup> ולא קם נביא עוד בישראל כמשה, ועאכו\"כ שהם למטה מדברי תורה], אעפ\"כ שם צבאות לא נזכר בתורה כ\"א בנביאים דוקא, ויש מעלה בדברי נביא על דברי תורה. וכמו שמצינו שהעובר על דברי נביא עונשו קשה יותר מעובר על כו\"כ דברי תורה<sup data-n=\"3451\">34</sup>, ומזה מובן שכן הוא גם בנוגע להפגם<sup data-n=\"3452\">35</sup>. ועפ\"ז מבאר כ\"ק אדמו\"ר האמצעי בארוכה<sup data-n=\"3453\">36</sup>, זה שהעונש והפגם של העובר על דברי נביא קשה יותר מעובר על (כו\"כ מ)דברי תורה שייך לזה ששם צבאות נמשך ע\"י הנביאים דוקא.\nה) <b>והענין</b> הוא, הנה פירוש שם צבאות הוא אות הוא בצבא שלו<sup data-n=\"3454\">37</sup>, והיינו דצבא הוא ריבוי נבראים, והשם צבאות, אות הוא בצבא שלו, הוא בחי' האלקות כמו שנמשך בנבראים. וכמבואר בתו\"א<sup data-n=\"3455\">38</sup> בענין שם צבאות, שצבאות הוא לשון חיילות והם גדודי נשמות ומלאכים דבריאה ש(מצד עצמן) אינן אלקות כלל.וזהו ההפרש בין שם צבאות לשאר השמות שאינן נמחקין, דכל השמות מורים על אוא\"ס כמו שהוא באצילות שהוא עולם האחדות, איהו וחיוהי חד איהו וגרמוהי חד<sup data-n=\"3456\">39</sup>, משא\"כ שם צבאות מורה על אוא\"ס כמו שנמשך ומתלבש בבי\"ע, שהם עלמי דפרודא<sup data-n=\"3457\">40</sup> נבראים נפרדים כמ\"ש<sup data-n=\"3458\">41</sup> ומשם יפרד. שלכן יש מ\"ד בגמרא<sup data-n=\"3459\">42</sup> (ולא רק קס\"ד) שצבאות אינו שם קדוש, שלא נקרא צבאות אלא על שם ישראל. וגם לפי מה דקי\"ל<sup data-n=\"3460\">43</sup> דצבאות הוא מהשמות שאינן נמחקין. הנה שם זה קאי על אוא\"ס כמו שנמשך ומתלבש בנבראים. וי\"ל הבי' ע\"פ מה דאיתא בזהר ובתקו\"ז ובכתבי האריז\"ל<sup data-n=\"3461\">44</sup> ששם צבאות הוא בנצח והוד<sup data-n=\"3462\">45</sup>, כי נצח והוד הם לבר מגופא, היינו שענינם הוא (לא בשביל האצילות גופא, כי אם) בכדי להמשיך בעולמות בי\"ע שלמטה מאצילות, וע\"ד הידוע<sup data-n=\"3463\">46</sup> שנו\"ה הן כליות יועצות בכדי להשפיע להבן ולהתלמיד.\nו) <b>וזהו</b> מה ששם צבאות לא נזכר בתורה כ\"א בנביאים דוקא, כי משה רבינו הי' נשמה והנהגה דאצילות, שלכן נקרא משה על שם מן המים משיתיהו<sup data-n=\"3464\">47</sup>, מים חכ' הוא בחי' אצילות. וכן התורה שניתנה ע\"י משה ונקראת על שמו כמ\"ש<sup data-n=\"3465\">48</sup> זכרו תורת משה עבדי היא בחי' אצילות. ולכן לא נזכר בתורה שם צבאות, כי שם צבאות מורה (כנ\"ל) על אוא\"ס כמו שנמשך בנבראים, שלמטה מאצילות. והוא<sup data-n=\"3466\">49</sup> ע\"ד מ\"ש<sup data-n=\"3467\">50</sup> ביהושע ויאמר לא כי אני שר צבא ה' עתה באתי, ואמרו רז\"ל<sup data-n=\"3468\">51</sup> עתה באתי אבל משה רבך לא קיבלו. דבימי משה, פני משה כפני חמה<sup data-n=\"3469\">52</sup>, הי' המשכת בחי' אצילות, וגם הנהגת המלחמות<sup data-n=\"3470\">53</sup> לא היתה ע\"י שר צבא ה' כ\"א כמ\"ש<sup data-n=\"3471\">54</sup> הוי' ילחם לכם. דזהו מה שביציאת מצרים וקריעת ים סוף היו נסים נגלים יוצאים מדרכי הטבע לגמרי שלא הי' לבוש הטבע כלל, לפי שהמלחמה היתה ע\"י שם הוי', בחי' אצילות. משא\"כ לאחרי הסתלקות פני משה כפני חמה וההנהגה היתה ע\"י פני יהושע כפני לבנה<sup data-n=\"3469\">52</sup> הנה אז דוקא בא שר צבא הוי', עתה (דוקא) באתי. והגם שגם אז (ע\"י שהנהגת המלחמה היתה ע\"י שר צבא הוי') היו כמה נסים שלמעלה מהטבע, מ\"מכללות המלחמה היתה קצת בלבושי הטבע, ולא כהמלחמה בימי משה שהיתה למעלה מלבושי הטבע לגמרי, הוי' ילחם לכם. וזהו ענין שם צבאות שנמשך ע\"י הנביאים, אות הוא בצבא שלו, שגם בנבראים דבי\"ע (צבא) יהי' אות הוא ית' ממש בצבא שלו, שגם בבי\"ע יהי' איהו וגרמוהי חד כמו באצילות. וענין זה הוא למעלה מבחי' שר צבא הוי' (שהי' ביהושע), כי שר צבא הוי' הוא מלאך, משא\"כ שם צבאות הוא מז' שמות שאינן נמחקין, כי גם בבי\"ע נעשה איהו וגרמוהי חד. וזהו מה ששם צבאות נתחדש ע\"י הנביאים, כי הנביאים המשיכו שגם בכלים דבי\"ע תהי' התלבשות אוא\"ס ב\"ה בתכלית היחוד, כמו בכלים דאצילות, ועי\"ז נקרא הוא ית' בשם צבאות, כמו שנקרא בהשמות (א-ל, אלקים וכו') שמורים על הכלים דאצילות (לפי שאיהו וגרמוהי חד), כי גם הצבאות (לשון חיילות, גדודי נשמות ומלאכים דבריאה) נעשו חד עמו ית', כמבואר בארוכה בתו\"א&lt;38&gt;.\nז) <b>והנה</b> ענין הנ\"ל בשם צבאות שאיהו וגרמוהי חד גם בבי\"ע, כותב כ\"ק אדמו\"ר הצ\"צ<sup data-n=\"3472\">55</sup> שבע\"ח לא מצינו זה. שמזה משמע שזהו חידושו של כ\"ק אדמו\"ר הזקן, כדמוכח ממה שכ\"ק אדמו\"ר הצ\"צ אינו מציין מקור אחר לזה. ומובן גודל החידוש והעילוי דשם צבאות שנעשה ע\"י עבודת בנ\"י כמו שישראל הם במעמד ומצב דזמן הנביאים (לאחרי הזמן דפני משה כפני חמה), ובפרט כמו שישראל הם במעמד ומצב דזמן נביאים האחרונים שהיו בסוף בית ראשון ותחלת זמן הגלות, ועד\"ז בהזמן שלאח\"ז, שגם בעולמות בי\"ע שמצד עצמם הם נבראים נפרדים [דענין איהו וגרמוהי חד הוא באצילות, עולם האחדות] יהי' איהו וגרמוהי חד כמו באצילות. וי\"ל שזהו הפי' להפס\"ד שצבאות הוא שם קודש ובכ\"ז נקרא ע\"ש צבאות שלו (כבגמרא<sup data-n=\"3473\">56</sup>), ע\"ש ישראל<sup data-n=\"3474\">57</sup>, כי זה שצבאות הוא שם קודש, היינו שגם בבי\"ע איהו וגרמוהי חד, זה נעשה ע\"י העבודה דישראל, כנ\"ל. וזה נעשה ע\"י המשכת אור ממקום עליון ביותר<sup data-n=\"3475\">58</sup>, שנעלה גם מבחינת התורה (כמו שהיתה בגילוי בזמן משה). שהרי בתורה לא נזכר שם צבאות (היינו שמצד בחינת התורה, הענין דאיהו וגרמוהי חד הוא רק באצילות), ובכדי שיהי' איהו וגרמוהי חד גם בבי\"ע צריך להמשיך ממקום עליון יותר.\nח) <b>והנה</b> המשכה זו היא ע\"י עבודת הבירורים. דהנה ידועה תורת הבעש\"ט<sup data-n=\"3476\">59</sup>, שבכל דבר שנמצא ברשותו של ישראל ישנם ניצוצין קדושים השייכים לשרש נשמתו. ובזה מבאר מה שהתורה חסה על ממונם של ישראל<sup data-n=\"3477\">60</sup> (אף שהוא רק ממונם), כי מכיון שהממון (וכן שארי דברים) הוא של ישראל, זה מורה (שהרי כל העניניםהם בהשגחה פרטית) שניצוצות אלו שייכים לשרש נשמתו, והבירור דניצוצות אלו הוא חלק מעבודתו, וע\"י שמבררים את הניצוצות ומזככים ומעלים אותם לשרשם הם מוסיפים עילוי גם בו. דכמו\"כ הי' בגלות מצרים, שע\"י וינצלו את מצרים שעשאוה כמצולה שאין בה דגים וכמצודה שאין בה דגן<sup data-n=\"3478\">61</sup> שביררו את הניצוצות השייכים לעלמא דאתכסיא (כמצולה שאין בה דגים) והניצוצות השייכים לעלמא דאתגליא (כמצודה שאין בה דגן), עי\"ז נעשה עילוי גם בישראל. וכמו שמבאר כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"3479\">62</sup> בארוכה בענין ויהי בשלח פרעה את העם שהי' משלח פארות וענפים ועושה פרי למעלה את העם, שע\"י הניצוצות שביררו בגלות מצרים נעשה בהם תוספות וריבוי. דזהו מ\"ש (גבי גלות מצרים) וזרעתי' לי בארץ<sup data-n=\"3480\">63</sup>, דענין הזריעה הוא כמרז\"ל<sup data-n=\"3481\">64</sup> כלום אדם זורע כור<sup data-n=\"3482\">65</sup> אלא כדי להוציא כמה כורין, היינו, דמה שישראל נזרעו בגלות מצרים הוא בשביל ההוספה שנעשה בהם ע\"י בירור הניצוצות. כמו שמבאר כ\"ק אדמו\"ר מהר\"ש בארוכה כמה פרטים בענין ההוספה שנעשה ע\"י בירור הניצוצות.\nט) <b>וזהו</b> מ\"ש ויהי בעצם היום הזה יצאו כל צבאות הוי' מארץ מצרים ולאח\"ז כתיב ויהי בעצם היום הזה הוציא הוי' את בנ\"י מארץ מצרים על צבאותם, צבאות הוי' לשון סמוך הם הצבאות שנתבררו בגלות מצרים ונתעלו ליכלל בשם הוי', שלכן נק' צבאות הוי' לפי שהם טפלים וסמוכים ונכללים בשם הוי'<sup data-n=\"3483\">66</sup>. ומצד הניצוצות שנתבררו ע\"י ישראל, גם ישראל נק' צבאות הוי'. ויתירה מזו – הוציא הוי' את בני ישראל גו' <i>על</i> צבאותם הוא זה שישראל הם למעלה מבחי' הניצוצות שנתבררו<sup data-n=\"3483\">66</sup>. דמכיון שישראל הם המבררים את הניצוצות הרי הם למעלה מהם.\n<b>וזוהי</b> השייכות דצבאות הוי' ועל צבאותם להשם צבאות, דע\"י העבודה דבירור הניצוצות והתכללותם בהוי', צבאות הוי', שע\"י עבודה זו נעשים ישראל על צבאותם, למעלה מבחי' הניצוצות, הנה עי\"ז ממשיכים ריבוי אור ממקום עליון ביותר (שלמעלה מבחינת התורה כמו שהיא בגילוי), ואור זה בוקע את כל הפרסאות והמסכים שבין אצילות לבי\"ע, עד שגם בבי\"ע נעשה איהו וגרמוהי חד כמו באצילות.\nי) <b>וביאור</b> הענין (השייכות דצבאות הוי' לשם צבאות) בעומק יותר, הנה שם צבאות הוא בנצח והוד. ומבאר כ\"ק מו\"ח אדמו\"ר בההמשך דיום ההילולא<sup data-n=\"3484\">67</sup>, שמדת הנצח נטוע ומושרש בעצם הנפש, ובשביל נצחון המלחמה מתגלה מעצם הנפש. ולכן ע\"י העבודה דמדת הנצח, נצחון המלחמה (עם נה\"ב), נמשך ומתגלה מעצמות אוא\"ס, כמבואר בארוכה בההמשך, ובארוכה יותר (עם כמה פרטים נוספים)בדרושי כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"3485\">68</sup>, עד לענין צדקת פרזונו בישראל<sup data-n=\"3486\">69</sup>, פרזונו לשון פרזות ע\"ד מ\"ש<sup data-n=\"3487\">70</sup> פרזות תשב ירושלים בלי חומה, למעלה ממדוה\"ג. ועפ\"ז יובן מה שע\"י העבודה דצבאות הוי' ממשיכים שם צבאות, דהנה ידועה תורת הרב המגיד<sup data-n=\"3488\">71</sup> (בענין במי נמלך בנשמותיהן של צדיקים<sup data-n=\"3489\">72</sup>), דישראל גם קודם שנבראו (קודם כל סדר ההשתל' שאודותו נמלך) הי' נחקק צורתם בו ית'. וע\"י עבודת בנ\"י נמשך ומתגלה ענין זה. ולכן ע\"י העבודה דצבאות הוי', נמשך שם צבאות, כי שם זה הוא (כנ\"ל) בנצח והוד, וכמו שמבאר אאמו\"ר<sup data-n=\"3490\">73</sup> בארוכה שהאותיות דשם צבאות וסדרן (צ\"ב, ב' יודי\"ן דאל\"ף, ו\"ת) מורים על נצח והוד [בפרדס<sup data-n=\"3491\">74</sup> ובכ\"מ בקבלה איתא דשם צבאות הוא גם ביסוד, אבל מה שנוגע כאן הוא ענין שם צבאות כמו שהוא בנצח והוד], ומכיון שצורתם של ישראל חקוקה בו ית' (כנ\"ל), לכן ע\"י העבודה דצבאות הוי', העבודה דנצח, נעשה ענין שם צבאות שהוא בנצח (והוד). והיינו שע\"י העבודה דנצחון המלחמה, נמשך ומתגלה מעצמות אוא\"ס, וע\"י המשכה זו נעשה איהו וגרמוהי חד (גם) בבי\"ע.\n<b>וזה</b> נותן כח על עבודת הבירורים בזמן הגלות, און מיטנעמען כל הענינים, כלי כסף וכלי זהב ושמלות<sup data-n=\"3492\">75</sup>, בגאולה העתידה שתהי' ביד רמה (כמו שהיתה הגאולה דיציאת מצרים, כמ\"ש<sup data-n=\"3493\">76</sup> כימי צאתך מארץ מצרים אראנו נפלאות) שע\"י מעשינו ועבודתינו במשך זמן הגלות<sup data-n=\"3494\">77</sup> ובפרט בעקבתא דמשיחא יהי' ובני ישראל יוצאים ביד רמה לקבל פני משיח צדקנו, במהרה בימינו ממש.\n**********",[["3417","*","יצא לאור בשעתו, \"<i>עש\"ק ט\"ו בשבט ה'תש\"מ</i>\"."],["3418","1","שה\"ש ה, א."],["3419","2","שהש\"ר שם. וש\"נ."],["3420","3","ראה זח\"ג כ, ב. עה, רע\"א."],["3421","4","ויק\"ר פכ\"ט, יא."],["3422","5","תהלים לז, כט."],["3423","6","יתרו יט, כ."],["3424","7","אף שבערך ביהמ\"ק נקרא אוהל (שמואל-ב ז, ו. שהש\"ר פ\"א טז [ג]), ואדרבא – דוקא מעשה משה נצחיים (סוטה ט, א)."],["3425","8","תרומה כה, ח."],["3426","9","שם כו, טו."],["3427","10","סוטה ג, א."],["3428","11","של\"ה סט, א. רא, א. שכה, ב. שכו, ב. ובכ\"מ."],["3429","12","תניא רפי\"ז."],["3430","13","אחרי יח, ה."],["3431","14","תורה אור שמות מט, א ואילך. אוה\"ת שמות ע' ח ואילך. ובכ\"מ."],["3432","15","שמות א, יד."],["3433","16","זח\"ג קנג, א."],["3434","17","בשלח יד, ח."],["3435","18","לשון הכתוב – בחוקותי כז, לב. וראה זח\"ב רעא, א."],["3436","19","שה\"ש ח, יג."],["3437","20","ראה בתחלת המאמר שם ממד\"ר: אמר הקב\"ה <i>אני</i> ופמליא שלי כו'."],["3438","21","בא יב, מא."],["3439","22","כמפורש בההמשך רפי\"א."],["3440","23","סעיף ט, מתו\"א בא ס, ג."],["3441","24","בא שם, לו. ובתו\"א שם [ובכ\"מ. וראה גם לקמן בפנים ס\"ח] שהו\"ע בירור הניצוצות שהיו במצרים."],["3442","25","כמובן גם ממה שמבאר בהמאמר (פ\"י) ג' הפירושים דצבא (צבא סתם). ובהקיצור שם: נק' ישראל <i>צבאות</i>."],["3443","26","בא שם, נא. יז."],["3444","27","ראה תו\"א שם. תו\"ח שמות קמא, ב [בהוצאה החדשה – בא ח\"א קטו, א]."],["3445","28","של\"ה כ, ב. שא, ב. ובכ\"מ."],["3446","29","שבועות לה, סע\"א (ושם ע\"ב שכן הלכה). רמב\"ם הל' יסוה\"ת פ\"ו ה\"ב. טושו\"ע יו\"ד סרע\"ו ס\"ט. שו\"ע אדה\"ז חאו\"ח ספ\"ה ס\"ג."],["3447","30","תו\"א ר\"פ בא."],["3448","31","ברכות לא, ב."],["3449","32","תו\"א שם."],["3450","33","ברכה לד, י. וראה רמב\"ם שם פ\"ז ה\"ו."],["3451","34","שהעובר על דברי נביא חייב מיתה ביד\"ש (רמב\"ם שם פ\"ט ה\"ב), משא\"כ בכו\"כ מדברי תורה."],["3452","35","שהרי העונש הוא לפי ערך הפגם (תניא פכ\"ד בהגהה)."],["3453","36","תו\"ח שם, סע\"א ואילך."],["3454","37","אוה\"ת בא ע' שכט. ד\"ה בעצם היום גו' פר\"ת סעיף ד'. ובחגיגה טז, רע\"א: <i>אדון</i> הוא בצבא שלו."],["3455","38","ר\"פ בא (ס, ב)."],["3456","39","תקוני זהר בהקדמה."],["3457","40","תו\"א בראשית ו, ב. ובכ\"מ."],["3458","41","בראשית ב, י."],["3459","42","שבועות לה, ב."],["3460","43","שבועות שם. מקומות שבהערה 29."],["3461","44","זח\"ג יא, ב. אד\"ז (בזח\"ג) רצו, א. תקו\"ז תי\"ח. ועוד (הובאו בפרדס שער השמות פי\"ב ובי\"נ למאו\"א מע' צבאות). ע\"ח שער השמות פ\"ג. פ\"ו. ועוד."],["3462","45","כמובא גם בההמשך רפי\"א משערי אורה לר\"י גיקטליא."],["3463","46","אגה\"ק סט\"ו (קכד, ב)."],["3464","47","שמות ב, י."],["3465","48","מלאכי ג, כב. וראה שבת פט, א."],["3466","49","ראה אוה\"ת וד\"ה בעצם היום שבהערה 37."],["3467","50","יהושע ה, יד."],["3468","51","ב\"ר פצ\"ז, ג. תנחומא משפטים יח. זח\"ג רפו, ב."],["3469","52","ב\"ב עה, א. ובכ\"מ."],["3470","53","אף שמלחמה (בכלל) שייכת לשם צבאות (שמו\"ר פ\"ג, ו)."],["3471","54","בשלח יד, יד."],["3472","55","אוה\"ת שם ס\"ע שכח."],["3473","56","חגיגה טז, א. וראה לעיל הערה 37."],["3474","57","שנקראו (בפרשתנו) צבאות."],["3475","58","ראה תו\"א שם (ס, ג), \"שכדי להמשיך בחי' צבאות הוצרך להמשיך מבחי' על הוי' היינו למעלה משם הוי'\"."],["3476","59","כתר שם טוב סי' ריח. צוואת הריב\"ש סי' קט."],["3477","60","ר\"ה כז, א. וש\"נ."],["3478","61","בא יב, לו. ברכות ט, ב."],["3479","62","בסה\"מ תרכ\"ז ד\"ה ויהי בשלח פרעה – ביאור על בשלח פרעה שבתו\"א."],["3480","63","הושע ב, כה."],["3481","64","פסחים פז, ב."],["3482","65","כ\"ה בתו\"א (ר\"פ בשלח) ובסה\"מ תרכ\"ז (ס\"ע קט). ובפסחים שם: <i>סאה</i>."],["3483","66","תו\"א בא ס, ג."],["3484","67","פי\"א ואילך."],["3485","68","ד\"ה בעצם היום גו' פר\"ת [סה\"מ פר\"ת ע' רמא ואילך]. והביאנו לציון תרע\"א [סה\"מ אעת\"ר ע' קעז ואילך]."],["3486","69","שופטים ה, יא."],["3487","70","זכרי' ב, ח."],["3488","71","או\"ת ב, סע\"ג. וראה שם א, א. לקו\"א בתחלתו."],["3489","72","רות רבה רפ\"ב. ב\"ר פ\"ח, ז."],["3490","73","לקוטי לוי\"צ לזהר אחרי ע' רפד."],["3491","74","שער השמות פי\"ב (קרוב לסופו). וראה גם מאו\"א שם ובי\"נ למאו\"א שם."],["3492","75","בא יב, לה."],["3493","76","מיכה ז, טו."],["3494","77","ראה תניא רפל\"ז."]]],[1500370047,"<h3>בס\"ד. ש\"פ בשלח, י\"א שבט ה'תשמ\"ח<sup data-n=\"3495\">*</sup></h3>\n<b>באתי</b> לגני אחותי כלה<sup data-n=\"3496\">1</sup>, ומביא ע\"ז כ\"ק מו\"ח אדמו\"ר בעל ההילולא בהמאמר דיום ההסתלקות ויום ההילולא שלו<sup data-n=\"3497\">2</sup>, דאיתא במדרש רבה (במקומו) לגני לגנוני, למקום שהי' עיקרי בתחלה, דעיקר שכינה בתחתונים היתה, אלא שע\"י הענינים הבלתי רצויים נסתלקה השכינה מלמטה למעלה עד רקיע השביעי, ואח\"כ [והותחל תיכף לאחרי זה] עמדו שבעה צדיקים והורידו את השכינה מלמעלה למטה, עד שבא משה שהוא השביעי (דכל השביעין חביבין<sup data-n=\"3498\">3</sup>) והורידה למטה בארץ. וענין זה (ירידת והמשכת השכינה למטה בארץ) נעשה בעיקר ע\"י המשכן שעשה משה [ועד דהמשכן נק' מעשה משה<sup data-n=\"3499\">4</sup>], כמ\"ש<sup data-n=\"3500\">5</sup> ועשו לי מקדש ושכנתי בתוכם.\nב) <b>וממשיך</b> בהמאמר<sup data-n=\"3501\">6</sup>, שהמשכת עיקר שכינה למטה (ושכנתי בתוכם) נעשית ע\"י העבודה דאתהפכא חשוכא לנהורא. וזהו מה שבמשכן כתיב<sup data-n=\"3502\">7</sup> ועשית את הקרשים למשכן, קרש הוא אותיות שקר, וע\"י שמהפכים את השקר דעולם לקרש המשכן, עי\"ז נעשה ושכנתי בתוכם, המשכת עיקר שכינה בתחתונים. [ויש להוסיף, דזהו גם מה ששקר אותיות קשר<sup data-n=\"3503\">8</sup>, כי העבודה שעל ידה נעשה ושכנתי בתוכם היא לא באופן שהאדם העובד פורש עצמו מעניני העולם, כי אם, שיש לו קשר עם העולם<sup data-n=\"3504\">9</sup>, ומהפך את העולם גופא לקדושה, אתהפכא חשוכא לנהורא], וזהו<sup data-n=\"3505\">10</sup> גם מה שהמשכן הי' מעצי שטים<sup data-n=\"3502\">7</sup>, שטים מלשון שטות<sup data-n=\"3506\">11</sup>, היינו שטות דלעו\"ז, והעבודה שעל ידה נעשה ושכנתי בתוכם היא להפוך את השטות דלעו\"ז לשטות דקדושה. דבכדי שיהי' ושכנתי בתוכם המשכת עיקר שכינה למטה [<i>דעיקר</i> שכינה הוא עצמות אוא\"ס שלמעלה משייכות לעולמות<sup data-n=\"3507\">12</sup>] אינו מספיק העבודה שע\"פ טעם ודעת, וצריכה להיות העבודה דשטות דקדושה שלמעלה מטעם ודעת. כמאמר רז\"ל<sup data-n=\"3508\">13</sup> אהני לי' שטותי' לסבא, דמאמר זה הוא בנוגע לאמורא שהי' מגדולי ישראל (גםלפני זה) ועד שנקרא בשם סבא, וע\"י עבודתו באופן של שטות דקדושה שלמעלה מטו\"ד נתעלה עוד יותר, <i>אהני</i> לי' שטותי'.\nג) <b>והנה</b> ידוע<sup data-n=\"3509\">14</sup> שהציווי ועשו לי מקדש הוא גם על המקדש, בית ראשון בית שני, וגם ביהמ\"ק השלישי שיבנה במהרה בימינו. ומזה מובן, דכמו שהמשכת עיקר שכינה במשכן היתה ע\"י העבודה שלמעלה ממדידה והגבלה, שטות דקדושה שלמעלה מטעם ודעת, עד\"ז הוא בנוגע להמשכת עיקר שכינה בביהמ\"ק, שזה נעשה ע\"י העבודה דשטות דקדושה שלמעלה ממדידה והגבלה. דע\"י מעשינו ועבודתינו במשך זמן הגלות באופן דשטות דקדושה שלמעלה מטעם ודעת, עי\"ז ועשו לי, עשיית ביהמ\"ק השלישי שיבנה במהרה בימינו, שיהי' נעלה עוד יותר מהמשכן וביהמ\"ק הא' והב', מקדש אד' כוננו ידיך<sup data-n=\"3510\">15</sup>.\nד) <b>וזהו</b> מה שישראל נק' בשם צבאות הוי'<sup data-n=\"3511\">16</sup> במשך כל הדורות, דכאו\"א מישראל הוא חייל בצבאות השם, שיוצא צבא למלחמה, לכבוש את העולם ולעשותו דירה לו ית'. וזה מה שישראל נק' בשם צבאות ה' (צבא דייקא) הוא להורות, שעבודתם צריכה להיות באופן שלא יתחשבו עם חשבונות שע\"פ טו\"ד, שטות דקדושה שלמעלה מטו\"ד, בדוגמת צבא כפשוטו.\nה) <b>וממשיך</b> בהמאמר<sup data-n=\"3512\">17</sup>, דכמו שבמלחמה בגשמיות, בכדי לנצח את המלחמה מבזבז המלך את כל האוצרות שנקבצו במשך כמה שנים מדור אחר דור<sup data-n=\"3513\">18</sup>, דהגם שע\"ד הרגיל הנה לא רק שאין משתמשים בהם (אפילו לצורך גדול) אלא יתירה מזו, שהם כמוסים וגנוזים מעין כל רואה, ומ\"מ בכדי לנצח את המנגד, הנה לא רק שמשתמשים בהאוצרות אלא שגם מבזבזים אותם, דבזבוז הוא למעלה מחשבון מדידה והגבלה, והטעם לזה הוא כי הנצח מושרש בעצם הנפש דשם (בעצם הנפש) אין שייך שום חשבונות, עד\"ז הוא גם למעלה, שבכדי שצבאות ה' ינצחו את המלחמה, לכבוש את העולם ולעשותו דירה לו ית', נותנים להם בחי' האוצר שלמעלה, ולא עוד, אלא שנתינת האוצרות להם הוא באופן דבזבוז, למעלה מחשבון. והגם שגם בנתינה (ע\"ד הרגיל) אמרו<sup data-n=\"3514\">19</sup> כל הנותן בעין יפה נותן, הרי גם \"עין יפה\" הוא תואר של מדידה והגבלה, משא\"כ כשהנתינה היא באופן דבזבוז, אין בה הגבלות. והטעם על זה (שבכדי שהצבאות ה' ינצחו את המלחמה, נותנים להם את האוצרות ובאופן דבזבוז) הוא, כי שרש הנצח הוא בפנימיות הכתר<sup data-n=\"3515\">20</sup>, דשם (בפנימיותהכתר) אין שייך שום חשבונות. והגם שנתינת האוצרות ובאופן דבזבוז היא ע\"י השרים ומפקדי המלחמה, נשיאי ישראל שבכל דור, עד לנשיא דורנו בעל ההילולא, הרי עיקר הכוונה בזה הוא שהאוצרות יומשכו ויותנו להאנשי חיל, צבאות הוי', שעל ידם נעשה הנצחון בפועל<sup data-n=\"3516\">21</sup>. וזהו גם מה שהנצחון שיהי' ע\"י העבודה דצבאות ה' (בביהמ\"ק השלישי) הוא נצחון נצחי (הוי' ימלוך לעולם ועד<sup data-n=\"3517\">22</sup>), דמכיון שהנתינת כח על עבודתם היא מפנימיות הכתר, דבפנימיות הכתר אין שייך ענין השינויים, לכן גם העבודה דהצבאות ה' היא בתוקף חזק בלי שינויים, ובמילא גם הנצחון שע\"י העבודה הוא נצחי שאין שייך בו הפסק ושינוי.\nו) <b>וממשיך</b> בהמאמר בפרק ח\"י (הפרק שלומדים בשנה זו<sup data-n=\"3518\">23</sup> בפעם השני', כפלים לתושי'<sup data-n=\"3519\">24</sup>), דביאור הענין (ששרש הנצח הוא בפנימיות הכתר) יובן ע\"פ מ\"ש<sup data-n=\"3520\">25</sup> וגם נצח ישראל לא ישקר ולא ינחם כי לא אדם הוא להנחם, דזה שנצח ישראל לא ינחם הוא לפי ששרש הנצח הוא בבחי' לא אדם. דענין ניחומין וחרטה שייך רק בבחי' אדם. והטעם על זה הוא, כי אדם הוא מוחין ומדות, היינו מדות שע\"פ שכל ושכל השייך למדות, ולכן שייך בו שינוי, דמכיון שהמדות דאדם הם ע\"פ שכל, לכן, כשנעשה שינוי בהשכל משתנים המדות. ועד\"ז הוא גם ברצון שלמעלה מהשכל, שגם הוא בכלל ציור אדם, מוחין ומדות. דברצון יש המדות שבו והטעם שבו, טעם כמוס. ומכיון ששכל (גם טעם כמוס) הוא דבר המשתנה, לכן, כשנעשה, שינוי בטעם הכמוס, משתנה הרצון (מדות שברצון). דכל זה הוא בחיצוניות הרצון, שדוגמתו למעלה הוא חיצוניות הכתר. משא\"כ בפנימיות הכתר, דאין שם בחי' מדות ולא טעם כמוס, אין שייך שם ענין הניחומין וחרטה. ויש לומר, דזה שמוסיף בהמאמר דאין שם בחי' מדות [אף שענין הניחומין וחרטה הוא ע\"י השינוי שנעשה בהטעם, וזה שבפנימיות הרצון (הכתר) אין שייך ניחומין וחרטה הוא, לכאורה, מצד זה דאין שם טעם כמוס] הוא, כי עי\"ז מובן יותר הענין דלא אדם הוא להנחם. דלא רק שבפנימיות הכתר אין סיבה לענין הנחמה והשינוי [דברצון שיש לו טעם, מכיון שטעם הוא דבר המשתנה, הרי שינוי הטעם הוא סיבה לשינוי הרצון, משא\"כ רצון שלמעלה מהטעם אין סיבה שישתנה], אלא יתירה מזו, שאינו גם בגדר שינוי. דבבחינת המדות, מכיון שבמדות ישנם ב' קוין, חסד ודין, שייך שיהי' שינוי מחסד לדין ומדין לחסד, משא\"כ בפנימיות הכתר, דאין שם בחי' מדות,היינו שהוא למעלה מציור קוין, דלית שמאלא בהאי עתיקא<sup data-n=\"3521\">26</sup> (כמובא בהמאמר), הרי אין שייך כלל שישתנה לדין (שמאל), מכיון דשם לית שמאלא<sup data-n=\"3522\">27</sup>, וכולא ימין<sup data-n=\"3521\">26</sup>. וזהו מ\"ש וגם נצח ישראל גו' לא ינחם כי לא אדם הוא להנחם, דנצח ישראל הוא בבחי' לא אדם, פנימיות הכתר<sup data-n=\"3523\">28</sup>. וכדאיתא בזהר<sup data-n=\"3524\">29</sup> עה\"פ<sup data-n=\"3525\">30</sup> הנה לא ינום ולא יישן שומר ישראל, שהוא בחינת עין אחת (שלמעלה משתי עינים<sup data-n=\"3526\">31</sup>), עין אחת דעתיקא, דבבחינה זו אין שייך שינה, עינא פקיחא דלא נאים.\nז) <b>והנה</b> הגם שעתיק הוא למעלה מציור אדם (למעלה מקוין), מ\"מ, מזה שהענין דעתיק (למעלה מקוין) בא בהמאמר בהמשך למה שמבואר לפנ\"ז (באותו הפרק) הענין דאדם (שאדם הוא מוחין ומדות), היינו, דענין עתיק (עתיק מלשון נעתק ונבדל<sup data-n=\"3527\">32</sup>) הוא שנעתק מציור אדם, מובן מזה שגם עתיק יש לו שייכות לבחי' אדם. ויתירה מזו, דמזה שמבאר (בתחלת הפרק) הענין דאדם גם באדם התחתון, מובן, דענין עתיק שייך גם לאדם התחתון, דהגם שעתיק הוא דרגא תחתונה שבא\"ס, כדאיתא בע\"ח<sup data-n=\"3528\">33</sup>, מ\"מ, הוא שייך גם לאדם התחתון כנ\"ל. וענין זה (שעתיק שייך גם לאדם התחתון) הוא לא רק בבחי' עתיק יומין, אלא גם בעתיק (סתם). דהגם שעתיק (סתם) הוא למעלה מעתיק יומין<sup data-n=\"3529\">34</sup>, דפירוש עתיק יומין הוא שנעתק מיומין, היינו שיש לו שייכות ליומין אלא שנעתק מהם, משא\"כ עתיק (סתם) הוא למעלה מיומין<sup data-n=\"3530\">35</sup>, מ\"מ, מכיון שנקרא בשם עתיק, דפירוש עתיק הוא שנעתק, בהכרח לומר, שישנו ענין שממנו הוא נעתק. ולהעיר מהמבואר בלקוטי לוי\"צ<sup data-n=\"3531\">36</sup> שקו\"ט בענין בחינות אלו עתיק יומין ועתיקא דעתיקין וכו', דהשקו\"ט שם שייך להמבואר לעיל. עיי\"ש. ומזה שמבאר בהמאמר הענין דאדם גם באדם התחתון, מובן, שהענין שעתיק נעתק ממנו, היינו שיש לו איזו שייכות אליו, הוא גם באדם התחתון. ויתירה מזו, דענין זה (שעתיק שייך גם לאדם התחתון) הוא בכל הדרגות דעתיק, גם בפנימיות עתיק, דהגם שבנוגע לפנימיות עתיק מבאר הצ\"צ שהוא בחי' א\"ס ממש<sup data-n=\"3532\">37</sup>, ו\"עד שהוא נקרא עצמותו ית'\"<sup data-n=\"3533\">38</sup>, מ\"מ מכיון שנקרא בשם עתיק שפירושו נעתק, בהכרח שיש ענין שממנו הוא נעתק, שבענין זה נכלל (כנ\"ל) גם אדם התחתון.ח) <b>וכן</b> מובן גם ממ\"ש אדמו\"ר האמצעי בתורת חיים<sup data-n=\"3534\">39</sup> בביאור הענין דעתיק שלמעלה מקוין (עין אחת שלמעלה מהתחלקות חו\"ג), שמקדים<sup data-n=\"3535\">40</sup> ענין התחלקות חו\"ג שמצד המוחין (הקוין דחו\"ג שבבחי' אדם), ושמצד המוחין אפשר שאותה הסברא תשתנה ותתהפך (וכמה פעמים) מזכות לחוב ומחוב לזכות (ענין נחמה ושינוי שבבחי' אדם), ושענין זה שבבחי' אדם (ענין ההתחלקות דחו\"ג וענין הנחמה ושינוי) הוא גם באדם התחתון, ויתירה מזו, שכל זה מבואר שם עה\"פ<sup data-n=\"3536\">41</sup> ויאמר ה' גו' ארדה נא ואראה הכצעקתה (דסדום), הירידה דאדם העליון לראות צעקתה דסדום [שמזה מובן, שגם הדוגמא לזה מאדם התחתון הוא גם כמו שהוא נמצא במצב ירוד ביותר], ולאחרי הקדמה זו בא הביאור בענין עתיק, היינו דענין עתיק הוא שנעתק מבחינה זו דאדם שמבאר לפנ\"ז, דמזה מובן, שענין עתיק שייך גם לאדם התחתון, גם כמו שהוא במצב ירוד ביותר. וכן מובן גם ממה שמבאר אדמו\"ר מהר\"ש בהמשך מים רבים<sup data-n=\"3537\">42</sup> בענין השינוי שנעשה ע\"י וירח את ריח הניחוח אחר המבול<sup data-n=\"3538\">43</sup>, וענין עתיק הוא שנעתק מזה. ועוד ענין בזה, שבמים רבים שם, בהמשך הענין דעתיק, מבואר (לא רק בענין קוצו של יו\"ד, ואפילו לא רק בענין יו\"ד, אלא גם) בענין ה' דשם הוי'. וכן מובן ממ\"ש אדמו\"ר (מהורש\"ב) נ\"ע בהמשך תער\"ב<sup data-n=\"3539\">44</sup> דעתיק לשון זקן<sup data-n=\"3540\">45</sup> לפי שבחי' עתיק (שאין בו שינויים) הוא דוגמת זקן כפשוטו [דכמו שזקן אינו מתפעל (ומשתנה) מדבר שנגד רצונו, עד\"ז הוא בעתיק, שאין שייך בו התפעלות ושינוי], דמזה שמדמה עתיק לזקן כפשוטו (שבאדם התחתון), מובן שזהו ענין טבעי שעתיק שייך באדם התחתון. ויתירה מזו, דזה שעתיק שייך לאדם התחתון הוא גם לנער (וגם לפני זה), מכיון שאז בכחו להיות זקן [ועד שע\"י אופן ההנהגה בנערותו, תהי' כן (במילא) גם ההנהגה בזקנותו, כמ\"ש<sup data-n=\"3541\">46</sup> חנוך לנער גו' גם כי יזקין לא יסור ממנה], ואינו אלא מחוסר זמן.\nט) <b>ויש</b> להוסיף, דעי\"ז שהנשיאים ועד כ\"ק מו\"ח אדמו\"ר בעל ההילולא כתבו וביארו ענינים הנ\"ל שיהי' מובן שהענין דעתיק שייך לאדם התחתון, הנה עי\"ז ניתוסף עוד יותר בהנתינת כח לכאו\"א שיהי' לו שייכות להענין דעתיק, ובכל הדרגות שבו, עד לפנימיות עתיק. ובפרט ע\"פ הידוע בנוגע לאדמו\"ר הזקן<sup data-n=\"3542\">47</sup>, דמזה מובן שכן הוא בהנשיאים שלאחריו, ממלאי מקומו, דבעת שאמר או כתב ע\"ד איזה ענין ומדריגה, הנה לא זו בלבד שהוא עצמו הי' אז במצב זה, אלא שגם פעל גם על החסידים.יו\"ד) <b>ויובן</b> זה (השייכות דעתיק לאדם התחתון) ע\"פ תורת הרב המגיד<sup data-n=\"3543\">48</sup> על מרז\"ל<sup data-n=\"3544\">49</sup> דע מה למעלה ממך, דכל מה שלמעלה הכל הוא ממך. ופירש אדמו\"ר הזקן<sup data-n=\"3545\">50</sup>, דזה מה שכל מה שלמעלה הכל הוא ממך, הוא (לא רק שע\"י עבודת האדם נעשה תוספות אור, וכיו\"ב, אלא) <i>שהמציאות</i> שלמעלה נעשית ע\"י עבודת האדם. והנה מלשון הרב המגיד \"<i>שכל</i> מה שלמעלה <i>הכל</i> הוא ממך\" מובן שזהו לא רק בנוגע לספירות אלא גם בנוגע לעתיק [ואדרבה, מכיון שעתיק הו\"ע עיקרי, הרי בנוגע לעתיק זהו ביותר], וגם בנוגע הענינים שלמעלה מעתיק. והענין הוא, דכל הענינים שלמעלה, התהוותם היא יש מאין. ולא רק הענינים שאחרי הצמצום, שנתהוו ע\"י הצמצום, אלא גם הענינים שלפני הצמצום, גם האורות הכי נעלים, מכיון שהם ענין שאינו עצמות, הרי <i>נתהוו</i> מהעצמות. ובלשון הרמב\"ם<sup data-n=\"3546\">51</sup>, שכל הנמצאים [דבכל הנמצאים נכללו גם אורות הכי נעלים] לא נמצאו אלא מאמתת המצאו. דאמיתת המצאו הוא העצמות, שמציאותו מעצמותו ואינו עלול מאיזה עילה שקדמה לו ח\"ו<sup data-n=\"3547\">52</sup>, וממנו נמצאו (נתהוו) כל הנמצאים. ואופן התהוותם מהעצמות הוא ע\"י עבודת האדם. והטעם לזה הוא, כי כל הענינים שלמעלה, הם בבחי' ירידה מאור פניו ית'<sup data-n=\"3548\">53</sup> (ואין בהם עלי' מצד עצמם), וכוונת הירידה היא בכדי שיהי' התהוות עוה\"ז התחתון, שאין תחתון למטה ממנו, שבו דוקא (בעוה\"ז), ע\"י עבודת האדם, מתחיל ענין העלי'. ועי\"ז נשלמה הכוונה דהתהוות הענינים שלמעלה, שגם בהם נעשה עלי'<sup data-n=\"3549\">54</sup>. ולכן, ההתהוות דכל הענינים שלמעלה, מה שהם מתהווים תמיד מאין ליש, כתורת הבעש\"ט הידועה<sup data-n=\"3550\">55</sup> שההתהוות היא תמיד בכל רגע ורגע, היא ממך, ע\"י עבודת האדם.\nיא) <b>ועפ\"ז</b> יובן גם מה שמבאר הצ\"צ<sup data-n=\"3551\">56</sup> עה\"פ<sup data-n=\"3552\">57</sup> כי א-ל דעות הוי' ולא נתכנו עלילות, דהקרי הוא ולו בוא\"ו, והכתיב הוא ולא באל\"ף, דדעות לשון רבים הם דעת עליון ודעת תחתון, דדעת תחתון יש בו התחלקות חו\"ג משא\"כ דעת עליון הוא למעלה מהתחלקות, כי ד\"ע הוא בעתיק שאין שם דין. וענין ולא באל\"ף ולא בוא\"ו הוא בשתי דיעות אלו. ולו בוא\"ו הוא בדעת תחתון, ששם נתכנו עלילות, ולא באל\"ף הוא בדעת עליון, דשם <i>לא</i> נתכנו עלילות, שאין מעשה בנ\"א (עלילות) נוגע שם. ומבאר שם<sup data-n=\"3553\">58</sup>, דבאמת הקרי והכתיב הכל אחד. ויש לומר הכוונה בזה, שמכיון שגם עתיק שלמעלה מקוין נעשה ע\"י עבודת האדם (כנ\"ל), לכן גם העניןדולא נתכנו (ולא באל\"ף) שייך לאדם, גם לאדם התחתון, ולו נתכנו (ולא בוא\"ו). ויש לקשר ענין זה (החיבור דדעת עליון שבבחי' לא אדם עם דעת תחתון שבבחי' אדם) עם זה שמבאר הצ\"צ שם<sup data-n=\"3554\">59</sup> בפירוש א-ל דעות הוי', דא-ל הוי' מחבר שתי הדיעות. ויש לומר, דזהו גם מה שעבודת האדם היא בכלל בג' הענינים דסור<sup data-n=\"3555\">60</sup> מרע ועשה טוב בקש שלום<sup data-n=\"3556\">61</sup> [דמכיון שאדם הוא בציור ג' קוין, לכן גם עבודתו היא בג' קוין], דג' הקוין דסור מרע ועשה טוב שייכים לשתי הדיעות<sup data-n=\"3557\">62</sup>, והעבודה דבקש שלום [דשלום הוא תורה<sup data-n=\"3558\">63</sup>, קו האמצעי] הוא החיבור דשתי הדיעות, החיבור דלא אדם עם אדם. וגם ענין זה שייך להאדם, מכיון שזה נעשה ע\"י עבודתו.\nיב) <b>והנה</b><b>,</b> כאמור לעיל, דע\"י שהנשיאים גילו לנו כל זה, ניתוסף עוד יותר בהנתינת כח לכאו\"א מהצבאות הוי' [ובפרט צבאות הוי' דדורנו זה, דור השביעי מאדמו\"ר הזקן, ודור התשיעי מהבעש\"ט, ומיד נעשה דור זה (דור האחרון דהגלות) דור הגאולה, דור העשירי שהולך לקראת משיח צדקנו], שעבודתו תהי' בתוקף בלי שינויים (מכיון שכאו\"א מישראל שייך לעתיק שאין שייך בו שינוי), דהגם שעבודת האדם צריכה להיות בג' קוין (סור מרע ועשה טוב בקש שלום) מ\"מ צריך שיהי' בזה התוקף שמצד עתיק שלמעלה מקוין (ע\"ד שנת\"ל בענין החיבור דאדם עם לא אדם). ובפרט ביום ההילולא, שאז, כל מעשיו ותורתו ועבודתו (של בעל ההילולא) הם בגילוי, ובאופן דפועל ישועות בקרב הארץ<sup data-n=\"3559\">64</sup>, שגם בקרב הארץ (בערות הארץ)<sup data-n=\"3560\">65</sup> נמשכים ומתגלים הישועות שלמעלה מהשתלשלות, ובפרט שמיום ההילולא באים תיכף לש\"ק ונמצאים עתה בזמן דמנחת שבת, רעוא דכל רעוין (בחי' עתיק), שאז מיתוסף עוד יותר בהנתינת כח לכאו\"א מבנ\"י, צבאות הוי', לעבוד עבודתו בתוקף בלי שינויים, שעי\"ז נמשך עיקר שכינה בתחתונים, כמו שהי' בתחלת הבריאה, ועוד יותר, דהגם שגם בתחלת הבריאה כתיב<sup data-n=\"3561\">66</sup> תולדות מלא<sup data-n=\"3562\">67</sup>, עולם על מילואו נברא<sup data-n=\"3563\">68</sup>, הרי אלה תולדות פרץ<sup data-n=\"3564\">69</sup>, תולדות מלא<sup data-n=\"3562\">67</sup>, הוא למעלה יותר מתולדות מלא שבתחלת הבריאה, ועד שיהי' גם הגילוי דפנימיות עתיק, שזה יהי' דוקא לע\"ל<sup data-n=\"3565\">70</sup>, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, בקרוב ממש.\n**********",[["3495","*","יצא לאור בשעתו, \"<i>ט\"ו שבט שנת הקהל</i>,<i> שנת תשמ\"ח</i>\"."],["3496","1","שה\"ש ה, א."],["3497","2","ד\"ה באתי לגני ה'שי\"ת (נדפס בסה\"מ ה'שי\"ת ע' 111 ואילך), שניתן על ידי בעל המאמר ליו\"ד שבט ה'שי\"ת, יום הסתלקותו."],["3498","3","ויק\"ר פכ\"ט, יא."],["3499","4","סוטה ט, א. שמו\"ר פל\"ה, ג."],["3500","5","תרומה כה, ח."],["3501","6","פ\"ו ואילך."],["3502","7","תרומה כו, טו."],["3503","8","ראה בהמשך ההילולא רפ\"י."],["3504","9","ראה רמב\"ם הל' דיעות פ\"ג."],["3505","10","בהבא להלן – ראה בהמשך ההילולא פ\"ג ואילך."],["3506","11","ראה סנהדרין קו, א. ספרי ר\"פ בלק. במדב\"ר פ\"כ, כב. תנחומא בלק טז."],["3507","12","ראה ד\"ה באתי לגני ה'תשי\"א (לעיל ע' רסג ואילך)."],["3508","13","כתובות יז, א. הובא בהמשך ההילולא פ\"ה."],["3509","14","ראה רמב\"ם ריש הל' בית הבחירה."],["3510","15","פרשתנו טו, יז. ובמכילתא ופרש\"י עה\"פ. וראה לקו\"ש חל\"א ע' 77 ואילך. וש\"נ."],["3511","16","בא יב, מא. וראה בהמשך ההילולא פ\"י."],["3512","17","פי\"א ואילך. וראה גם ד\"ה בעצם היום הזה פר\"ת. וראה בכ\"ז גם ד\"ה צדקת פרזונו בתו\"ח פרשתנו (שכב, א ואילך [בהוצאה החדשה – ח\"א רכא, סע\"ב ואילך]). אוה\"ת פרשתנו ס\"ב (ע' תערב). ד\"ה צדקת פרזונו תרפ\"ט ס\"ו (סה\"מ קונטרסים ח\"א לו, ב)."],["3513","18","וצריך ביאור בפירוש ענין זה (\"מדור אחר דור\") בהנמשל למעלה. ואכ\"מ."],["3514","19","ב\"ב נג, א. וש\"נ."],["3515","20","המשך ההילולא ספי\"ז."],["3516","21","כמבואר בהמשך ההילולא ספי\"א. רפי\"ט."],["3517","22","פרשתנו טו, יח."],["3518","23","כהמנהג שנקבע אצל כו\"כ ללמוד פרק מעשרים הפרקים* של ההמשך ע\"פ סדר (גם) דשנה אחר שנה. ולאחרי שנשלמו עשרים השנים הראשונות (ה'תשי\"א-ה'תש\"ל), מתחילים המנין דעשרים שנה השניות, בעשרים פרקים אלו, כל שנה פרק אחד."],["3519","24","ראה איוב יא, ו. שמו\"ר פמ\"ו, א."],["3520","25","שמואל-א טו, כט.\n*) <i>ולהעיר</i>,<i> שעשרים בגימטריא כתר (לקו\"ת שה\"ש לה</i>,<i> ג</i>.<i> וראה ס' הערכים-חב\"ד מערכת אותיות אות כ\"ף ע' סט ואילך</i>. <b>וש\"נ</b>)."],["3521","26","זח\"ג קכט, א (באד\"ר)."],["3522","27","הביאור ב\"לית <i>שמאלא</i>\" ו\"כולא ימינא\" – אף שמכיון שעתיק הוא למעלה מקוין הרי אין בו לכאורה גם קו הימין – ראה תו\"ח וירא קיד, א ואילך."],["3523","28","ראה גם תו\"א יתרו עב, ג. ד\"ה באתי לגני תשכ\"ח ס\"ד ואילך (לעיל ס\"ע שט ואילך)."],["3524","29","ח\"ג קכט, ב. וראה שם באד\"ז רפט, א."],["3525","30","תהלים קכא, ד."],["3526","31","ראה לקו\"ת ראה כד, ג. אוה\"ת לתהלים (יהל אור) ע' קכב. סה\"מ עזר\"ת ע' סה. סה\"מ קונטרסים ח\"ב רפב, ב ואילך. סה\"מ אידיש ע' 24. ע' 47 ואילך."],["3527","32","תו\"א צח, רע\"ג. לקו\"ת ר\"ה סא, ג. דרמ\"צ לט, א. סה\"מ תרנ\"ח ע' קצט. ובכ\"מ."],["3528","33","שער דרושי אבי\"ע פ\"א."],["3529","34","ראה גם אוה\"ת שבועות ס\"ע פה. המשך תער\"ב ח\"ג ע' א'תלט."],["3530","35","סה\"מ תרנ\"ב ס\"ע לח."],["3531","36","לזח\"ג נשא (אד\"ר קלה, א) ע' שנט ואילך. ולהעיר מהשקו\"ט ובכמה דרגות דאתתקן ולא אתתקן שנאמר בעת\"י. וצ\"ע איך להתאים להמבואר בכהנ\"ל דבפני' הכתר אין שינוי."],["3532","37","אוה\"ת שלח ע' תרכב."],["3533","38","אוה\"ת לך תשכח, א. וראה אוה\"ת על מארז\"ל וענינים ע' רפו. המשך תער\"ב ח\"א פט\"ו."],["3534","39","וירא – ד\"ה ארדה נא הב' פ\"ז ואילך."],["3535","40","ראה שם פ\"ט ואילך. פי\"ד ואילך."],["3536","41","וירא יח, כא."],["3537","42","תרל\"ו –פ\"ו."],["3538","43","נח ח, כא."],["3539","44","ח\"ג ע' א'שסח ואילך."],["3540","45","שעתיק פירושו זקן – מובן גם מהכתוב (ומפרשים לדניאל ז, ט) ועתיק יומין גו'. והחידוש שבתער\"ב שם, שגם הענין דעתיק <i>שאינו</i> משתנה (דענין זה הוא בעיקר בעתיק סתם שלמעלה מעתיק יומין) נקרא זקן. ויתירה מזו, דענין זה בעתיק (<i>שאינו</i> משתנה) מקשר עם זקן כפשוטו."],["3541","46","משלי כב, ו."],["3542","47","ס' השיחות תורת שלום ע' 86."],["3543","48","לקו\"א שלו (הוצאת קה\"ת) סקצ\"ח. או\"ת שלו קיב, ב."],["3544","49","אבות פ\"ב מ\"א."],["3545","50","ראה ס' השיחות תש\"ד ע' 23. וראה ד\"ה פדה בשלום תשל\"ח סעיף ג (לעיל ע' קמד) ובהערות שם."],["3546","51","הל' יסוה\"ת בתחלתם."],["3547","52","אגה\"ק סי' כ (קל, ריש ע\"ב). – ולהעיר אשר כ ר\"ת <i>כתר</i> ועשרים בגימטריא כתר (כנ\"ל בשוה\"ג להערה 23)."],["3548","53","תניא פל\"ו (מה, ב). וראה בארוכה סה\"מ תרנ\"ח ע' ל ואילך."],["3549","54","וראה סה\"מ שם ע' לג."],["3550","55","הובאה בשעהיוה\"א פ\"א."],["3551","56","אוה\"ת נ\"ך ס\"ע כה ואילך."],["3552","57","שמואל-א ב, ג."],["3553","58","אוה\"ת שם ריש ע' כו."],["3554","59","ראה שם ע' כד. ע' כח."],["3555","60","תהלים לד, טו."],["3556","61","ראה לקו\"ת בלק ד\"ה מה טובו (עג, ב ואילך)."],["3557","62","ראה אוה\"ת שם ע' כז (ע\"פ לקו\"ת ר\"פ פקודי) דשרש מ\"ע הוא בז\"א (לו בוא\"ו) ושרש ל\"ת הוא בע\"ק (ולא באל\"ף)."],["3558","63","ראה לקו\"ת בלק שם עד, א. ובכ\"מ."],["3559","64","אגה\"ק סי' כח (קמח, א)."],["3560","65","בארץ מצרים (מקץ מב, ט) – שנאמר בו \"בקרב הארץ\" (וארא ח, יח. וראה ראב\"ע שם)."],["3561","66","בראשית ב, ד."],["3562","67","ב\"ר פי\"ב, ו."],["3563","68","שם פי\"ד, ז. פי\"ג, ג."],["3564","69","רות ד, יח."],["3565","70","פע\"ח שער הק\"ש פט\"ו. הובא בלקו\"ת שה\"ש בסופו."]]],[1500370048,"<h3>בס\"ד. יום ד' חמשה עשר בשבט ה'תשל\"א<sup data-n=\"3566\">*</sup></h3>\n<b>ארבעה</b> ראשי שנים הם באחד בניסן כו' באחד באלול כו' באחד בתשרי כו' באחד בשבט ראש השנה לאילן כדברי בית שמאי, בית הלל אומרים בחמשה עשר בו<sup data-n=\"3567\">1</sup>, והלכה כבית הלל<sup data-n=\"3568\">2</sup>. וצריך להבין טעם השינוי דר\"ה לאילן מג' ראשי שנים הראשונים, שג' ראשי שנים הראשונים הם בראש חודש ור\"ה לאילן הוא בחמשה עשר. ולהוסיף, דע\"פ המבואר במק\"א<sup data-n=\"3569\">3</sup> שהשייכות דג' הרגלים<sup data-n=\"3570\">4</sup> ליום הט\"ו בחודש הוא כי ביום הט\"ו הוא שלימות הלבנה, שזה מורה גם על השלימות דישראל שמונין ללבנה ודומין ללבנה<sup data-n=\"3571\">5</sup>, צריך לומר, דזה שרובם של הראשי שנים [ולדעת ב\"ש כל ד' הראשי שנים] הם בראש חודש, בעת מולד הלבנה שאז הלבנה היא רק נקודה, הוא לפי שענין ראש השנה הוא שבו נמשך הענין שהוא ר\"ה אליו, והענינים כמו שהם בתחלת המשכתם הם רק נקודה, ועפ\"ז צריך להבין עוד יותר מה שר\"ה לאילן הוא בחמשה עשר<sup data-n=\"3572\">6</sup>.\nב) <b>ויובן</b> זה בהקדים המבואר בכמה דרושים<sup data-n=\"3573\">7</sup>, דזה שהרגלים נקבעו בזמני גמר ואסיפת התבואות [דחג הפסח צריך להיות בזמן האביב (זמן גמר שעורים)<sup data-n=\"3574\">8</sup> ויתרה מזה בחג השבועות שנקרא בשם<sup data-n=\"3575\">9</sup> חג הקציר<sup data-n=\"3576\">10</sup> על שם בכורי קציר חטים<sup data-n=\"3577\">11</sup>, וכן חג הסוכות שנקרא בשם חג האסיף<sup data-n=\"3578\">12</sup>], המכוון הוא (בעיקר) לתבואההרוחניית, הם ישראל, דכתיב בהו<sup data-n=\"3579\">13</sup> קודש ישראל להוי' ראשית תבואתה גו'. וזה שהרגלים צריכים להיות בזמני גמר ואסיפת התבואות בגשמיות [ועד שבשביל זה מעברים את השנה<sup data-n=\"3580\">14</sup>], הוא, כי כל הענינים שבגשמיות משתלשלים מענינם ברוחניות<sup data-n=\"3581\">15</sup>. ועפ\"ז יש לומר גם בנוגע ר\"ה לאילן, שעיקר ענינו הוא שהוא ר\"ה להאדם (אתם קרויין אדם<sup data-n=\"3582\">16</sup>) שנמשל לאילן, כמ\"ש<sup data-n=\"3583\">17</sup> כי האדם עץ השדה, ומזה נשתלשל שהוא ר\"ה לאילן כפשוטו בגשמיות. וע\"פ מארז\"ל<sup data-n=\"3584\">18</sup> עה\"פ<sup data-n=\"3583\">17</sup> כי האדם עץ השדה אם תלמיד חכם כו', יש לומר, דזה שישראל נקראים בשם תבואה (חטים שעורים וכו'<sup data-n=\"3585\">19</sup>) הוא מצד העבודה שלהם בקיום המצוות (כדלקמן), וזה שנקראים בשם אילן (עץ השדה) הוא ע\"י עסק התורה. ויש לומר דזהו מ\"ש כי האדם עץ השדה (אדם דייקא), דשם אדם הוא על שם השכל (כמבואר בכ\"מ החילוק בין אדם לאיש<sup data-n=\"3586\">20</sup>).\nג) <b>והנה</b> מבואר בהדרושים<sup data-n=\"3587\">21</sup> השייכות דג' הרגלים לזמני בישול התבואות, כי אז (בג' רגלים) הוא צמיחת התבואה הרוחניית שע\"י הזריעה. והענין הוא, דכתיב<sup data-n=\"3588\">22</sup> וזרעתי' לי בארץ, וידוע<sup data-n=\"3589\">23</sup> שזה קאי על ירידת הנשמות (תבואה הרוחניית) למטה להתלבש בגוף ונפש הבהמית (ארץ)<sup data-n=\"3590\">24</sup>, ובפרטיות יותר על הירידה דהגלות<sup data-n=\"3591\">25</sup>. שהכוונה בזה היא לצורך עלי', בדוגמת זריעה בארץ (כפשוטה) שהיא בשביל הצמיחה בריבוי יותר מכמו שהי' בתחילה<sup data-n=\"3592\">26</sup>. והצמיחה (העלי') היא ע\"י קיום התומ\"צ שנקרא ג\"כ בשם זריעה. דנוסף להזריעה דירידת הנשמה למטה (<i>שהקב\"ה</i> הוריד את הנשמה למטה), צריכה להיות גם <i>עבודת</i> הזריעה <i>דישראל</i>, קיום התומ\"צ. דע\"י שהנשמות ירדו למטה, ובפרט בזמן הגלות, ומ\"מ הם מקיימים תומ\"צ (באתכפיאואתהפכא<sup data-n=\"3593\">27</sup>), עי\"ז נעשה הצמיחה – המשכת גילוי נעלה יותר באין ערוך מהגילוי שהי' להנשמה קודם ירידתה למטה. ועיקר גילוי הצמיחה יהי' לעתיד לבוא. והארה מזה מאיר גם עכשיו, בג' רגלים. ברגל הראשון (חג המצות) שהוא צמיחת בישול שעורים, הו\"ע היראה, שהיא שער הראשון<sup data-n=\"3594\">28</sup> שעל ידו נכנסים לדבקה בו ית'. וזהו ששעורה היא אותיות שעור ה'<sup data-n=\"3595\">29</sup>, שעור הוא מלשון שער והה' היא ה' תתאה (מלכות). וברגל השני (חג השבועות) הוא צמיחת חטים שהם מאכל אדם, הוא התורה דכתיב בה<sup data-n=\"3596\">30</sup> זאת התורה אדם. וזהו שחטה בגימטריא כ\"ב שרומז על כ\"ב אותיות התורה<sup data-n=\"3597\">31</sup>. ומבואר בדרושים הנ\"ל, שזוהי השייכות דעצרת לפירות האילן (בעצרת על פירות האילן<sup data-n=\"3598\">32</sup>), כי חטה היא מין אילן (לדיעה אחת<sup data-n=\"3599\">33</sup>), שרומז על אדם כמ\"ש כי האדם עץ השדה, ובחג השבועות (עצרת) ניתנה תורה, זאת התורה אדם. ויש לומר, דכיון דזה שחטה היא מין אילן הוא רק לדיעה אחת, וגם לדיעה זו הוא רק מין אילן<sup data-n=\"3600\">34</sup>, לכן ענין התורה המרומזת בחטים היא דרגת התורה כמו ששייכת למצוות. והתורה עצמה שלמעלה מענין המצוות, עיקר ענין האדם (זאת התורה אדם), מרומזת בפירות האילן.\nד) <b>והענין</b> הוא, דזה שקיום התומ\"צ נקרא בשם זריעה הוא מצד שני ענינים<sup data-n=\"3601\">35</sup>. לפי שע\"י קיום התומ\"צ נעשה בירור הגוף ונפש הבהמית, ועי\"ז מתגלה השרש דהגוף ונה\"ב שלמעלה מהשרש דנפש האלקית – בדוגמת הזריעה כפשוטה, שע\"י זריעת התבואה והגרעין בארץ מתעורר ומתגלה כח הצומח שבארץ<sup data-n=\"3602\">36</sup>. וגם, לפי שקיום התומ\"צ צריך להיות (לא מצד הטעם אלא) בכדי לקיים ציווי הקב\"ה<sup data-n=\"3603\">37</sup>, כהלשון בברכת המצוות אשר קדשנו במצוותיו <i>וצונו</i>, ביטול דקבלת עול – בדוגמת הזריעה כפשוטה, דהשרשת הגרעין בארץ היא ע\"י <i>רקבון</i> הגרעין. וזהו הטעם על זה שעיקר הצמיחה היא ע\"י קיום התומ\"צ בזמן הגלות, כי בזמן הבית, כשהי' גילוי אלקות (כולל גם הגילוי שע\"י קיום המצוות), לא הי' נרגש כ\"כ הביטול דקבלת עול, מכיון שנרגש אז הגילוי שע\"י המצוות. ועיקר הביטול דקבלת עול הוא בזמן הגלות, ובפרט בדרא דעקבתא דמשיחא, ועד שקיום המצוות אז הוא באופן דהזורעים <i>בדמעה</i><sup data-n=\"3604\">38</sup>, ועי\"ז דוקא ברנה יקצורו<sup data-n=\"3604\">38</sup>.ה) <b>והנה</b> ידוע<sup data-n=\"3605\">39</sup> החילוק בין תורה למצוות, דהמצוות הם ציוויים <i>להאדם</i>, והתורה היא דבר <i>השם</i>, חכמתו של הקב\"ה, אלא שירדה למטה ונתלבשה בשכל האדם<sup data-n=\"3606\">40</sup>. ומזה מובן, דשני ענינים הנ\"ל שבזריעה (בירור הגוף ונה\"ב וביטול דקב\"ע) הם בעיקר בקיום המצוות, משא\"כ בתורה. דבמצוות שהם ציוויים להאדם, שייך לומר שהכוונה בהם הוא בכדי לצרף בהם את הבריות<sup data-n=\"3607\">41</sup>, בשביל הבירור והזיכוך של הגוף ונה\"ב דהאדם שמקיים את המצוה ובשביל הבירור והזיכוך של הדברים שבעולם שבהם מקיימים את המצוה. משא\"כ התורה שהיא חכמתו של הקב\"ה, אין שייך לומר שהיא אמצעי ח\"ו בכדי לפעול בהאדם ובהעולם. והפעולה שנעשית על ידה בהאדם הלומדה, הוא, שע\"י לימוד התורה שלו נמשכת בו חכמתו של הקב\"ה שלמעלה מעולם [והמשכת התורה בהאדם הלומדה היא באופן שהוא מתאחד עמה<sup data-n=\"3608\">42</sup>]. ועד\"ז הוא בנוגע להביטול דקב\"ע (ענין השני דזריעה), דבמצוות שהם ציוויים להאדם (שזה מורה שבהדרגא דמצוות יש להאדם תפיסת מקום), האדם הוא מציאות<sup data-n=\"3609\">43</sup>. וזה שמקיים את הציווי הוא מצד הביטול דקבלת עול, כעבד<sup data-n=\"3610\">44</sup> המקיים מצות המלך. ובתורה שהיא חכמתו של הקב\"ה, אין שם נתינת מקום למציאות שחוץ ממנו, גם לא למציאות דעבד, ולכן השלימות דעסק התורה היא כשהלימוד שלו הוא באופן שדבר ה' מדבר בפיו. וזהו שארז\"ל<sup data-n=\"3611\">45</sup> מאן מלכי רבנן, כי לימוד התורה שלהם היא באופן שדבר ה' מדבר על ידם, ולכן הם בתכלית הביטול שלמעלה גם מהביטול דעבד, ועד שכל מציאותם היא המלך עצמו<sup data-n=\"3610\">44</sup>, שע\"י אורייתא ישראל וקוב\"ה כולא חד<sup data-n=\"3612\">46</sup>. וגם מי שאינו בדרגא זו שלימוד התורה שלו יהי' באופן זה שדבר ה' מדבר בפיו<sup data-n=\"3613\">47</sup>, מ\"מ, עיקר ההדגשה בעסק התורה הוא לא על ענין הביטול והאתכפיא, אלא אדרבה, על זה שהמציאות שלו (ההבנה וההשגה) תהי' חד עם התורה.\n<b>וזהו</b> שאמרו<sup data-n=\"3614\">48</sup> לעולם ילמוד אדם במקום שלבו חפץ, דחפץ הוא רצון שיש בו תענוג<sup data-n=\"3615\">49</sup>, דהגם שגם בלימוד התורה צ\"ל הביטול דעבד (<i>עולה</i> של תורה<sup data-n=\"3616\">50</sup>) וגם הביטול דאתכפיא (לשנות פרקו מאה פעמים ואחד<sup data-n=\"3617\">51</sup>), מ\"מ, עיקר ההדגשה בלימוד התורה הוא<sup data-n=\"3618\">52</sup> שהתורה שלומד תהי' התענוג והחיות שלו. ויש לומר טעם לזה, דכיוןשענין לימוד התורה הוא שעי\"ז נעשים ישראל וקוב\"ה כולא חד, לכן, כמו שבהקב\"ה, התורה היא התענוג דהקב\"ה, ואהי' אצלו שעשועים<sup data-n=\"3619\">53</sup>, כמו\"כ צריך להיות בהאדם העוסק בתורה, שהתורה שלומד תהי' התענוג שלו. [ואף שהתענוג דהאדם בהתורה שלומד הוא מצד השכל שבה, כמובן גם מענין במקום שלבו חפץ, יש לומר, <i>שבפנימיות הענינים</i> התענוג שלו בתורה הוא מפני שהתורה היא שעשועים דהקב\"ה [וכיון שישראל וקוב\"ה כולא חד, לכן התורה היא גם התענוג דישראל], אלא שבתענוג הגלוי שלו נרגש שהתענוג שלו בתורה הוא מצד השכל שבה].\nו) <b>ויש</b> לומר, דשני הענינים שבתורה מרומזים בחטה ובאילן. דחטה שהיא תבואה [דגם לדעת ר\"י היא רק <i>מין</i> אילן] רומזת על התורה כמו ששייכת למצוות (שלימוד התורה הוא בכדי לקיים <i>מצות</i> תלמוד תורה, וכיו\"ב), והתורה כמו שהיא מצד עצמה מרומזת באילן. דמעלת האילן לגבי תבואה היא, שתבואה (גם חטים) היא דבר המוכרח לקיומו של האדם, וענין האילן הוא שהוא מצמיח <i>פירות</i>, שאינם מוכרחים לקיומו של האדם, אלא דברים של <i>תענוג</i>. ולהוסיף, שגם ראיית האילן (לא רק אכילת פירותיו) גורמת לתענוג, כמ\"ש<sup data-n=\"3620\">54</sup> ויצמח גו' כל עץ נחמד למראה גו'. וכמו שרואים בפועל, שהטיול בגן, מקום שצומחים בו אילנות, הוא תענוג. ועפ\"ז יובן העילוי דר\"ה לאילן על ר\"ה לירקות, אף שבירקות נכלל גם חטים (מאכל אדם) שרומזים על התורה, דההמשכה בר\"ה לירקות היא בנוגע לקיום המצוות, וגם ההמשכה שבנוגע לעסק התורה (חטים) היא בנוגע לעסק התורה כמו ששייך לקיום המצוות, וההמשכה בר\"ה לאילן היא בנוגע ללימוד התורה כמו שהוא מצד עצמו, ענין התענוג דתורה.\nז) <b>ויש</b> לומר, דע\"י שהמצוות נמשכות מהתורה, וגם זה שקיום המצוות צ\"ל בדרך עבודת עבד הוא לפי <i>שהתורה</i> אמרה<sup data-n=\"3621\">55</sup> ועבדתם את ה' אלקיכם וגו'<sup data-n=\"3622\">56</sup>, עי\"ז נמשך <i>מעין</i> התענוג דתורה גם בעבודה דקבלת עול (עבודת עבד) שבקיום המצוות. וע\"ד המבואר בהמשך תרס\"ו<sup data-n=\"3623\">57</sup>, דזה שגם עבד פשוט [שעבודתו היא מצד <i>עול</i> האדון המוטל עליו] משתדל שהמלאכה שעושה תהי' לנוי ולתפארת לאדונו, הוא לפי שגם עבד הפשוט יש לו תענוג בהעבודה, אלא שהתענוג דעבד הפשוט הוא [לא מצד ענינו ומציאותו של העבד, אלא אדרבה] מצד הביטול שלו<sup data-n=\"3624\">58</sup>, דלהיות שאינו מציאות לעצמו לכן התענוג של האדון הוא התענוג שלו. ועד\"ז הוא בעבודת ה', שבהעבודה דקבלת עול יש גם ענין התענוג, אלא שהתענוג הוא התענוג דלמעלה. ויש לומר,דזה שגם בהעבודה דקב\"ע יש ענין התענוג, הוא לפי שגם העבודה דקב\"ע נמשכת מהתורה, שהתורה אמרה ועבדתם את ה' אלקיכם גו'.\nח) <b>והענין</b> הוא, דאיתא באגה\"ק ד\"ה זמירות קרית להו<sup data-n=\"3625\">59</sup>, שכל העולמות עליונים ותחתונים תלויים בדקדוק מצוה, ומביא שתי דוגמאות לזה, קרבן ותפילין. ומבאר אאמו\"ר בהערותיו לתניא<sup data-n=\"3626\">60</sup>, דהטעם שתפס ב' מצוות אלו (קרבן ותפילין) הוא, כי כלל ענין המצוות הוא העלאה והמשכה, רצוא ושוב (כמ\"ש בלקו\"ת בד\"ה זאת חוקת התורה<sup data-n=\"3627\">61</sup>), ולכן תפס ב' מצוות אלו, כי קרבן הוא העלאה, רצוא, ותפילין הוא המשכה, שוב (כמ\"ש בלקו\"ת בדרושי הנסכים<sup data-n=\"3628\">62</sup>). וצריך להבין, מה נוגע להענין המבואר באגה\"ק הנ\"ל [שכל העולמות תלויים בדקדוק מצוה] לרמז שענין המצוות הוא העלאה והמשכה. ויש לומר, דזה שמבאר באגה\"ק שכל העולמות תלויים בדקדוק <i>מצוה</i> הוא הקדמה למ\"ש שם לאח\"ז שכל העולמות בטלים במציאות לגבי דקדוק אחד מדקדוקי <i>תורה</i>. דזה שאמר דוד<sup data-n=\"3629\">63</sup> זמירות היו לי חוקיך גו' הוא שבחא <i>דאורייתא</i> (כמ\"ש באגה\"ק הנ\"ל בתחלתה), והשבח הוא שכל העולמות <i>בטלים במציאות</i> (ולא רק תלויים)<sup data-n=\"3630\">64</sup> לגבי דקדוק אחד מדקדוקי תורה, אלא שגילוי ענין זה דתורה הוא ע\"י שכל העולמות <i>תלויים</i> בדקדוק מצוה. והיינו, דלגבי המצוות שהם ציוויים <i>להאדם</i> איך שיתנהג <i>בעולם</i>, בהכרח שיש איזה ערך ותפיסת מקום להעולמות, וזה שהעולמות הם <i>בטלים במציאות</i> הוא (דוקא) לגבי (דקדוק אחד מדקדוקי) <i>תורה</i>. וההוכחה על זה היא מזה שכל העולמות תלויים בדקדוק מצוה. דזה שהעולמות תלויים בדקדוק מצוה (אפילו בדקדוק קל) הוא מפני שהוא דקדוק תורה, שלגבה העולמות בטלים במציאות, ולכן, גם לאחרי שנמשך במצוות ונעשה \"דקדוק מצוה\", כל העולמות תלויים בו.\n<b>ובכדי</b> לבאר שגם לאחרי המשכת דקדוקי תורה בהמצוות מאיר בהם בגילוי ענין התורה, מרמז באגה\"ק (ע\"י הבאת הדוגמאות דקרבן ותפילין) שענין המצוות הוא העלאה והמשכה, רצוא ושוב. דיש לומר, שענין ההעלאה והרצוא שבמצוות הוא שנרגש בהם מקורם כמו שהם בתורה שלמעלה מהעולם, וענין ההמשכה והשוב שבהם הוא שהם נמשכים להיות ציוויים <i>להאדם</i>, וגם אז נרגש בהם שהמקור שלהם הוא בתורה שלמעלה מעולמות [כי ענין רצוא ושוב הוא שגם לאחרי השוב ניכר רישומו של הרצוא<sup data-n=\"3631\">65</sup>]. ולהעיר מזה שאומרים בברכת המצוות אשר קדשנו במצוותיו וצונו, דיש לומר, שקדשנו במצוותיו הו\"ע ההעלאה, שהעלנו למעלת קודש העליוןב\"ה שהיא קדושתו של הקב\"ה בכבודו ובעצמו<sup data-n=\"3632\">66</sup>, וצונו הו\"ע ההמשכה, שציוה <i>אותנו</i>. והטעם לזה שאומרים בברכת המצוות (בנוגע להמצוות <i>שניתנו לנו</i>) קדשנו במצוותיו, הוא, כי גם לאחרי שצונו (ונעשו ציוויים להאדם) הם מצוו<i>תיו</i> דהקב\"ה כמו שהוא קדוש ומובדל מענין הציווי לאדם.\nט) <b>וזהו</b> שע\"י התורה הוא המשכת התענוג גם בעבודה דקבלת עול שבקיום המצוות. כי זה שקיום המצוות הוא באופן דקבלת עול כעבד המקיים מצות המלך [שהעבד הוא לא האדון אלא שהוא בטל להאדון] הוא מפני שהכוונה בענין המצוות (ציוויים להאדם) היא שהאדם יהי' מציאות שחוץ ממנו (שאין לו תענוג באלקות) ואעפ\"כ יהי' בטל אליו. וע\"י המשכת התורה (שלמעלה מציווי לאדם) בהמצוות ובהעבודה דקבלת עול (<i>שהתורה</i> אמרה ועבדתם), נרגש, דזה שהאדם הוא מציאות שחוץ ממנו ית' הוא בכדי להשלים הכוונה העליונה. ועי\"ז, הביטול דקב\"ע הוא בכל מציאותו, היינו שגם זה שנעשה כמו מציאות לעצמו הוא בכדי להשלים הכוונה. ולכן המציאות שלו אינה סתירה להתענוג שיש לו בעבודתו (היינו לתענוג האדון שנמשכת בו), לפי שגם המציאות שלו היא בכדי להשלים הכוונה.\n<b>ועפ\"ז</b> יובן מה שמובא לעיל (סעיף ז) מהמשך תרס\"ו, דזה שהעבד משתדל שהמלאכה שעושה תהי' לנוי ולתפארת לאדונו הוא לפי שיש לו תענוג בהעבודה והתענוג שלו הוא תענוג האדון. דלכאורה אינו מובן, הרי השייכות דהעבד להאדון היא לדרגת האדון ששייכת אליו (שהוא משועבד להאדון), ואיך נרגש בו התענוג דהאדון בהנוי והתפארת דהמלאכה שאינה שייכת (לכאורה) להשעבוד והביטול דהעבד להאדון. ויש לומר הביאור בזה בהנמשל (ומזה משתלשל גם בהמשל), דע\"י שהביטול דקב\"ע (כמו שהוא מצד זה <i>שהתורה</i> אמרה ועבדתם גו') הוא להשלים הכוונה בזה שהקב\"ה צמצם עצמו כביכול לצוות להאדם, דכוונה זו היא בהקב\"ה עצמו שלמעלה מענין הציווי, לכן נרגש בו גם ענין התענוג דהאדון עצמו.\nיו\"ד) <b>וזהו</b> בחמשה עשר בשבט ר\"ה לאילן, דאילן רומז על תורה (כנ\"ל סעיף ב), שביום זה נמשך נתינת כח על כל השנה בנוגע לעסק התורה, שלימוד התורה יהי' בשקידה ובהתמדה, ושהתורה שלומד תהי' התענוג והחיות שלו (דאילן הו\"ע התענוג, כנ\"ל סעיף ו). וע\"פ הידוע<sup data-n=\"3633\">67</sup> שכל ארבעה ראשי השנים שייכים זל\"ז, יש לומר, דבר\"ה לאילן נמשך הנתינת כח שגם כל הענינים דעבודת האדם (הנמשכים בג' ראשי שנה הראשונים) יהיו מתוך תענוג, ע\"ד המבואר לעיל סעיף ט שע\"י התורה, גם העבודה דקב\"ע היא בתענוג. וזהו שר\"ה לאילן הוא בחמשה עשר שבו הוא שלימות הלבנה, ולא כג' ראשי שנים הראשונים שהם בר\"ח שאז הלבנה היא רק נקודה, כי זה שהלבנה היא רק נקודה מורה על ענין הביטול<sup data-n=\"3634\">68</sup>, והתענוג שבעבודת ה', ובפרט התענוג דתורה, הו\"ע השלימות.<b>וע\"י</b> ההוספה במעשינו ועבודתינו<sup data-n=\"3635\">69</sup>, ובפרט בעסק התורה ובאופן שהתורה היא התענוג והחיות של האדם העוסק בתורה, ומכש\"כ ע\"י העסק (וההפצה) דפנימיות התורה [דבתורה עצמה בחינת התענוג דתורה היא פנימיות התורה], יהי' גם ר\"ה למלכים בתכלית השלימות, שיראו בגילוי שכל ישראל בני מלכים הם<sup data-n=\"3636\">70</sup>, ויתירה מזה – מלכים (כמפורש בתקו\"ז<sup data-n=\"3637\">71</sup>), ובני ישראל יוצאים ביד רמה<sup data-n=\"3638\">72</sup>, כמתאים למלכים, ע\"י דוד מלכא משיחא, ועבדי דוד מלך עליהם גו'<sup data-n=\"3639\">73</sup>, בגאולה האמיתית והשלימה, בקרוב ממש.\n**********",[["3566","*","יצא לאור ב<b>קונטרס ט\"ו בשבט – תנש\"א</b>, \"לקראת חמשה עשר בשבט . . <i>מוצש\"ק שירה</i>,<i> שנת ה'תנש\"א</i>\"."],["3567","1","משנה ריש מס' ר\"ה."],["3568","2","רמב\"ם הל' תרומות פ\"ה הי\"א. הל' מעשר שני פ\"א ה\"ב."],["3569","3","ראה זהר ח\"ב קצד, א (הובא באוה\"ת ואתחנן כרך ו ע' ב'קצד) \"מועד כו' יום חדוה דסיהרא לא שלטא בה פגימותא\"."],["3570","4","גם דחג השבועות כיון שאינו יום קבוע בחודש סיון, וקביעותו הוא יום הנ\"א <i>מט\"ו</i> בניסן (ר\"ה ו, ב. שו\"ע אדה\"ז או\"ח ריש סימן תצ\"ד). וראה אוה\"ת דברים ע' ב \"פסח וסוכות הם בחמשה עשר לחודש . . ושבועות זהו עצרת של פסח\"."],["3571","5","סוכה כט, א. ב\"ר פ\"ו, ג."],["3572","6","בפע\"ח שער חג השבועות בסופו – \"דרוש על סוד ט\"ו באב וט\"ו בשבט\", דבט\"ו בשבט \"הוא מילוי הלבנה . . תתחנט עלים של פירות אילן\". וצריך ביאור, דלכאורה <i>חנטת</i> העלים הוא רק <i>התחלת</i> הצמיחה, ומהי השייכות <i>למילוי</i> הלבנה."],["3573","7","ד\"ה שלש רגלים באוה\"ת משפטים (ע' א'קעח ואילך). ד\"ה קדש ישראל לה' באוה\"ת פינחס (ע' א'ריב ואילך). ד\"ה כי תבואו גו' ושבתה וד\"ה קדש ישראל לה' תר\"ל (סה\"מ תר\"ל ע' קלב ואילך. שם ע' רה ואילך). ד\"ה וחג האסיף תשמ\"ג (לעיל ח\"א ע' קעב ואילך)."],["3574","8","משפטים כג, טו. וראה ראב\"ע שם פסוק טז."],["3575","9","דשמו של כל דבר מורה על ענינו, ועד שהוא החיות שלו (שעהיוה\"א פ\"א. ובכ\"מ)."],["3576","10","משפטים שם, טז. ולהעיר שבפירוש רש\"י שם \"שהוא זמן <i>הבאת</i> ביכורים\". אבל בפירוש הבחיי שם (הובא בהדרושים שבהערה 7) שג' המועדים הם על התבואה, וחגה\"ש הוא <i>בזמן ביכורי קציר חטים</i>. וכ\"מ בפירוש הראב\"ע שם."],["3577","11","תשא לד, כב."],["3578","12","משפטים ותשא שם."],["3579","13","ירמי' ב, ג."],["3580","14","בדרושים הנ\"ל מובא מס' פנים יפות \"שיזהרו שיהיו השלשה רגלים בזמן האביב בזמן הקציר ובזמן האסיפה, והיינו ע\"י עיבור השנה\". היינו שמעברין את השנה גם בכדי שחג הסוכות יהי' בזמן האסיפה. וראה סנהדרין יא, ב \"על שלשה דברים מעברין את השנה, על האביב ועל פירות האילן ועל התקופה\" ובפרש\"י שם שקאי גם על תקופת תשרי, דחגה\"ס צ\"ל בתקופת תשרי (ראה שם יג, א). אבל ברמב\"ם הל' קדה\"ח פ\"ד אינו מביא שחגה\"ס צ\"ל בתקופת תשרי, ופירוש \"על התקופה\" הוא <i>שחגה\"פ</i> יהי' בתקופת ניסן (שם ה\"ב). וראה כס\"מ שם הט\"ז."],["3581","15","ראה תניא רפ\"ג."],["3582","16","יבמות סא, רע\"א."],["3583","17","שופטים כ, יט."],["3584","18","תענית ז, א."],["3585","19","ראה זח\"ב קנ, ב. דמ\"ש (ירמי' שם) \"ראשית תבואתה\" בה' רומז על ה' מיני תבואה, חטה שעורה כוסמת שבולת שועל ושיפון."],["3586","20","ראה לקו\"ת שה\"ש כה, א. סה\"מ תרכ\"ט ע' קנז. ועוד. וראה ספר הערכים-חב\"ד כרך א ערך אדם ס\"ט. <i>וש\"נ</i>."],["3587","21","אוה\"ת פינחס וסה\"מ תר\"ל שבהערה 7."],["3588","22","הושע ב, כה."],["3589","23","לקו\"ת האזינו עד, ג. תו\"ח שבהערה 25. ובכ\"מ."],["3590","24","דעל נה\"ב נאמר (קהלת ג, כא) רוח הבהמה היורדת גו' <i>לארץ</i> (לקו\"ת שם)."],["3591","25","פסחים פז, ב. וראה בארוכה תו\"א בשלח סא, א ואילך. תו\"ח שם קסט, ב ואילך [בהוצאה החדשה – ח\"א קלג, ב ואילך]. אוה\"ת שם ע' שנג ואילך. ובכ\"מ."],["3592","26","דכלום אדם זורע סאה אלא להכניס כמה כורין (פסחים שם)."],["3593","27","כ\"ה הלשון באוה\"ת פינחס ע' א'ריד. סה\"מ תר\"ל ע' קלב. שם ע' רו. וראה לקמן הערה 35."],["3594","28","ראה זהר (ח\"א יא, ב) \"יראת ה' דאקרי ראשית כו' ודא איהי תרעא לאעלאה כו' תרעא דכולא\"."],["3595","29","זח\"ג קפח, ב."],["3596","30","חוקת יט, יד."],["3597","31","זהר שם. תקו\"ז תס\"ט (קיד, ב (ס\"א))."],["3598","32","ר\"ה פ\"א מ\"ב (טז, רע\"א)."],["3599","33","דעת ר' יהודה בברכות (מ, סע\"א)."],["3600","34","דגם לדעת ר' יהודה אין מברכים על החטה בורא פרי העץ (ברכות שם)."],["3601","35","להעיר, דשני הענינים (דלקמן בפנים) הם דוגמת אתכפיא ואתהפכא."],["3602","36","לקו\"ת האזינו שבהערה 23."],["3603","37","ראה לקו\"ת שלח מ, א. ובארוכה – עטרת ראש דרוש לעשי\"ת (נז, א. נט, ב)."],["3604","38","תהלים קכו, ה."],["3605","39","הדרן על ששה סדרי משנה תשמ\"ח סכ\"ו (תורת מנחם – הדרנים על הרמב\"ם וש\"ס ע' תו)."],["3606","40","תניא פ\"ד (ח, ב)."],["3607","41","ב\"ר רפמ\"ד. וש\"נ."],["3608","42","תניא פ\"ה. וראה לקמן בפנים."],["3609","43","היינו שמצד הרצון דמצוות <i>צריך</i> האדם להיות מציאות."],["3610","44","תו\"א וישב כז, ב. וארא נו, א."],["3611","45","גיטין סב, א. וראה תו\"א וישב שם."],["3612","46","ראה זח\"ג עג, א. וראה תניא פכ\"ג שהענין ד\"כולא חד\" הוא דוקא בתורה משא\"כ במצוות."],["3613","47","להעיר שענין זה (\"אני המשנה המדברת בפיך\") נאמר בנוגע <i>להב\"י</i> (מגיד מישרים ר\"פ ויקרא – הובא בלקו\"ת פקודי ו, א. ובכ\"מ)."],["3614","48","ע\"ז יט, א."],["3615","49","לקו\"ת שה\"ש כח, ד. וש\"נ."],["3616","50","ראה במדב\"ר פי\"ח, כא. תדא\"ר רפ\"ב. מדרש שמואל פכ\"ט."],["3617","51","חגיגה ט, ב. וראה תניא פט\"ו. ד\"ה באתי לגני שנה זו (ה'תשל\"א) ס\"י (לעיל ע' שסא). וש\"נ."],["3618","52","להעיר מלקו\"ת פ' ראה כט, ג-ד, דיש מעלה בעבד שאינה בבן, וענין \"<i>עולה</i> של <i>תורה</i>\" (כולל העניןדשונה פרקו מאה פעמים ואחד) הוא \"כמ\"ש בסש\"ב פמ\"א דיש בן שהוא ג\"כ עבד\". ומזה מובן, דענין עולה של תורה הוא בכדי שבלימוד התורה שלו תהי' גם המעלה דעבד, אבל לימוד התורה עצמו הו\"ע בן – והרי ענין הבן הוא \"דמה שהוא רצון האב הוא גם רצון הבן\" (המשך תרס\"ו ס\"ע שח)."],["3619","53","משלי ח, ל."],["3620","54","בראשית ב, ט."],["3621","55","לשון אדה\"ז בתניא פמ\"א (נז, א)."],["3622","56","משפטים כג, כה."],["3623","57","ס\"ע שכה ואילך."],["3624","58","בהמשך תרס\"ו שם, דחילוק זה הוא המעלה דעבד פשוט. ויש לומר, שמצד חילוק זה יש מעלה גם בבן (ועבד נאמן), עסק התורה – שהתענוג באלקות הוא גם מצד ענינו ומציאותו <i>דהאדם</i>."],["3625","59","קס, א ואילך."],["3626","60","לקוטי לוי\"צ לאגה\"ק שם (ע' נג)."],["3627","61","לקו\"ת חוקת נו, ב ואילך."],["3628","62","לקו\"ת שלח מ, א ואילך."],["3629","63","תהלים קיט, נד."],["3630","64","ולהעיר, דזה שדוד הי' משמח לבו בעסק התורה בעת צרתו הוא (לא מפני שכל העולמות תלויים בדקדוק אחד של תורה, אלא) מפני שכל העולמות <i>בטלים במציאות</i> לגבי דקדוק אחד של תורה, שעי\"ז פעל בעצמו שעניני העולם לא יתפסו מקום אצלו (ראה סה\"מ תרפ\"ז ס\"ע רד ואילך. לקמן ח\"ד ע' יד)."],["3631","65","לקו\"ת חוקת שם נז, א."],["3632","66","תניא פמ\"ו (סו, א)."],["3633","67","הגהות מיימוניות לרמב\"ם הל' שופר פ\"א אות א."],["3634","68","תו\"א יתרו סז, ג. ובכ\"מ."],["3635","69","תניא רפל\"ז."],["3636","70","שבת סז, א."],["3637","71","בהקדמה (א, ב)."],["3638","72","בשלח יד, ח."],["3639","73","יחזקאל לז, כד."]]],[1500370049,"<h3>בס\"ד. יום ה' פ' יתרו, חמשה-עשר בשבט ה'תשל\"ד<sup data-n=\"3640\">*</sup></h3>\n<b>בחודש</b> השלישי לצאת בני ישראל מארץ מצרים ביום הזה באו מדבר סיני<sup data-n=\"3641\">1</sup>, ואיתא בגמרא<sup data-n=\"3642\">2</sup> כתיב הכא ביום הזה באו מדבר סיני וכתיב התם<sup data-n=\"3643\">3</sup> החודש הזה לכם ראש חדשים, מה להלן ר\"ח אף כאן ר\"ח. וידוע הדיוק<sup data-n=\"3644\">4</sup> מה שנאמר ביום הזה סתם (וצריך ללמוד מגז\"ש שהוא ר\"ח<sup data-n=\"3645\">5</sup>) ולא נאמר באחד לחודש. והנה ברש\"י מפרש דמה שכתוב ביום הזה<sup data-n=\"3646\">6</sup> הוא שיהיו דברי תורה חדשים עליך כאילו היום ניתנו. וצריך להבין, דפירוש ביום הזה כפשוטו הוא שביום הזה קאי על ר\"ח סיון, ולהפירוש שיהיו דברי תורה חדשים עליך כו' ביום הזה קאי על כל יום דכל ימות השנה. גם צריך להבין (כהדיוק בכמה דרושים<sup data-n=\"3647\">7</sup>), איך אפשר שיהיו דברי תורה בכל יום כחדשים ועאכו\"כ חדשים אחר שכבר ניתנה התורה יותר מג' אלפים שנה. ולכאורה אפשר לבאר זה ע\"פ המבואר בהדרושים ד\"ה זה<sup data-n=\"3648\">8</sup> בפירוש הכתוב<sup data-n=\"3649\">9</sup> וידבר אלקים את כל הדברים האלה לאמר, דתיבת לאמר בפסוק זה פירושה הוא שלימוד התורה (כל הדברים האלה) יהי' באופן דלאמר, לחזור הדברים שהקב\"ה אומר עכשיו, כמ\"ש<sup data-n=\"3650\">10</sup> תען לשוני אמרתך, שהתורה היא אמרתך אלא שלשוני תען כעונה אחר האומר. ולכן מה להלן באימה וביראה כו' אף כאן כו'<sup data-n=\"3651\">11</sup>, כי בלימודו התורה עכשיו הקב\"ה אומר הדברים האלה עכשיו, באותו האופן ממש כבשעת מתן תורה. וג\"ז צריך ביאור, דכיון שדבריו של הקב\"ה חיים וקיימים לעד בלי שום שינוי<sup data-n=\"3652\">12</sup>, מה מיתוסף ומתחדש בזה שאומרם עכשיו (בעת לימוד האדם) עוד פעם<sup data-n=\"3653\">13</sup>.ב) <b>ויובן</b> זה בהקדים דאיתא במדרש<sup data-n=\"3654\">14</sup>, משל למלך שגזר ואמר בני רומי לא ירדו לסוריא ובני סוריא לא יעלו לרומי, כך כשברא הקב\"ה את העולם גזר ואמר השמים שמים לה' והארץ נתן לבני אדם<sup data-n=\"3655\">15</sup>, כשביקש ליתן התורה ביטל הגזירה ואמר התחתונים יעלו לעליונים והעליונים ירדו לתחתונים, ואני המתחיל, שנאמר<sup data-n=\"3656\">16</sup> וירד הוי' על הר סיני וכתיב<sup data-n=\"3657\">17</sup> ואל משה אמר עלה אל הוי'. והנה ידוע שהגילוי אלקות בעולם שהי' בשעת מתן תורה (ירידת העליונים לתחתונים, וירד הוי' על הר סיני) הי' בדרך מלמעלה למטה, היינו שהגילוי הי' מצד ההמשכה מלמעלה והמטה לא הי' כלי לזה<sup data-n=\"3658\">18</sup>, וענין התחתונים יעלו לעליונים הוא<sup data-n=\"3659\">19</sup> שבמתן תורה ניתן הכח שהעבודה דתומ\"צ שלאחרי מ\"ת תפעול בהעולם שיהי' כלי לאלקות. וכמבואר במק\"א<sup data-n=\"3660\">20</sup>, דזה שע\"י קיום המצוות נעשה בירור וזיכוך בהדברים שבעולם שבהם נעשית המצוה, ועד שבכמה ענינים נעשים הם (הדברים שבעולם) חפצא של מצוה, הוא ע\"י נתינת כח מיוחדת שניתנה במ\"ת. דכיון שהמצוות (רצונו של הקב\"ה) והדברים שבעולם (שבהם נעשים המצוות) הם באין ערוך לגמרי, לכן, בכדי שהמצוות יפעלו שינוי בהדברים שבעולם הוא דוקא ע\"י ביטול הגזירה והמחיצה שבין העליונים (מצוות) והתחתונים (הדברים שבעולם). ועד\"ז הוא בנוגע ללימוד התורה, דזה שע\"י לימוד התורה נעשה שינוי (רוממות<sup data-n=\"3661\">21</sup>) בהאדם הלומדה, ועד שהוא מתאחד עם חכמתו של הקב\"ה<sup data-n=\"3662\">22</sup>, הוא ע\"י שבמ\"ת נעשה ביטול הגזירה והמחיצה שבין חכמתו של הקב\"ה (עליונים) ושכל האדם (תחתונים).\nג) <b>והנה</b> במעלה ומטה (עליונים ותחתונים) שני פירושים (ענינים). מעלה ומטה במקום (מקום גשמי או מקום רוחני), וענין זה דמעלה ומטה שרשו הוא מהקו. דבאם היתה ההמשכה מאוא\"ס (שלא ע\"י הקו) היו כל העולמות בשוה<sup data-n=\"3663\">23</sup>. ועוד פירוש במעלה ומטה, שכללות ענין ההתחלקות (מעלה ומטה דמקום) נק' בשם מטה, כי מעלה הוא למעלה מהתחלקות. וכידוע<sup data-n=\"3664\">24</sup> בפירוש המאמר<sup data-n=\"3665\">25</sup> אוא\"ס למעלה מעלהעד אין קץ ולמטה מטה עד אין תכלית, דלמטה מטה הוא האור שבבחינת גבול, שרש הקו (שיש בו בהעלם ההתחלקות דמעלה ומטה, שהם השרש דמעלה ומטה שבעולמות), ולמעלה מעלה הוא אור הבלי גבול, שרש הסובב שלמעלה מהתחלקות. ויש לומר, דזה שבמ\"ת נעשה החיבור דמעלה ומטה, הוא בשני הענינים. החיבור דמעלה ומטה שבעולמות (מקום), דבכללות הוא החיבור דאצילות ובי\"ע<sup data-n=\"3666\">26</sup>, וגם החיבור דאור הבל\"ג שלמעלה מעולמות עם האור שבערך העולמות, וכידוע<sup data-n=\"3667\">27</sup> שענין המצוות (שלאחרי מ\"ת) הוא שעל ידם נעשה יחוד קוב\"ה ושכינתי', יחוד סובב וממלא.\nד) <b>והנה</b> ענין זה שבהחיבור דמעלה ומטה שבמ\"ת נכלל גם המעלה שלמעלה מהגדר דמעלה ומטה שבעולמות, הוא הן בנוגע להנתינת כח שהיתה במ\"ת על העבודה דתומ\"צ שלאחרי מ\"ת (התחתונים יעלו לעליונים), שע\"י עבודת התחתונים יומשך (אור האצילות ו)אור הסובב ועד לאור הבל\"ג שלפני הצמצום (השרש דאור הסובב), והן בהחיבור דמעלה ומטה (העליונים ירדו לתחתונים) שהי' בשעת מ\"ת גופא. והענין הוא, דהנה ידוע<sup data-n=\"3668\">28</sup> שהתורה היא למעלה מזמן ומקום, שלכן כל העוסק בתורת עולה כאילו הקריב עולה<sup data-n=\"3669\">29</sup> אף שאינו בזמן ומקום ההקרבה<sup data-n=\"3670\">30</sup>.\nה) <b>והנה</b> אף שירידת העליונים למטה ועליית התחתונים למעלה הם שני ענינים, ועד שהיו בשני זמנים, דירידת העליונים למטה היתה בשעת מ\"ת ועליית התחתונים למעלה היתה לאחרי מ\"ת, מ\"מ, כיון שירידת העליונים למטה היתה (גם) ההתחלה (והנתינת כח) על עליית התחתונים, וכמרז\"ל ואני המתחיל דכ\"ז, לכן, היתה הירידה באופן שבשעת מעשה פעלה בהתחתונים. ועפ\"ז יש לבאר מה דאיתא<sup data-n=\"3671\">31</sup> שהקול דעשרת הדברות הי' נשמע מכל ד' רוחות העולם ומלמעלה ומלמטה, כי הגילוי דאוא\"ס שלמעלה מגדר מקום (למעלה גם מהגדר דמקום כמו שהוא בהקו) שבהקול דעשרת הדברות פעל בהמקום (שבו נשמע הקול) שיהי' למעלה מהמקום<sup data-n=\"3672\">32</sup>. ולכן,אף שהמקום שבו הי' הקול הי' מקום מסויים, נכללו בו כל הששה קצוות. ויש לומר, שעד\"ז הוא בנוגע לזמן, שהזמן שבו ניתנה תורה הי' למעלה מהזמן, ונכלל בו כל המשך הזמן. ויש לומר דזהו מהטעמים על זה שמתן תורה הי' רק פעם אחת ולא יהי' עוד פעם<sup data-n=\"3673\">33</sup>, כי בהזמן דמ\"ת נכלל כל המשך הזמן כולו. ועד\"ז הוא בנוגע לר\"ח סיון שאז נשלמה ההכנה למ\"ת<sup data-n=\"3674\">34</sup>, שביום זה נכלל כל משך הזמן שלאח\"ז. וזהו הקשר דשני הפירושים דביום הזה, שקאי על ראש חודש סיון ושקאי על כל יום, כי בר\"ח סיון דשנת מ\"ת נכללו כל הימים שלאח\"ז.\nו) <b>ועפ\"ז</b> יש לבאר ההוספה והחידוש של הדיבור דהקב\"ה (אמרתך) בעת לימוד האדם על הדיבור שהי' במתן תורה, כי זה שהדיבור דמ\"ת ישנו בכל זמן הוא מצד הלימוד של האדם וכמשנת\"ל (סעיף ה) דזה שהגילוי דמ\"ת פעל בהזמן שבו ניתנה תורה שיהי' כלול בו כל המשך הזמן הוא בכדי שהגילוי דמ\"ת יהי' ההתחלה והנתינת כח על עליית התחתונים, עבודת האדם. ולכן הדיבור דהקב\"ה שבא ע\"י לימוד האדם הוא נעלה יותר.\n<b>ויש</b> להוסיף, דכמו שביום הזה כפשוטו שקאי על ראש חודש, הוא רק מולד הלבנה, נקודה בלבד, ואח\"כ היא הולכת ומתגדלת עד ליום הט\"ו שבו קיימא סיהרא באשלימותא<sup data-n=\"3675\">35</sup>, עד\"ז הוא בישראל, שבעת מתן תורה שהי' במדבר סיני, הי' ההתחלה, וע\"י העבודה דישראל לאח\"ז ולאחרי מתן תורה הם הולכים ומתגדלים, ועד שבימי דוד<sup data-n=\"3676\">36</sup> ובימי שלמה הי' קיימא סיהרא באשלימותא<sup data-n=\"3675\">35</sup>. ועיקר המילוי והשלימות יהי' בדרא דמלכא משיחא, שאז יהי' וירד מים עד ים ומנהר עד אפסי ארץ<sup data-n=\"3677\">37</sup>, בכל מקום בשוה, ועד <i>לוימלא</i> כבודו את כל הארץ<sup data-n=\"3678\">38</sup>, מילוי בתכלית השלימות בכל הארץ בשוה.\nז) <b>והנה</b> מבואר בהדרושים<sup data-n=\"3679\">39</sup>, שהתורה נקראת עוז<sup data-n=\"3680\">40</sup> ותושי'<sup data-n=\"3681\">41</sup>, עוז לנפש האלקית ותושי' לנפש הבהמית. וזה שיש בתורה שני ענינים אלה (אף שנתלבשהבענינים גשמיים) הוא, כי מקור התורה ויסודה הוא באוא\"ס ב\"ה בעצמו ובכבודו [וגילוי בחינה זו דתורה הוא כשלימוד התורה של האדם הוא בביטול, כעונה אחר הקורא]. ויש לומר, דשני הענינים דעוז ותושי' הם גם דוגמת שני הענינים דלעיל (סעיף ד) בהחיבור דמעלה ומטה. דזה שהתורה נותנת כח ועוז לנה\"א הוא ע\"ד ירידת והמשכת התורה למטה, וזה שהתורה מתשת כח הנה\"ב הוא ע\"ד הנתינת כח דמ\"ת על עליית התחתונים. וזה שמקור התורה הוא מאוא\"ס ב\"ה, שלכן יש בה שני הענינים דעוז ותושי', הוא ע\"ד המבואר במק\"א<sup data-n=\"3682\">42</sup>, דזה שהתורה (שהיא <i>למעלה</i> מהעולם) ירדה למטה ופועלת בהמטה, הוא ע\"י שנמשך בה מהעצמות, שהוא נושא הפכים.\nח) <b>וזהו</b><sup data-n=\"3683\">43</sup> בחודש השלישי גו' ביום הזה באו מדבר סיני, מדבר מלשון דיבור, ונק' מדבר בתוספת מ' להורות שהדיבור הוא בביטול כעונה אחר הקורא (כמבואר בארוכה בהדרושים), ועי\"ז נעשה סיני שירדה שנאה לאומות העולם<sup data-n=\"3684\">44</sup>. דכשלימוד התורה הוא בביטול אזי היא נעשית (עוז לנפש האלקית ו)תושי' לנפש הבהמית, דבירדה שנאה לאומות העולם נכללים גם הגוף ונפש הבהמית<sup data-n=\"3685\">45</sup>. [ולהעיר מתורת הבעש\"ט<sup data-n=\"3686\">46</sup> עה\"פ<sup data-n=\"3687\">47</sup> כי תראה חמור שונאך, כאשר תסתכל בעיון טוב בהחומר שלך הוא הגוף, תראה שהוא שונאך, שהוא שונא את הנשמה].\nט) <b>ולאח\"ז</b><sup data-n=\"3688\">48</sup> אומר ויסעו מרפידים, רפידים הוא על שם שרפו ידיהם מדברי תורה<sup data-n=\"3689\">49</sup>, שאינו מנגד לתורה ואדרבא הוא לומד תורה, אלא שהלימוד שלו הוא ברפיון וחלישות, וע\"י העבודה דמדבר הוא מסיע את עצמו (גם) מהרפיון והחלישות בדברי תורה ועושה תשובה<sup data-n=\"3690\">50</sup> על זה. וממשיך בכתוב (לאחרי שאומר ויסעו מרפידים) ויבואו מדבר סיני גו' נגד ההר, דזה שהי' תחלה ברפידים מביא אותו להתחזק<sup data-n=\"3691\">51</sup> בדברי תורה עוד יותר.\nיו\"ד) <b>ויש</b> לומר, דע\"י שלומדים בתורה פסוק זה עכשיו, הנתינת כח על ויסעו מרפידים הוא עוד יותר. דבפעם הראשונה, הנתינת כח על ויסעו מרפידים היתה ע\"י שבר\"ח סיון נשלמה ההכנה למ\"ת, ועכשיו, יש גם הנתינת כח ממתן תורה שבשנים שעברו, ומלימוד התורה שלאחרי מתן תורה שעי\"ז מיתוסף בענין דמ\"ת (כנ\"ל סעיף ו). ובפרט שנמצאים ביום הט\"ו לחודש שבו קיימא סיהראבאשלימותא, ובזה גופא – בט\"ו בשבט, ראש השנה לאילן<sup data-n=\"3692\">52</sup>, ששייך לארץ טובה ורחבה – ישנה נתינת כח מיוחדת להוסיף בלימוד התורה ובקיום המצוות באופן דארץ טובה ורחבה, ועד\"ז בנוגע לתשובה (ויסעו מרפידים) שתהי' באופן דארץ טובה ורחבה, היינו תשובה עילאה שהיא בשמחה רבה<sup data-n=\"3693\">53</sup>, וכשישראל עושין תשובה מיד הן נגאלין<sup data-n=\"3694\">54</sup>, ואתם תלוקטו לאחד אחד בני ישראל<sup data-n=\"3695\">55</sup>, שהקב\"ה בעצמו<sup data-n=\"3696\">56</sup> מביאם לארץ טובה ורחבה כפשוטה, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, בקרוב ממש.\n**********",[["3640","*","יצא לאור ב<b>קונטרס כ\"ב שבט – תש\"נ</b>, \"לקראת ש\"פ יתרו, כ\"ב שבט – יאָרצייט-הילולא השני של הרבנית הצדקנית מרת חי' מושקא נ\"ע זי\"ע . . <i>עש\"ק פ' יתרו</i>,<i> כ\"ב שבט</i>,<i> שנת ה'תש\"נ</i>\"."],["3641","1","פרשתנו (יתרו) יט, א."],["3642","2","שבת פו, ב."],["3643","3","בא יב, ב."],["3644","4","רד\"ה זה בתו\"א ריש פרשתנו. תקס\"ז (סה\"מ תקס\"ז ע' קמו). תו\"ח פרשתנו שסו, ב [בהוצאה החדשה – ח\"ב רנא, א]. תרנ\"ה (סה\"מ תרנ\"ה ע' פט)."],["3645","5","בפרש\"י כאן \"ביום הזה – בר\"ח\". ומזה שאינו מביא הגז\"ש שבמס' שבת שם, מוכח, שזה מובן מהכתוב עצמו. וכפירוש הספורנו \"ביום הזה – ביום החודש\" (וראה ראב\"ע כאן). אבל גם לפי פירוש זה יש מקום להדיוק דהול\"ל באחד לחודש – ראה פקודי מ, ב. שם, יז. ועוד."],["3646","6","בפרש\"י שם: \"לא הי' צריך לכתוב אלא ביום ההוא, מהו ביום הזה\". ובד\"ה בחודש השלישי ה'תש\"ב בתחלתו (סה\"מ ה'תש\"ב ע' 99) \"טעם אומרו ביום הזה סתם <i>ולא נתפרש באיזה יום</i> . . כפירש\"י כו'\"."],["3647","7","סה\"מ תרס\"ה ס\"ע רלה. עטר\"ת ע' תלח. תרפ\"ה ע' ריא. ה'ש\"ת ע' 116. וראה לקו\"ת שה\"ש מב, א."],["3648","8","תו\"א שם סז, א. סה\"מ תקס\"ז שם ע' קמט. תו\"ח שם שע, ב [בהוצאה החדשה – ח\"ב רנג, ב]. סה\"מ תרנ\"ה שם ע' צא-ב."],["3649","9","פרשתנו כ, א."],["3650","10","תהלים קיט, קעב."],["3651","11","ברכות כב, א."],["3652","12","ולהעיר מסה\"מ תרנ\"ה שם."],["3653","13","ראה עד\"ז סה\"מ תרס\"ה וה'ש\"ת שבהערה 7."],["3654","14","תנחומא וארא טו. שמו\"ר פי\"ב, ג. ועוד."],["3655","15","תהלים קטו, טז."],["3656","16","פרשתנו יט, כ."],["3657","17","משפטים כד, א."],["3658","18","סה\"מ תרמ\"ג ס\"ע פד ואילך. המשך תער\"ב ח\"ב ס\"ע תתקל ואילך. ובכ\"מ. וראה לקו\"ש ח\"ח ע' 24."],["3659","19","ראה לקו\"ש שם."],["3660","20","ראה בארוכה לקו\"ש חט\"ז ע' 212 ואילך. הדרן על הש\"ס (תשמ\"ט) ס\"ה ואילך (תורת מנחם – הדרנים על הרמב\"ם וש\"ס ס\"ע תיז ואילך)."],["3661","21","ראה פסחים סח, ב \"אי לאו האי יומא דקא גרים (יום דמ\"ת) כמה יוסף איכא בשוקא\", ובפירש\"י שם \"שלמדתי תורה <i>ונתרוממתי</i>\". ובלקו\"ש שם (ע' 214), דהשינוי שנעשה בהאדם הלומד תורה, שמתעלה ומתרומם, נתחדש ב\"האי יומא\" דמ\"ת. וראה הדרן הנ\"ל הערה 31 (תורת מנחם שם ס\"ע תיח ואילך). ואכ\"מ."],["3662","22","תניא פ\"ה."],["3663","23","ראה בארוכה המשך תרס\"ו ע' מט ואילך. תער\"ב ח\"ב ע' תתקכ ואילך. סה\"מ ה'תש\"ח ע' 160 ואילך."],["3664","24","המשך תרס\"ו ע' קפט. <i>ובכ\"מ</i>."],["3665","25","ראה תקו\"ז סוף תיקון נז (וראה שם תיקון יט – מ, ב). ז\"ח יתרו לד, סע\"ג. וראה לקמן ח\"ג ע' קעא ואילך. קפ ואילך. וש\"נ."],["3666","26","ראה סה\"מ תרמ\"ג ע' עה. המשך תער\"ב ח\"א ע' רנ. ובכ\"מ."],["3667","27","תניא פמ\"א (נח, א). המשך תרס\"ו ע' לו. שם ע' נה. ועוד."],["3668","28","לקו\"ת במדבר יג, א-ב. קונטרס עץ החיים פ\"ב. ובכ\"מ."],["3669","29","מנחות בסופה. שו\"ע אדה\"ז או\"ח מהדו\"ת סוף ס\"א. מהדו\"ק שם סי\"א. הל' ת\"ת פ\"ב סי\"א. וראה לקו\"ש חי\"ח ע' 413 הערה 25 ובשוה\"ג שם."],["3670","30","לכאורה הי' מקום לקשר זה עם מרז\"ל (ראה מדרש תהלים צ, ד. ב\"ר פ\"ח, ב. תנחומא וישב ד. זח\"ב מט, א) שהתורה קדמה לעולם, כי גדר העולם הוא מקום וזמן (שעהיוה\"א פ\"ז – פב, א), וכיון שהתורה קדמה לעולם היא למעלה מזמן ומקום. וע\"פ הידוע (המשך תער\"ב שבהערה 23) שהגדר דזמן ומקום הוא לא רק בהעולם עצמו אלא גם בהאור שבערך העולמות, וכנ\"ל (סעיף ג) שבאור הקו ישנם הענינים דמעלה ומטה (מקום) וקדימה ואיחור (זמן), שהם השרש דמקום וזמן שבעולמות, יש לומר, דזה שהתורה היא למעלה מזמן ומקום הוא לפי ששרשה הוא באוא\"ס שלפני הצמצום, ויתירה מזו, שבהאור שלפני הצמצום גופא, שרש התורה הוא בעצמות אוא\"ס שלמעלה מהאור השייך לעולמות. ומזה מובן שבירידת העליונים למטה שבנתינת התורה נכלל גם אור הבל\"ג שלמעלה מהגדר דמעלה ומטה שבעולמות.\nאבל סיום מרז\"ל זה שקדמה אלפיים שנה – שולל פי' זה."],["3671","31","תקו\"ז תכ\"ב (סד, ב), הובא בתניא פל\"ו (מו, א). וראה תנחומא שמות כה. שמו\"ר פ\"ה, ט."],["3672","32","וע\"ד מקום ארון אינו מן המדה (יומא כא, א. וש\"נ). וראה ד\"ה באתי לגני ה'תש\"ל (לעיל ע' שלה) ס\"ג, ובהערה 22 שם."],["3673","33","סה\"מ תרנ\"ו ע' שנו. המשך תרס\"ו ע' כג. שם ע' תקמו. תער\"ב ח\"א ע' שסו. סה\"מ עטר\"ת ע' רצא. תרפ\"ה ע' קצט. ה'תש\"ט ע' 57. ועוד."],["3674","34","תו\"א פרשתנו סז, סע\"ג. תו\"ח שם שעג, א [בהוצאה החדשה – ח\"ב רנה, ב]."],["3675","35","ראה זהר ח\"א קנ, רע\"א. רכה, סע\"ב. רמג, סע\"א. ח\"ב פה, א. רטו, א. ח\"ג מ, ב. מו, א. וראה שמו\"ר פט\"ו, כו."],["3676","36","ראה לקו\"ש ח\"ח ע' 24 הערה 26."],["3677","37","תהלים עב, ח.\nולהעיר, שע\"פ המנהג לומר הקאַפּיטל תהלים המתאים למספר שנותיו (קובץ מכתבים אודות גודל ערך אמירת תהלים. אגרות-קודש כ\"ק אדמו\"ר מוהריי\"צ ח\"א ע' לא. ח\"י ס\"ע נג. סה\"מ י\"א ניסן ע' 1 ואילך) – אומרים מזמור עב שבתהלים החל מי\"א ניסן תשל\"ג עד י\"א ניסן שנה זו דאמירת המאמר (תשל\"ד)."],["3678","38","תהלים שם, יט."],["3679","39","תו\"א פרשתנו סז, סע\"א ואילך. סה\"מ תקס\"ז שם ע' קמח ואילך. תו\"ח שם שסט, ב ואילך [בהוצאה החדשה – ח\"ב רנג, א]. סה\"מ תרנ\"ה ע' צ ואילך."],["3680","40","מדרש תהלים ח, ג. ויק\"ר פל\"א, ה. מכילתא בשלח טו, ב. יל\"ש שם רמז רמד. שהש\"ר פ\"א, ד. פ\"ב, ג."],["3681","41","סנהדרין כו, ב."],["3682","42","ראה הדרן הנ\"ל ס\"ט (תורת מנחם שם ע' תכא ואילך), ובהערות שם."],["3683","43","בהבא להלן – ראה תו\"א שם סז, סע\"ג ואילך. סה\"מ תקס\"ז שם ע' קנב. תו\"ח שם שעג, ב [בהוצאה החדשה – ח\"ב רנה, ב] (וראה שם שעב, ב [שם רנה, א]). סה\"מ תרנ\"ה ע' צד."],["3684","44","שבת פט, סע\"א ואילך."],["3685","45","ראה תו\"א בראשית ב, ב. לקו\"ת דרושים לשמע\"צ צ, ד."],["3686","46","\"היום יום\" כח שבט. כתר שם טוב (הוצאת קה\"ת תשנ\"ט) בהוספות סי' כא. וש\"נ."],["3687","47","משפטים כג, ה."],["3688","48","פרשתנו יט, ב."],["3689","49","מכילתא ויל\"ש עה\"פ בשלח יז, ח. וראה סנהדרין קו, סע\"א ובפרש\"י שם."],["3690","50","להעיר מפרש\"י עה\"פ (יט, ב)."],["3691","51","ראה תניא פ\"ז (יב, א). אגה\"ת ספ\"ח."],["3692","52","מס' ר\"ה בתחלתה."],["3693","53","אגה\"ת פי\"א (קי, סע\"ב ואילך)."],["3694","54","רמב\"ם הל' תשובה פ\"ז ה\"ה."],["3695","55","ישעי' כז, יב."],["3696","56","ראה רש\"י עה\"פ נצבים ל, ג."]]],[1500370050,"הנחה\n<b>הנני</b> ממטיר לכם לחם מן השמים גו' (ומבאר שזהו) למען אנסנו הילך בתורתי אם לא<sup data-n=\"3697\">1</sup>. וידועים דיוקי רבותינו נשיאינו בכתוב זה<sup data-n=\"3698\">2</sup>, מהו הקשר דענין המן (לחם מן השמים) עם ענין התורה. ובפרט שאומר למען אנסנו אם יוכל להיות קבלת התורה, היינו שמנסיון זה ידעו אם ילך בתורתי אם לא, שבנסיון זה תלוי ענין קבלת התורה. וגם מהו לשון הילך בתורתי, הול\"ל כבכ\"מ לשון של לימוד, המתאים לתורה להיותה ענין של שכל, או הישמור תורתי וכיו\"ב. עוד צלה\"ב, דהנה מכיון שאומרים בחמשה עשר באייר<sup data-n=\"3699\">3</sup> הנני ממטיר לכם לחם מן השמים, הרי מובן שזהו דבר חידוש לגבי הלחם מן הארץ שהיו אוכלים עד חמשה עשר באייר, ולכאורה אי\"מ שהרי ישנה מעלה גדולה בהלחם מן הארץ שאכלו אז שהי' מהעוגות מצות שאכלו בארץ מצרים שע\"ז נצטוו על מצות ומרורים יאכלוהו<sup data-n=\"3700\">4</sup>, דענין המצה ה\"ה קשור עם הגאולה, וכמבואר בדרושי פסח<sup data-n=\"3701\">5</sup> דענין המצה (הנה אע\"פ שהו\"ע של קטנות, מ\"מ) הוא קטנות אבא וכמאמר<sup data-n=\"3702\">6</sup> אין התינוק יודע לקרות אבא כו' עד שיטעום טעם דגן, דעי\"ז הי' הגילוי דנגלה עליהם ממה\"מ הקב\"ה בכבודו ובעצמו וגאלם<sup data-n=\"3703\">7</sup>, שמכ\"ז מובן גודל העילוי דלחם מן הארץ, ואעפ\"כ אומרים ש(אי\"ז מספיק ו)ישנו חידוש שנתוסף דוקא ע\"י הלחם מן השמים. עוד צלה\"ב, דהרי החידוש דלחם מן השמים הי' בזה שבא שלא ע\"י עבודת ויגיעת האדם כלחם מן הארץ, אלא כמ\"ש הנני ממטיר לכם, היינו שבא מלמעלה, וא\"כ אי\"מ מהו הלשון ממטיר, הלא ענין המטר הוא לא כענין הטל שטל לא מיעצר<sup data-n=\"3704\">8</sup>, אלא הוא תלוי בעבודת האדם, וכמבואר בדרושי האזינו<sup data-n=\"3705\">9</sup> החילוק בין יערוף כמטר לקחי ותזל כטל אמרתי<sup data-n=\"3706\">10</sup>.\nב\n)\n<b>והנה</b> במשנה תורה<sup data-n=\"3707\">11</sup> כתיב ויאכילך את המן גו' למען הודיעך כי לא על הלחם לבדו יחי' האדם כי על כל מוצא פי הוי' יחי' האדם, והיינו דנוסף לזה שענין המן הוא למען אנסנו הילך בתורתי גו', ישנו עוד ענין בהמן, שהוא למעןהודיעך כי לא על הלחם לבדו יחי' האדם כי על כל מוצא פי הוי' יחי' האדם. וצ\"ל שייכות ב' הענינים זל\"ז. עוד צלה\"ב, דלכאורה יש בזה תמיהה גדולה ונפלאה, למה צריכים (אָנקומען) להמן כדי לידע שכל המציאות כולה תלוי' במוצא פי הוי', והרי לכאורה הוא דבר פשוט שלעולם הוי' דברך נצב בשמים<sup data-n=\"3708\">12</sup>, היינו שהמוצא פי הוי' שבכל דבר הוא המהווה ומחי' ומקיים אותו<sup data-n=\"3709\">13</sup>, שענין זה הוא באמונה פשוטה אצל כאו\"א מישראל שנקראו מאמינים בני מאמינים עוד בהיותם בארץ מצרים<sup data-n=\"3710\">14</sup>, עאכו\"כ לאחרי היציאה ממצרים, שנגלה עליהם ממה\"מ הקב\"ה בכבודו ובעצמו כו', ובפרט לאחרי קריעת י\"ס בשביעי של פסח שאז אמרו זה א-לי ואנוהו<sup data-n=\"3711\">15</sup>, וא\"כ ה\"ז לכאורה בפשטות שעל כל מוצא פי הוי' יחי' האדם, ומהו החידוש דהנני ממטיר לכם לחם מן השמים, ויאכילך את המן גו' שעי\"ז דוקא באה הידיעה שלא על הלחם לבדו יחי' האדם כי על כל מוצא פי הוי' יחי' האדם.\nג) <b>אך</b> כללות נקודת הביאור בזה היא, דהחידוש דלחם מן השמים בא לאחרי שהי' הענין דלחם מן הארץ בתכלית העילוי שלו, ואעפ\"כ אומרים שישנו עילוי גדול יותר בלחם מן השמים (כדלקמן). ועד\"ז הוא בנוגע להחידוש דלמען הודיעך כי לא על הלחם לבדו יחי' האדם, דאין הכוונה בזה להודיע שאין העולם ח\"ו באופן שאין בעה\"ב לבירה זו והלחם הוא מציאות בפ\"ע, אלא שזה הי' ידוע בפשטות שהלחם מתהווה מפי הוי' שבו, ממכ\"ע, אבל עדיין אי\"ז הידיעה דאמיתית הענינים, שממוצא פי הוי' יחי' האדם.\nד) <b>ויובן</b> כ\"ז בהקדם הביאור בהחילוק שבין לחם מן השמים ללחם מן הארץ כפי שהוא ברוחניות הענין. שזהו בדוגמת החילוק בעבודה בין תורה למצוות. דהעבודה דתורה היא באופן דהמשכה מלמעלמ\"ט, הלא כה דברי גו'<sup data-n=\"3712\">16</sup> ואשים דברי בפיך גו'<sup data-n=\"3713\">17</sup>, היינו שזהו דבר הוי' שנמשך למטה (לחם מן השמים). ולכן אין שייך בזה שינויים דהתורה היא נצחית<sup data-n=\"3714\">18</sup>. משא\"כ מעשה המצוות, הנה אע\"פ שגם זה בא ע\"י לימוד התורה וכמאמר<sup data-n=\"3715\">19</sup> גדול לימוד שמביא לידי מעשה, מ\"מ הרי זה קשור בפעולת האדם שצריך לעשות מהקלף גשמי שיהי' הענין דתפילין, ומהצמר גשמי שיהי' הענין דציצית וכו' (שזהו\"ע מן הארץ). ובתוספת ביאור יובן זה מב' הענינים כפי שהם בתורה עצמה (שהרי כל הענינים שבעולם תחלתם היא כפי שהם בתורה), שזהו תושב\"כ ותושבע\"פ<sup data-n=\"3716\">20</sup>. דבתושב\"כ הרי כל אות וכל תג הוא מנוי וספור בדיוק, ואיןשייך לומר בזה לא הוספה ולא גרעון ח\"ו (מן השמים), משא\"כ בתושבע\"פ כתיב<sup data-n=\"3717\">21</sup> ארוכה מארץ מדה ורחבה מני ים, ועד באופן דועלמות אין מספר<sup data-n=\"3718\">22</sup>, בל\"ג, שזה בא<sup data-n=\"3719\">23</sup> ע\"י יגיעת האדם (מן הארץ) דיגעת ולא מצאת אל תאמין<sup data-n=\"3720\">24</sup>, דמכיון שהוא יגע כדבעי (כפי תביעת התורה) הרי דבר ברור שעי\"ז יש לו לפי אופן היגיעה, ועד לאופן של מציאה ומצאת. והנה כמו שהוא בקו התורה, כן הוא גם בשאר הב' קוין דגמ\"ח (מצוות) ועבודה. דישנו חילוק זה (בקו הגמ\"ח) בין עבודתו הרוחנית (מצוות) לעבודתו עם העולם באופן שצריך יגיעת נפש ויגיעת בשר כדי להפוך את העולם שיהי' דירה לו ית' בתחתונים. ועד\"ז ישנם ב' ענינים אלו בעבודה גופא (שהיא הממוצע בין תורה לגמ\"ח), דישנה העבודה דאהבה בתענוגים, ועד\"ז העבודה דיום השבת, וקראת לשבת עונג<sup data-n=\"3721\">25</sup>, שענין העונג (דאהבה בתענוגים ודשבת) קשור עם ענין המנוחה, היינו שאין אז כל ענין היגיעה, וכמבואר בתניא<sup data-n=\"3722\">26</sup> דאהבה בתענוגים ענינה הוא דוגמת מתן שכר כו', משא\"כ העבודה, מלשון עבוד עורות<sup data-n=\"3723\">27</sup> והעבודה דימות החול, שכללות ענין עבודות אלו הוא ע\"י יגיעה ועבודה גדולה.\nה) <b>וזהו</b> ויאכילך את המן גו' למען הודיעך כי לא על הלחם לבדו יחי' האדם כי על כל מוצא פי הוי' יחי' האדם, דבזה יובן דהחידוש דלחם מן השמים על לחם מן הארץ ה\"ה אפי' כפי שהלחם מן הארץ הוא בדרגא הכי נעלית שבו (וכנ\"ל דגם לחם מן הארץ ברוחניות הענינים הו\"ע נעלה כו'). דהנה הקס\"ד דעל הלחם לבדו יחי' האדם היא בדוגמת מה שאומרים דכללות הבריאה כולה היא באופן דעולם מלשון העלם והסתר<sup data-n=\"3724\">28</sup> אע\"פ שעולם על מילואו נברא<sup data-n=\"3725\">29</sup>. שזהו מפני ששם מתגלה רק הענין דממכ\"ע (בלשון הזהר והקבלה). וע\"ז אומרים דתכלית השלימות דבנ\"י היא לידע שלא על הלחם לבדו יחי' האדם כי על כל מוצא פי הוי' יחי' האדם, דמוצא הוא לשון מקור ושרש כמבואר בכ\"מ<sup data-n=\"3726\">30</sup>, דבערך הענין דממכ\"ע זהו\"ע סוכ\"ע, ובכללות יותר הו\"ע שלמעלה מממלא וסובב, שלמעלה מכל סדר ההשתלשלות, שזהו ע\"ד ענין הטל דטל לא מיעצר<sup data-n=\"3727\">31</sup>. וכדי שתהי' ידיעה זו, לכן ויאכילך את המן גו', דענין זה (דלחם מן השמים, מוצא פי הוי') נעשה דם ובשר כבשרו, היינו אַז דאָס האָט דורכגענומען גם את הדם ובשר כו'<sup data-n=\"3728\">32</sup>.ו) <b>וזהו</b> החידוש דלחם מן השמים, דאע\"פ שכבר הי' לפנ\"ז הענין דלחם מן הארץ, וע\"י היו גילויים נעלים ונפלאים, וכנ\"ל דאין התינוק יודע לקרות אבא כו' עד שיטעום טעם דגן, ועד שהענין דלחם מן הארץ פעל (את הענין דיודע לקרות אבא) שכבר אמרו זה א-לי ואנוהו&lt;15&gt;, מ\"מ יכול להיות כ\"ז (אך) בבחי' ממכ\"ע. דאע\"פ שלפי שעה הי' הענין דנגלה עליהם ממה\"מ הקב\"ה בכבודו ובעצמו וגאלם&lt;7&gt;, ועד\"ז בקרי\"ס הי' גילוי נעלה יותר מגילוי הנבואה לגדול שבנביאים<sup data-n=\"3729\">33</sup>, מ\"מ הרי הי' זה רק לפי שעה, אבל אח\"כ היתה העבודה (מסודרת) מיום ליום ודרגא אחר דרגא, שמזה מוכח שזה שייך לממכ\"ע, שבא בסדר והשתלשלות. ולכן כשהיו צריכים לקבל את התורה ובאופן כזה שנתחדש ע\"י מתן תורה (היינו למעלה יותר מענין התורה שהי' לפנ\"ז, דקיימו כל התורה כולה עד שלא ניתנה<sup data-n=\"3730\">34</sup>), שזהו ענין התורה כפי שהיא בבחי' הליכה דוקא, דאמיתית ענין ההליכה הוא בל\"ג<sup data-n=\"3731\">35</sup> עד באופן דאי\"ע, ועד באופן כזה שאפילו כשהגיע כבר להבל\"ג שבתורה הרי זה גבול לגבי ענין התורה שצריך לבא אליו ע\"י קיום הציווי (שהוא גם נתינת כח) דמעלין בקודש<sup data-n=\"3732\">36</sup>, הנה כהקדמה לזה הי' צ\"ל הנני ממטיר לכם לחם מן השמים, שלמעלה מממכ\"ע וכו'. ולכן הנה אף שכבר נמצאו אז בדרגא נעלית כנ\"ל, והי' במצב שנק' לכתך אחרי במדבר בארץ לא זרועה<sup data-n=\"3733\">37</sup>, מ\"מ נק' זה לכתך אחרי דוקא, שאי\"ז ענין הפנימיות וכמבואר בארוכה במאמרים שלפנ\"ז<sup data-n=\"3734\">38</sup>, ועד שכללות העבודה במשך זמן הגלות, ויתירה מזה כללות העבודה בעולמות בי\"ע הנה הכל הוא בחיצוניות עתיק, ודוקא לע\"ל יתגלה בחי' פנימיות עתיק<sup data-n=\"3735\">39</sup>. ומכיון שזהו חיצוניות עתיק (נק' לכתך אחרי, כי) אי\"ז אמיתית ענין הפנים, ואמיתית ענין הפנים שבתורה הוא באופן שאין שם כלל מציאות דאחור, וכמו הלוחות שלא הי' בהם פנים ואחור (אלא כולו פנים<sup data-n=\"3736\">40</sup>) כמבואר לעיל<sup data-n=\"3734\">38</sup> בארוכה, שזהו בחי' השיר שבתורה.\nז) <b>וזהו</b> הנני ממטיר גו' למען אנסנו הילך בתורתי גו'. דבכדי לבא לבחינת הליכה בתורה, הנה לפנ\"ז צ\"ל הענין דמן, וכמאמר המכילתא<sup data-n=\"3737\">41</sup> לא ניתנה תורה אלא לאוכלי המן, והדיוק בזה הוא לאוכלי המן (וכנ\"ל בפי' ויאכילך את המן), שהמן צ\"ל באופן שנעשה דם ובשר כבשרו. דענין המן הוא שלא הי' בו פסולת, שהוא למעלה לגמרי מסדר ההשתלשלות<sup data-n=\"3738\">42</sup>, מכיון שהוא למעלה מממכ\"ע ומסוכ\"ע וגם למעלה מדרגא הג' (שלמעלה מממלא וסוכ\"ע). וע\"י שענין זה בא באופן דאכילהונעשה דם ובשר כבשרו, הנה עי\"ז נהי' הענין דאנסנו, ד[כמבואר בכמה דרושים<sup data-n=\"3739\">43</sup> וגם בספרי השרשים הרי] אנסנו הו\"ע של הרמה והגבהה כמו ארים נסי<sup data-n=\"3740\">44</sup>, כי ע\"י אכילת המן מגביהים אותו למעלה מכל סדר ההשתלשלות שעי\"ז באים לבחי' ההליכה בתורה. וזהו<sup data-n=\"3741\">45</sup> מ\"ש<sup data-n=\"3742\">46</sup> עומר לגולגולת דוקא, דענין הגולגולת הוא למעלה אפילו מהראש, וכמ\"ש<sup data-n=\"3743\">47</sup> שאו את ראש כל עדת בני ישראל גו' לגולגלותם, היינו<sup data-n=\"3744\">48</sup> שהרמת הראש (שאו את ראש) היא לגולגלותם שלמעלה מהראש, וזה הי' גם ענין המן שהי' עומר לגולגולת דייקא, כי ענינו הוא לפעול בישראל הידיעה דלא על הלחם לבדו (ממכ\"ע) יחי' האדם כי על כל מוצא פי הוי' יחי' האדם, וכמשנת\"ל.\nח) <b>ולהבין</b> לשון ממטיר דוקא, הנני ממטיר לכם גו', הנה יובן זה מהמבואר בלקו\"ת בדרושי פ' עקב<sup data-n=\"3745\">49</sup>, דאף שבכללות הנה המן הוא בחי' טל (כנ\"ל), אעפ\"כ נתגשם עד שדכו במדוכה ובשלו בפרור<sup data-n=\"3746\">50</sup>, ועד שאפי' בצדיקים שאצלם הי' אכילת המן בלי טרחא, מ\"מ הי' צ\"ל ולקטו מעל פתח האוהל<sup data-n=\"3747\">51</sup>, ואח\"כ הי' צ\"ל האכילה כפשוטה, ועד שמבואר בראשונים<sup data-n=\"3748\">52</sup> שהי' גם ענין הברכה המוציא לחם מן השמים או בנוסח אחר וכו'<sup data-n=\"3748\">52</sup>. אבל מ\"מ, ע\"י שראו ואכלו המן ששרשו הוא מטלא דבדולחא, ונמשך למטה עד שנתגשם [כמבואר בדרושי כ\"ק אדה\"ז משנת תקס\"ח ועוד<sup data-n=\"3749\">53</sup>], עי\"ז יוודע להם שלא על הלחם לבדו יחי' האדם<sup data-n=\"3750\">54</sup>, היינו (לא שאי\"צ להיות ענין אכילת הלחם, אלא שצריך להיות אכילה (שלכן נתגשם המן), אמנם) השלילה היא שאין זה על הלחם <i>לבדו</i>, היינו בחי' ממכ\"ע שבזה (כמשנת\"ל), אלא על כל מוצא פי הוי' יחי' האדם, ע\"י שהמוצא פי הוי' מתלבש בהלחם, כמו שהמן נתגשם כו'. וכמש\"נ בתורה שהיא נעלמה מעיני כל חי<sup data-n=\"3751\">55</sup>, ואהי' שעשועים לפניו גו'<sup data-n=\"3752\">56</sup>,ומשם נסעה וירדה בסתר המדרי' ממדרגה למדרגה כו' עד שנתלבשה כו' בדיו על הספר<sup data-n=\"3753\">57</sup>, באותיות התורה<sup data-n=\"3754\">58</sup>.\nט) <b>וזהו</b> כללות הענין דהנני ממטיר לכם לחם מן השמים, דאע\"פ שישראל היו לפנ\"ז ברום המעלות, הנה אעפ\"כ, כשהנני ממטיר לכם לחם מן השמים הרי אין דרגתם שלפנ\"ז מגיעה להמעלה שצריכה להיות אצלם ע\"י ענין זה. הן בנוגע ללימוד התורה, שצ\"ל באופן של הליכה, הילך בתורתי (שלי דוקא ע\"ד החילוק דמצוות הוי' ומצוותי<sup data-n=\"3755\">59</sup>), ובפרט ע\"פ המבואר בתו\"א<sup data-n=\"3756\">60</sup> דבההליכה שבפסוק זה (הילך בתורתי) ישנם ב' הענינים דמלמעלמ\"ט ומלמטלמ\"ע, והן בנוגע להעבודה דכל מעשיך יהיו לשם שמים ובכל דרכיך דעהו<sup data-n=\"3757\">61</sup>, שכללות צרכי האדם נק' בשם אכילה<sup data-n=\"3758\">62</sup>, הנה ע\"י המן נפעל דאע\"פ שיודע שלחם זה יש קס\"ד לומר שעליו לבדו יחי' האדם, כי הכוונה היא ללחם זה כמו שהוא בתכלית השלימות (כמשנת\"ל), אעפ\"כ הרי זהו רק לחם מן הארץ, ולא על הלחם לבדו יחי' האדם כי על כל מוצא פי הוי' יחי' האדם. ובזה גופא למען הודיעך דייקא, היינו שאין זה רק באופן של אמונה, כ\"א ידיעה ובתכלית השלימות דידיעה, שיודע בעת אכלו את הלחם שאז מקבל חיות ממוצא פי הוי' שע\"י יחי' האדם.\nי) <b>והנה</b> התורה היא נצחית&lt;18&gt;, ולכאורה צלה\"ב במה הנצחיות של כל הפרטים ושל כללות הענין דהנני ממטיר לכם לחם מן השמים. עוד צלה\"ב, דהנה איתא בברכות<sup data-n=\"3759\">63</sup> משה תקן לישראל ברכת הזן בשעה שירד להם מן (שלכן אומרים הזן לשון נסתר<sup data-n=\"3760\">64</sup>) יהושע תקן להם ברכת הארץ (על הארץ ועל המזון, ארץ דמפקא מזון<sup data-n=\"3761\">65</sup>), ומחוייבים גם עתה, שהברכה הראשונה דברכת המזון היא ברכת הזן שהיא על המן. והענין הוא כמשנת\"ל<sup data-n=\"3762\">66</sup> בארוכה, דאפילו כשהעבודה היא (מאיזה טעם שיהי') רק ביחו\"ת, מ\"מ צריכים עכ\"פ מזמן לזמן גם להארה מיחו\"ע<sup data-n=\"3763\">67</sup> ועד שזה יפעול בגלוי. ועד\"ז כשהעבודה היא רק באופן דאתכפיא, מ\"מ צ\"ל ההתבוננות עכ\"פ בהשגה גם בהענין דאתהפכא. ועד\"ז הוא בלימוד התורה, דאף שעיקר הלימוד הוא לכאורה בנגלה דתורה, ששם הוא ענין היגיעה, אעפ\"כ מוכרח להיות גם העניןדפנימיות התורה<sup data-n=\"3764\">68</sup>, וכמבואר בארוכה בקונטרס עץ החיים<sup data-n=\"3765\">69</sup> ובכמה דרושים. ואדרבה, הענין דפנימיות התורה הו\"ע דמלח שע\"י הוא קיום כל הלימוד. וכדאיתא בשבת<sup data-n=\"3766\">70</sup> משל לאדם שאמר לשלוחו העלה לי כור חטים לעלי' [היינו ענין החטים כפי שהוא באופן נעלה] כו' עירבת בהם קב חומטין א\"ל לאו כו', היינו שבלי ענין המלח<sup data-n=\"3767\">71</sup>, אין קיום אפי' לכור של חטים ושבעלי'. ועד\"ז הוא בכללות העבודה דעולמות בי\"ע, הרי אמרז\"ל שצ\"ל כשם שאין בלבך אלא אחד כך אין בלבנו אלא אחד<sup data-n=\"3768\">72</sup>, היינו שצריכים לזכור מה שאין בלבך (של יעקב, אצילות) אלא אחד, וזה פועל שאין בלבנו (השבטים, בי\"ע) אלא אחד כשם שאין בלבך כו'. והיינו דנוסף לזה שישנו הענין דועד, יש לו גם הענין דאחד. דאף שהענין דועד הוא המשכת מלכותו של הקב\"ה בכל העולמות כולם, מ\"מ אין זה מגיע להענין דאחד, כי אף שועד בחילופי אתוון אחד<sup data-n=\"3769\">73</sup>, הרי אין זה מגיע להאתוון כפי שהם קודם החילוף, וכמובן מהמבואר בשער היחוד והאמונה<sup data-n=\"3770\">74</sup> ענין החילופים כו'.\nיא) <b>ובזה</b> יובן הנצחיות שבענין המן (דהתורה היא נצחית), דהיינו שבכל מקום ובכל זמן ובכל מעמד ומצב שיהודי נמצא, צריך לדעת שזה שיש לו הלחם מן הארץ, היינו כל הענינים שמקבל ע\"י שעושה כלי בדרך הטבע, בכל מלאכתך אשר תעשה<sup data-n=\"3771\">75</sup>, הנה לא על הלחם לבדו יחי' האדם כי על כל מוצא פי הוי' יחי' האדם. כי בהענין שמקבל בדרך הטבע ישנו שם המוצא פי הוי' שהוא השרש ומקור דכל הענינים כפי שהוא באלקות, עד למקור כל המקורות ושרש כל השרשים, שזה בא בהעשי' דכל מלאכתך אשר תעשה בעולם הזה התחתון בזמן הגלות ובחושך כפול ומכופל. ועד\"ז הוא גם בעבודתו, דאע\"פ שעבודתו היא באופן דאחרי ה\"א תלכו<sup data-n=\"3772\">76</sup>, באופן דיחו\"ת ובאופן דאתכפיא, מ\"מ יש לו הנתינת כח מענין המן, ועד שזה בא בגלוי. וכמובן מהמבואר<sup data-n=\"3773\">77</sup> בענין דלגבי משה מילתא זוטרתא היא<sup data-n=\"3774\">78</sup>, שלכן היא מילתא זוטרתא גם אצל כאו\"א מישראל, הנה עד\"ז הוא בעניננו דהנני ממטיר לכם לחם מן השמים שהוא בזכות משה<sup data-n=\"3775\">79</sup>, ומשה תקן ברכת הזן, שלכן ישנו זה אצל כאו\"א מישראל בכל מקום ובכל זמן ובכל מעמד ומצב שיהי'. וכמו שהוא בעבודה בכלל, כן הוא גם בלימוד התורה, דבאיזו דרגא בלימוד התורה שיהי', אפי' כשהתינוקשמתחיל לדבר שמלמדים אותו תורה, הנה אומרים תורה צוה לנו משה<sup data-n=\"3776\">80</sup>, שבלימוד ודיבור זה יש לו כבר הענין דמשה, וכמבואר לעיל שענין המן שייך להכרה וידיעה שזהו\"ע התורה, וממשיך ענין זה למטה עד שנעשה דם ובשר כבשרו ברוחניות, ועד שנעשה דם ובשר כבשרו גם בגשמיות כפשוטו&lt;32&gt;.\nיב) <b>והנה</b> גילוי ענין זה הוא ע\"י הפצת המעיינות דפנימיות התורה חוצה, שבא בגלוי עכ\"פ בידיעה, עכ\"פ באופן של עומר, במדידה והגבלה, שלכן כתיב לשון ממטיר (ולא טל כבכל המקומות). וזה פועל שכמו שהי' בענין המן בפעם הראשונה, שהי' עומר לגולגולת (כמשנת\"ל) ואח\"כ אכלו אותו ונהי' דם ובשר כבשרו גם בעקב שברגלים, הנה כן גם עתה מתגלה ענין הגולגולת הנ\"ל. וכמשנת\"ל דבכל מקום ובכל זמן ובכל מעמד ומצב שיהי', הרי החל מהענין בעבודה, הנה אף שבגלוי ישנו אצלו הענין דועד, מ\"מ יודע שכשם שאין בלבך אלא אחד כך אין בלבנו אלא אחד, כי בלבבו פנימה ישנו הענין דאחד ממש, דלא כבחיצוניות שיש אצלו הענין דחילופי אתוון אחד, ועד\"ז הוא גם בתורה, דמשהתינוק מתחיל לדבר כו' מלמדו תורה צוה לנו משה, ועאכו\"כ כשכבר גדל בלימוד התורה ויש לו הענין דפנימיות התורה, הנה זה מגלה אח\"כ הפנימיות דעולם. וזה נעשה ההכנה קרובה ומביא אח\"כ את הגאולה האמיתית והשלימה ע\"י משיח צדקנו, שאז יהיו הענינים דפנימיות עתיק בגלוי, ועד שיהי' אז ולא יכנף עוד מוריך<sup data-n=\"3777\">81</sup>, ויהי' הגילוי פנים בפנים כמבואר בתניא פל\"ו. וכבר הי' מעין זה בעת מתן תורה, שאז הי' בפעם הא' הענין דלמען אנסנו, הגבהה באופן שיהי' הליכה בתורה ילך בתורתי, וכמו שהי' מעין זה בשעת מתן תורה יהי' זה בגלוי ממש ובקרוב ממש בימות המשיח [אע\"פ שעיקר קבלת השכר הוא באלף השביעי, כמבואר בתניא שם בהגה\"ה], בגאולה האמיתית והשלימה ע\"י משיח צדקנו.\n**********",[["","","*) יצא לאור בשעתו, \"<i>ער\"ח אדר</i>,<i> ה'תשל\"ז</i>\"."],["3697","1","בשלח טז, ד."],["3698","2","תו\"א סה, סע\"א ואילך. אוה\"ת בשלח ע' תקצו. ועוד."],["3699","3","בשלח שם א. וראה פרש\"י שם (משבת פז, ב)."],["3700","4","בהעלותך ט, יא. וראה בא יב, ח."],["3701","5","לקו\"ת צו יג, ג ואילך. וראה אוה\"ת בשלח ע' תקפט."],["3702","6","ברכות מ, א."],["3703","7","נוסח ההגדה."],["3704","8","תענית ג, א."],["3705","9","לקו\"ת האזינו עג, ב ואילך. ובכ\"מ."],["3706","10","האזינו לב, ב."],["3707","11","עקב ח, ג."],["3708","12","תהלים קיט, פט."],["3709","13","שעהיוה\"א בתחלתו."],["3710","14","ראה שבת צז, רע\"א."],["3711","15","בשלח טו, ב. וראה פרש\"י שם."],["3712","16","ירמי' כג, כט."],["3713","17","ישעי' נא, טז."],["3714","18","תניא רפי\"ז."],["3715","19","קידושין מ, ב."],["3716","20","ראה אוה\"ת בשלח ע' תקצ."],["3717","21","איוב יא, ט. וראה עירובין כא, א."],["3718","22","שה\"ש ו, ח ובשהש\"ר עה\"כ."],["3719","23","ראה גם המשך תרס\"ו ע' תה ואילך."],["3720","24","מגילה ו, ב."],["3721","25","ישעי' נח, יג."],["3722","26","פי\"ד."],["3723","27","תו\"א משפטים עו, א. וראה לקו\"ת ויקרא ב, ד."],["3724","28","לקו\"ת שלח לז, ד."],["3725","29","ראה ב\"ר פי\"ב, ו. פי\"ד, ז."],["3726","30","ראה לקו\"ת צו יג, רע\"ג (בעניננו). מסעי צו, א. ובכ\"מ."],["3727","31","ראה לקו\"ת עקב יד, ב."],["3728","32","ראה תניא פ\"ה."],["3729","33","ראה מכילתא ופרש\"י עה\"פ."],["3730","34","יומא כח, ב."],["3731","35","ראה ד\"ה צאינה וראינה תר\"ס. ובכ\"מ."],["3732","36","ברכות כח, א. וש\"נ."],["3733","37","ירמי' ב, ב. וראה גם המשך תרס\"ו ס\"ע רמא ואילך."],["3734","38","ד\"ה באתי לגני שנה זו פ\"ז ואילך. פ\"י (לעיל ס\"ע שפז ואילך. ע' שצג ואילך)."],["3735","39","פע\"ח ש' הק\"ש פט\"ו."],["3736","40","שבת קד, א. וראה ירושלמי שקלים פ\"ו ה\"א."],["3737","41","עה\"פ בשלח טז, ד."],["3738","42","ראה תו\"א סה, סע\"ב ואילך. פט, א. אוה\"ת שם ע' תקצט ואילך. תרלה. ובכ\"מ."],["3739","43","ראה גם תו\"א ע, סע\"ד."],["3740","44","ישעי' מט, כב."],["3741","45","ראה אוה\"ת שם ע' תקצד. ס\"ע תרא ואילך."],["3742","46","בשלח טז, טז."],["3743","47","במדבר א, ב."],["3744","48","ראה לקו\"ת ר\"פ במדבר."],["3745","49","יד, א."],["3746","50","בהעלותך יא, ח."],["3747","51","ראה יומא עה, א."],["3748","52","הרמ\"ע מפאנו בס' מאמר שבתות ה' ח\"ב בתחלתו בהמשך דבריו ע\"ד הסעודה דלעת\"ל כותב שכן יברכו אז על המן (השמור בצנצנת). ובס' חסידים (הוצאת מק\"ן) סי' תתתת\"מ: על המן <i>היו</i> מברכים <i>הנותן</i> לחם מן השמים. וראה זח\"ב (סב, ב): נפקי ולקטי ומברכאן שמא קדישא עלי' (ובאוה\"ח – מהרמ\"ק – היינו ברכת המוציא) כו' ומברך למלכא קדישא (שם – היינו ברכת המזון). – וכנראה (כיון שלא הזכירו את הרמ\"ק) שלא הי' זה לעיני כמה דשקו\"ט בכ\"ז (הובאו בשד\"ח כללים כ' כלל ק. נפש חי' – מרגלית – לאו\"ח סר\"ד סי\"ג. תו\"ש חי\"ד בסופו)."],["3749","53","ראה סה\"מ תקס\"ח ע' לו. וראה סה\"מ תקס\"ב ע' סג (בנוגע לטל). הנחות הר\"פ ע' עח. וראה תו\"ח בשלח שג, סע\"א [בהוצאה החדשה – ח\"א רי, ב ואילך]."],["3750","54","ראה תו\"א (פט, א), שגם לאחר שנתגשם ונעשה מזון גשמי \"מלובש בו אורות העליונים ממש. ולכן הוא ג\"כ למטה . . אין בו פסולת\". ובד\"ה והריחו (בסה\"מ אתהלך-ליאזנא ע' רלה ואילך) נראה דהמן למטה הי' <i>מהות</i> השפע דלמעלה."],["3751","55","איוב כח, כא."],["3752","56","משלי ח, ל."],["3753","57","תניא פ\"ד."],["3754","58","לקו\"ת שם (עקב יד, א) – דמה שנתגשם המן הוא דוגמא להתלבשות התורה באותיות גשמיות."],["3755","59","לקו\"ת במדבר ט, ג. ובכ\"מ."],["3756","60","סה, ג."],["3757","61","אבות פ\"ב מי\"ב. משלי ג, ו. וראה רמב\"ם הל' דיעות ספ\"ג."],["3758","62","ראה סנהדרין לח, א: כדי שיכנס <i>לסעודה</i> מיד כו', ובפרש\"י שם."],["3759","63","מח, ב."],["3760","64","תו\"א סו, ב. לקו\"ת עקב יד, ג."],["3761","65","ברכות מט, א."],["3762","66","ד\"ה באתי לגני שנה זו פ\"ז. פי\"א ואילך (לעיל ריש ע' שפט. ע' שצד ואילך)."],["3763","67","ראה אוה\"ת שבהערה 5 שענין המן הוא ד\"ע, שהו\"ע יחו\"ע כמבואר באוה\"ת שם ע' תקצא. ושם, די\"ל ששרש המן הוא למע' מב' הדעות דיחו\"ת ויחו\"ע."],["3764","68","ראה אוה\"ת בשלח (ס\"ע תרו ואילך. תריז ואילך. תרמח) שענין המן בתורה הוא פנימיות התורה. וראה זח\"ב קפג, ב: ומגו ההוא נהמא (מן) הוו ידעין ומסתכלין <i>ברזי דאורייתא</i>."],["3765","69","פי\"ג ואילך."],["3766","70","לא, סע\"א. וראה לקו\"ת ויקרא ו, א."],["3767","71","ראה פרש\"י שבת שם. לקו\"ת שם."],["3768","72","פסחים נו, א."],["3769","73","זח\"ב קלד, א. שעהיוה\"א פ\"ז."],["3770","74","פ\"א. פי\"ב."],["3771","75","פ' ראה טו, יח."],["3772","76","ראה יג, ה."],["3773","77","תניא פמ\"ב."],["3774","78","ברכות לג, ב."],["3775","79","תענית ט, א."],["3776","80","סוכה מב, א."],["3777","81","ישעי' ל, כ."]]],[1500370051,"<h3>בס\"ד. יום ב' פ' יתרו, ט\"ו בשבט, ה'תשל\"ח<sup data-n=\"3778\">*</sup></h3>\n<b>באתי</b> לגני אחותי כלה<sup data-n=\"3779\">1</sup>, ומביא כ\"ק מו\"ח אדמו\"ר [בעל ההילולא דיו\"ד שבט, שהשלימות דכל ימי החודש היא ביום הט\"ו, שבו קיימא סיהרא באשלמותא<sup data-n=\"3780\">2</sup>] במאמרו הידוע ד\"ה זה<sup data-n=\"3781\">3</sup>, דאיתא במדרש<sup data-n=\"3782\">4</sup> דפירוש באתי לגני הוא המשכת וירידת עיקר שכינה למטה בארץ. ועיקר המשכה זו היתה כשהוקם המשכן, כדאיתא במדרש שם ואימת שרתה שכינה עלי' (בארץ) ביום שהוקם המשכן. וכמ\"ש<sup data-n=\"3783\">5</sup> ועשו לי מקדש (ואז) ושכנתי בתוכם. והגם שגם במתן תורה היתה המשכת וירידת השכינה למטה בארץ כמ\"ש<sup data-n=\"3784\">6</sup> וירד הוי' על הר סיני, יש לומר<sup data-n=\"3785\">7</sup>, שעיקר הענין דהמשכת וירידת השכינה למטה בארץ הוא כשההמשכה למטה היא בפנימיות (באופן שהמטה מזדכך ומתעלה עי\"ז<sup data-n=\"3786\">8</sup>), שזהו דוקא כשההמשכה היא ע\"י עבודת המטה, ולכן אומר שעיקר המשכת השכינה בארץ הי' כשהוקם המשכן, כי ההמשכה שהיתה במתן תורה היתה מצד למעלה, שלכן הי' הגילוי לפי שעה, והעילוי דהמשכת השכינה במשכן היא שההמשכה (ושכנתי בתוכם) היא ע\"י עבודה ועשי', <i>ועשו</i> לי מקדש.\n<b>ויש</b> להוסיף, דמעלת ההמשכה במשכן ומקדש (על ההמשכה שהיתה במתן תורה) היא לא רק מצד זה שההמשכה היא ע\"י עבודה (בכלל), אלא גם מצד זה שהעבודה דועשו לי מקדש היא העבודה דאתכפיא ואתהפכא (הפיכת השטות דלעו\"ז לשטות דקדושה)<sup data-n=\"3787\">9</sup>. דגם בהמשכה שבאה ע\"י עבודה, ההמשכה שע\"י העבודה דאתכפיא ואתהפכא היא נעלית יותר מההמשכה שע\"י עבודה בעניני קדושה<sup data-n=\"3788\">10</sup>, כי יתרון האור הוא מן החושך דוקא, דע\"י שהחושך נהפך לאור נעשה יתרון בהאור, כמבואר בארוכה בהמאמר<sup data-n=\"3789\">11</sup>.ב) <b>והנה</b> ידוע שבמתן תורה ניתן הכח על כללות ענין העבודה. דהגם שההמשכה שע\"י עבודה, ומכש\"כ שע\"י העבודה דהפיכת החושך לאור, יש לה יתרון על ההמשכה שהיתה (בפועל) במתן תורה, זה גופא שע\"י עבודה יוכלו להמשיך המשכות אלו, הוא בכח ההמשכה שהיתה במתן תורה.\n<b>ויש</b> לומר, דזה שבההמשכה דמתן תורה הי' (בכח) גם העילוי דההמשכה שע\"י עבודה וגם העילוי דיתרון האור הבא מן החושך, הוא, כי ההמשכה דמתן תורה היתה לאחרי שאמר יתרו<sup data-n=\"3790\">12</sup> עתה ידעתי כי גדול הוי' מכל האלקים, כדאיתא בזהר<sup data-n=\"3791\">13</sup>, שע\"י שהודה יתרו ואמר עתה ידעתי כי גדול הוי' גו' אסתלק ואתייקר<sup data-n=\"3792\">14</sup> קוב\"ה ביקרי' עילא ותתא ולבתר יהיב אורייתא, ועי\"ז (שההמשכה דמתן תורה היתה לאחרי הודאת יתרו) נעשה יתרון (כביכול) בהתורה שניתנה במתן תורה (אף שניתנה מצד מלמעלה) בדוגמת יתרון האור הבא מן החושך. אלא שבמתן תורה, כיון שנתינת התורה היתה מצד למעלה (והודאת יתרו היתה רק הקדמה למתן תורה), היתרון (כביכול) בהתורה שנעשה ע\"י הודאת יתרו הי' רק בכח, ועי\"ז נמשכה הנתינת כח, שע\"י העבודה דהפיכת החושך לאור יהי' יתרון בהאור (גם) בפועל.\nג) <b>ועפ\"ז</b> יש לבאר מ\"ש בכמה דרושים<sup data-n=\"3793\">15</sup> שבכדי לבאר מה שקודם מ\"ת הוצרכה להיות הודאת יתרו, יובן זה בהקדים מ\"ש<sup data-n=\"3794\">16</sup> וראיתי אני שיש יתרון לחכמה מן הסכלות כיתרון האור מן החושך [דלכאורה אינו מובן, וכמו שמדייק בזהר<sup data-n=\"3795\">17</sup> אמאי אמר וראיתי אני [שלמה המלך, החכם מכל אדם<sup data-n=\"3796\">18</sup>], והלא כו\"ע ידעי דא שיש יתרון לחכמה מן הסכלות. והביאור בזה<sup data-n=\"3797\">19</sup>], שהכוונה בסכלות (כאן) היא (לא לשטות כפשוטה, אלא) לחכמות חיצוניות שהם סכלות לגבי חכמת התורה. ועל זה אומר וראיתי אני שיש יתרון לחכמה מן הסכלות כיתרון האור מן החושך, דכמו שיתרון האור הוא מן החושך דוקא, דע\"י שהחושך נהפך לאור נעשה יתרון בהאור (כמבואר בארוכה בההמשך דההילולא), עד\"ז הוא בחכמה (חכמת התורה) וסכלות (חכמות חיצוניות), שע\"י בירור והפיכת החכמה דלעו\"ז לקדושה, נעשה יתרון והוספה בחכמה דקדושה. וזהו מה שקודם מתן תורה הוצרכה להיות הודאת יתרו, כי יתרו הי' חכם גדול בחכמות חיצוניות, ועל ידי שהודה יתרו כי גדול הוי' מכל האלקים נעשה הבירור של חכמה דלעו\"ז שנהפכה לחכמה דקדושה, ועי\"ז נעשה יתרון והוספה בחכמה דקדושה, למעלה יותר מכמו שהיא מצד עצמה. [ועפ\"ז יש לבאר מהשארז\"ל<sup data-n=\"3798\">20</sup> דהטעם שנקרא בשם יתרו הוא לפי שיתר פרשה אחת בתורה, דלכאורה הרי גם השם יתר הוא מלשון יתרון, ולמה נקרא בשם יתר לפני שיתר פרשה בתורה. וע\"פ הנ\"ל יש לומר<sup data-n=\"3799\">21</sup>, דהשם יתר (מלשון יתרון) שהי' נקרא בו מקודם הוא מצד יתרון ומעלת השכל, דיתרון ומעלת השכל (על המדות) הוא גם בחכמה דלעו\"ז. אלא שבחכמה דלעו\"ז, להיותה תכלית הישות, והנפילה שע\"י המוחין דלעו\"ז היא נפילה גדולה יותר מהנפילה שע\"י המדות דלעו\"ז<sup data-n=\"3800\">22</sup>, היתרון שבה הוא ע\"ד שאמרו<sup data-n=\"3801\">23</sup> כל יתר כנטול דמי. ולאחרי שנתגייר ויתר פרשה אחת בתורה נקרא בשם יתרו בתוספות וא\"ו, דוא\"ו מורה על תורה<sup data-n=\"3802\">24</sup> כדאיתא בזהר<sup data-n=\"3803\">25</sup> שוא\"ו הוא אות אמת ואין<sup data-n=\"3804\">26</sup> אמת אלא תורה, להורות שהיתרון שבו הוא (לא בחכמה דלעו\"ז אלא) בחכמת התורה].\n<b>וצריך</b> להבין, דמלשון הכתוב (שיש יתרון לחכמה מן הסכלות כיתרון האור מן החושך) משמע, דזה שיתרון האור הוא מן החושך (דע\"י שהחושך נהפך לאור נעשה יתרון בהאור) הוא דבר ידוע, והכתוב מחדש, דכמו\"כ הוא בחכמה וסכלות, שע\"י בירור החכמה דלעו\"ז נעשה יתרון בחכמה דקדושה. וצריך ביאור, דלכאורה, לאחרי שיודעים כבר שע\"י בירור הלעו\"ז (חושך) נעשה יתרון בקדושה (אור), מהו החידוש בזה שיש יתרון לחכמה מן הסכלות, ועד שאומר על זה וראיתי <i>אני</i> (שלמה המלך, החכם מכל אדם). וע\"פ הנ\"ל יש לומר, דזה שע\"י שהחושך נהפך לאור נעשה יתרון בהאור הוא בהאור הבא ונמשך ע\"י עבודה, שבזה שייך לומר שהעבודה דאתהפכא חשוכא לנהורא ממשיכה המשכה נעלית יותר מההמשכה שנמשכה ע\"י העבודה בעניני קדושה. והחידוש דשלמה (וראיתי <i>אני</i>) הוא, שע\"י בירור והפיכת הלעו\"ז לקדושה נעשה יתרון גם בחכמת התורה. דהגם שהמשכת וירידת התורה למטה היא המשכה מצד עצמה, מצד למעלה [וכהלשון <i>מתן</i> תורה, מתנה מלמעלה, שלא מצד עבודת האדם], וגם מה שתלמיד ותיק עתיד לחדש ע\"י היגיעה שלו בעסק התורה כבר ניתן למשה בסיני<sup data-n=\"3805\">27</sup> (והיגיעה שלו היא לגלות<sup data-n=\"3806\">28</sup> זה שניתן כבר בדרך מתנה, המשכה מלמעלה), מ\"מ, ע\"י בירור הסכלות דחכמות חיצוניות והפיכתה לחכמה דקדושה [כשלומד חכמה זו<sup data-n=\"3807\">29</sup> בכדי להוסיף עי\"ז ידיעה בעניני התורה, שעי\"זמתבררת חכמה זו ונכללת בתורה<sup data-n=\"3808\">30</sup>], נעשה יתרון בחכמת התורה, למעלה יותר מכמו שהיא מצד עצמה. ויתירה מזו, שע\"י הודאת יתרו (קודם מתן תורה) נעשה יתרון גם בכללות הענין דמתן תורה. דהגם שמתן תורה היתה בדרך המשכה מלמעלה [דהענינים שבתורה שמתחדשים ע\"י התלמיד ותיק שבכל דור, הגם שהענינים עצמם ניתנו כבר בסיני, המשכתם מהעלם לגילוי היא ע\"י העבודה והיגיעה של התלמיד ותיק, משא\"כ ההמשכה דמתן תורה היתה בדרך המשכה מלמעלה, שלא ע\"י עבודה ויגיעה], מ\"מ, ע\"י הבירור והפיכת החכמה דלעו\"ז לחכמה דקדושה שע\"י הודאת יתרו, נעשה יתרון (כביכול) גם בהתורה שניתנה במתן תורה.\n<b>ויש</b> לומר, דהיתרון (כביכול) שנעשה בהתורה ע\"י הודאת יתרו הוא, דהתורה מצד עצמה ענינה הוא המשכה <i>מלמעלה</i>, שעבודת המטה אינה מגיעה לשם, ומכש\"כ שהעבודה דהפיכת החושך דלעו\"ז לקדושה אינה מגיעה לשם כי לגבי האור דתורה אין (מלכתחילה) החושך, ועי\"ז שמתן תורה היתה ע\"י הודאת יתרו, נמשך בה העצמות שלמעלה מגדר דמעלה ומטה, אור וחושך, ועי\"ז נתחדש, שע\"י העבודה ויגיעה יוכלו לחדש בתורה<sup data-n=\"3809\">31</sup>, לאפשה לה<sup data-n=\"3810\">32</sup>, ושע\"י בירור הסכלות דחכמות חיצוניות יהי' יתרון בחכמת התורה.\nד) <b>וביאור</b> הענין (דהיתרון שנעשה ע\"י שהודה יתרו שגדול הוי' מכל האלקים) בעומק יותר, יובן בהקדים שלכאורה אינו מובן, דלפי פשוטו שהכוונה ב\"מכל האלקים\" היא לע\"ז, כדפירש רש\"י עה\"פ מכל האלקים מלמד שהי' מכיר בכל ע\"ז שבעולם, מהי הרבותא בזה שהודה שהוי' גדול מכל האלקים. ויש לומר הביאור ע\"פ מ\"ש הרמב\"ם<sup data-n=\"3811\">33</sup> שהתחלת ענין ע\"ז הוא מה שחשבו שמכיון שהקב\"ה ברא את הכוכבים והגלגלים להנהיג את העולם והם המשמשים לפניו לכן ראוי לחלוק להם כבוד [וטעותם הי' בזה שחשבו שיש שלטון להכוכבים להשפיע בבחירתם, ולא ידעו האמת שהוא ית' משפיע על ידם כגרזן ביד החוצב<sup data-n=\"3812\">34</sup>]. ומזה יובן, ששלילת ענין ע\"ז שייך לא רק בנוגע לכוכבים ומזלות אלא גם בנוגע לכל המדריגות דסדר ההשתלשלות (מלאכים<sup data-n=\"3813\">35</sup>, ספירות וכו'<sup data-n=\"3814\">36</sup>) שעל ידם נמשך השפע למטה. ואדרבא, כלשהממוצע הוא נעלה יותר צריך לשלול את הטעות שראוי לחלוק לו כבוד, כי הוא אינו אלא כגרזן ביד החוצב. וכמובן גם ממה דאיתא במדרש<sup data-n=\"3815\">37</sup> משל למלך שנכנס למדינה והיו עמו דוכסין ואפרכין כו', ככל שהשר הוא גדול יותר, ובפרט המשנה למלך, צריך לפקחות יתירה להיות אנא נסיב מלכא. וזהו שהודאת יתרו כי גדול הוי' מכל האלקים היתה תלוי' בזה שהי' מכיר כל ע\"ז שבעולם, כי ע\"י שהי' לו ידיעה והכרה בכל סדר ההשתלשלות, עד במדריגה הכי עליונה, עי\"ז דוקא<sup data-n=\"3816\">38</sup> הי' יכול להיות אצלו הידיעה (עתה <i>ידעתי</i>) כי גדול הוי' מכל האלקים.\n<b>ויש</b> לומר, דזהו גם הפירוש (בפנימיות הענינים) בזה שיתרו הי' כהן מדין, דמדין הוא מלשון מדון ופירוד<sup data-n=\"3817\">39</sup>, והתחלת ענין הפירוד הוא (כביכול) בדקות וכו' מהמדריגות הכי עליונות שבאצילות. כמרז\"ל<sup data-n=\"3818\">40</sup> עד שלא נברא העולם הי' הוא ושמו בלבד, וידוע שבעד שלא נברא העולם נכלל גם עד שלא נאצל<sup data-n=\"3819\">41</sup>, והיינו שדוקא קודם שנאצל הי' הוא ושמו בלבד [שהגילוי (שמו) הי' בתכלית היחוד בעצמותו ית'<sup data-n=\"3820\">42</sup>], אבל לאחרי שנאצל (ע\"י הצמצום), נעשה הגילוי בבחינת מציאות (בערך הביטול והיחוד שהי' עד שלא נאצל), כביכול ענין מדון ופירוד<sup data-n=\"3821\">43</sup>. אלא שזה שנעשה מציאות הוא מצד הצמצום דשם אלקים, ומכיון שההעלם דהצמצום הוא רק לגבינו (היינו לגבי הגילויים שלאחרי הצמצום), והוי' ואלקים כולא חד<sup data-n=\"3822\">44</sup>, לכן, גם עכשיו הם (באמת) בתכלית היחוד כמו שהי' קודם שנאצל. וזהו מה שיתרו הי' כהן מדין, שהיתה לו ידיעה והכרה בכל המדריגות שנאצלו, אלא שידיעתו בהם היתה כמו שהם (מצד הצמצום) בבחינת מציאות, מדון ופירוד. ומזה נשתלשל<sup data-n=\"3823\">45</sup> שהי' כהן מדין כפשוטו, והי' מכיר בכל ע\"ז שבעולם, ע\"ז כפשוטה. וע\"י שהי' לו ידיעה והכרה בכל הדרגות (לאחרי שנאצל), בא אח\"כ לידי ידיעה והכרה [והודעה והכרזה] כי גדול הוי' מכל האלקים.ה) <b>וע\"פ</b> כל הנ\"ל יש לומר, דזה שהיתרון נעשה בתורה ע\"י הודאת יתרו הוא שנמשך בה העצמות (כנ\"ל סעיף ג), הוא מפני שהודאת יתרו עתה ידעתי כי גדול הוי' מכל האלקים היא הידיעה בהפלאת העצמות שהוא <i>למעלה</i> מגילויים (<i>גדול</i> הוי' מכל האלקים). ומכיון דזה שהגיע לידיעה זו (בהפלאת העצמות) היתה ע\"י הידיעה וההכרה שהיתה לו (לפני זה) בכל הדרגות דגילויים שנאצלו, לכן, היתרון בתורה (המשכת העצמות) הוא באופן ששייך לגילויים, הנתינת כח לכל אחד מישראל לאפשה לה, לגלות את חלקו בתורה<sup data-n=\"3824\">46</sup>, וכפסק אדמו\"ר הזקן<sup data-n=\"3825\">47</sup> שכל אחד צריך להשיג בידיעת התורה, ולחדש בה<sup data-n=\"3826\">48</sup>, הן בפשט והן ברמז הן בדרוש והן בסוד.\n<b>ויהי</b> רצון שכן תהי' לנו, שכל אחד יעשה כהנ\"ל, ונזכה לראות בגלוי איך שכל ישראל הם ממלכת כהנים וגוי קדוש<sup data-n=\"3827\">49</sup>, שכל אחד מישראל יהי' במעמד ומצב של שר<sup data-n=\"3828\">50</sup> כפשוטו, כי ע\"י ההחלטה ללמוד את התורה ולקיימה גם כשהוא במצב של עוני, הרי כהבטחת חז\"ל<sup data-n=\"3829\">51</sup> כל המקיים את התורה מעוני סופה לקיימה מעושר, שכשמחליט ללמדה ולקיימה מעוני הנה מיד לאחרי ההחלטה<sup data-n=\"3830\">52</sup> הוא לומדה ומקיימה מעושר, מעושר אמיתי בגשמיות וברוחניות גם יחד, ומוסיף בלימוד התורה בנגלה ובחסידות, ולימוד מביא לידי מעשה<sup data-n=\"3831\">53</sup> – קיום המצוות בהידור, און מ'ברענגט אַראָפּ משיח צדקנו למטה מעשרה טפחים בקרוב ממש, ויבנה בית המקדש במקומו ויקבץ נדחי ישראל<sup data-n=\"3832\">54</sup>, והיתה לה' המלוכה<sup data-n=\"3833\">55</sup>, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, במהרה בימינו ממש.\n**********<i>הוספות</i><i>עמוד ריק</i>",[["3778","*","יצא לאור ב<b>קונטרס כ\"ב שבט – תשמ\"ט</b>, \"לקראת ש\"ק פ' יתרו, כ\"ב שבט – יום ההסתלקות של הרבנית הצדקנית מרת חי' מושקא נ\"ע זי\"ע . . <i>עש\"ק כ\"ב שבט תשמ\"ט</i>\"."],["3779","1","שה\"ש ה, א."],["3780","2","זהר ח\"ב רטו, א. וראה גם שם ח\"א קנ, רע\"א. רכה, סע\"ב. רמט, ב. ח\"ב פה, רע\"א."],["3781","3","שניתן על ידי בעל המאמר ליו\"ד שבט ה'שי\"ת, יום הסתלקותו – נדפס בסה\"מ ה'תש\"י ע' 111 ואילך."],["3782","4","שהש\"ר במקומו. וש\"נ."],["3783","5","תרומה כה, ח."],["3784","6","פרשתנו יט, כ. וראה תנחומא נשא טז \"עמד משה והורידה לארץ שנאמר וירד ה' על הר סיני\". וכ\"ה במ\"כ לב\"ר פי\"ט, ז."],["3785","7","וראה סה\"מ תרמ\"ד ע' רכב."],["3786","8","וראה ד\"ה וה' אמר המכסה גו' ה'תשל\"ז ס\"ה (לעיל ח\"א ע' רנח ואילך), דכאשר ההמשכה היא באופן שאינה פועלת העלאה בהתחתון – הגם שהחסרון הוא מצד התחתון, שאינו כלי – חסר אז (לא רק בההעלאה, אלא) גם בההמשכה."],["3787","9","ראה בארוכה המשך ההילולא פ\"ג ואילך."],["3788","10","ראה ד\"ה באתי לגני ה'תשכ\"ט ס\"ג. שם סי\"ד (לעיל ע' שכ. של ואילך). ובכ\"מ."],["3789","11","פ\"א ואילך."],["3790","12","פרשתנו יח, יא."],["3791","13","ח\"ב פרשתנו סז, ב."],["3792","14","כן מובא הלשון בהדרושים שבהערה הבאה."],["3793","15","אוה\"ת ריש פרשתנו. ד\"ה וישמע יתרו תרמ\"ז (סה\"מ תרמ\"ז ע' עב ואילך) ותרע\"ה (המשך תער\"ב ח\"ב ע' תתסא ואילך). ד\"ה ויאמר משה ה'תש\"ט פ\"ו (סה\"מ ה'תש\"ט ס\"ע 56 ואילך) (וראה שם פ\"ב ואילך – סה\"מ שם ע' 52 ואילך)."],["3794","16","קהלת ב, יג."],["3795","17","ח\"ג מז, ב."],["3796","18","מלכים-א ה, יא."],["3797","19","ראה גם אוה\"ת וישב רס, ב. שלח ס\"ע תנו ואילך. ואתחנן ס\"ע עו ואילך."],["3798","20","שמו\"ר פרשתנו פכ\"ז, ח."],["3799","21","ראה <i>עד\"ז</i> אוה\"ת פרשתנו ע' תשלא-ב. ד\"ה ויאמר משה הנ\"ל פ\"ז (סה\"מ שם ע' 58)."],["3800","22","ראה תניא ספ\"ח."],["3801","23","חולין נח, ב."],["3802","24","ראה גם אגה\"ת ספ\"ד."],["3803","25","ח\"ג ר\"פ ויקרא."],["3804","26","ירושלמי ר\"ה פ\"ג ה\"ח. ועוד."],["3805","27","ראה מגילה יט, ב. ירושלמי פאה פ\"ב ה\"ד. שמו\"ר רפמ\"ז. ויק\"ר רפכ\"ב. ועוד."],["3806","28","והלשון \"תלמיד ותיק עתיד <i>לחדש</i>\" הוא (כמדובר כמ\"פ) שבמ\"ת ניתנו רק הכללים. וגם להביאור (המשך תרס\"ו ע' שפג. שם ע' שצג. ועוד) דזה שרוב הדינים דתושבע\"פ שלמדו מפסוקי התורה הם לא בדרך גילוי ההעלם אלא \"כמו חידוש מאין ליש\" שמתחדש ע\"י יגיעתם – הרי (א) כיון שגם החידושים הם ע\"פ המדות שהתורה נדרשת בהן, אין זה חידוש ממש ורק \"<i>כמו</i> חידוש מאין ליש\", (ב) זה שאפשר לחדש בתורה הוא חידוש שנעשה (גם) ע\"י הודאת יתרו (עי\"ז שיש יתרון לחכמה מן הסכלות), כדלקמן בפנים."],["3807","29","מי ששייך לזה, אבל מי שאין ביכלתו לברר, הרי אדרבא נמשך אחריהם ח\"ו (ד\"ה ויאמר משה הנ\"ל פ\"ה – סה\"מ שם ע' 56). וראה תניא ספ\"ח, הובא בד\"ה הנ\"ל שם."],["3808","30","ד\"ה ויאמר משה הנ\"ל שם. ויש לומר, דשני אופנים בזה: שע\"י לימוד החכמה שלמד מיתוסף לו ידיעה בתורה, שגם אז היא נכללת בתורה, כבסה\"מ ה'תש\"ט שם; ולמעלה יותר – שהיא נעשית חלק בתורה, כהחשבונות וכו' שבהל' קידוש החודש להרמב\"ם שנלקחו מספרי חכמי יון (רמב\"ם הל' קדה\"ח ספי\"ז) ואעפ\"כ הם לא \"אמצעים\" שעל ידם יתוסף בהבנת התורה, אלא שהם נעשו חלק בתורה – ראה רמב\"ם הל' קדה\"ח בסופן \"ולא ישוטטו . . בספרים אחרים, דרשו מעל <i>ספר ה'</i>\"."],["3809","31","ויש לקשר זה עם זה שיתרו הוסיף פרשה בתורה. ולהעיר מד\"ה ויאמר משה הנ\"ל פ\"ו (סה\"מ שם ע' 57), שע\"י הודאת יתרו וע\"י פרשת ואתה תחזה שנתחדשה על ידו, ניתן במ\"ת גם החידוש בתורה [ע\"ד \"תורה חדשה מאתי תצא\" – ויק\"ר פי\"ג, ג] שיתחדש לעתיד."],["3810","32","זח\"א יב, ב."],["3811","33","הל' ע\"ז בתחלתן."],["3812","34","סהמ\"צ להצ\"צ מצות מילה (דרמ\"צ ו, ב). שם מצות אחדות ה' (ס, ב). ובכ\"מ."],["3813","35","ראה רמב\"ם שם ה\"ב. שם רפ\"ב. וראה פיה\"מ להרמב\"ם פ' חלק יסוד החמישי."],["3814","36","ולהעיר ממחז\"ל (ספרי הובא בפרדס שער לב (שער הכוונה) פ\"ב) אליו ולא למדותיו – שזהו בנוגע אצילות ולמעלה מאצילות (ראה לקו\"ת הוספות לויקרא נא, ג. סהמ\"צ להצ\"צ שרש מצות התפלה פ\"ז (קיז, א). ועוד. ובשרש מצות התפלה שם מקשר זה עם מ\"ש הרמב\"ם ביסוד החמישי)."],["3815","37","איכ\"ר פ\"ג, כד – הובא באוה\"ת פרשתנו ס\"ע תשלט ואילך לענין מה שאמר יתרו \"כי גדול הוי' מכל האלקים\"."],["3816","38","דע\"י שישנה הידיעה וההכרה בהעילוי ד\"כל האלקים\" (דקדושה, המדריגות שלמעלה), אז דוקא נרגש ההפלאה בהגדלות דהוי' שהוא גדול גם מהעילוי ד\"כל האלקים\"."],["3817","39","לקו\"ת מטות פו, רע\"א. ד\"ה החלצו תרנ\"ט פ\"ג (סה\"מ תרנ\"ט ע' נה).\nהשייכות דיתרו כהן מדין למדון – ראה גם זהר פרשתנו סח, א \"כהן מדין רזא דא אשת מדנים\". וראה גם אוה\"ת פרשתנו (ס\"ע תשכא ואילך) ובד\"ה וישמע יתרו תרמ\"ז (סה\"מ שם ע' עט) ותרע\"ה (המשך תער\"ב ח\"ב ע' תתסא), אלא שהביאור שם הוא כי יתרו הוא חכמה דקליפה שגורמת מדנים ופירוד."],["3818","40","פרקי דר\"א פ\"ג."],["3819","41","עבודת הקודש חלק א (חלק היחוד) פ\"ב – הובא בהמשך תרס\"ו ס\"ע קפה. ולהעיר, שלפי אחד מהביאורים – הכוונה היא לאצילות דכללות (ד\"ה צאינה וראינה תרנ\"ד (סה\"מ תרנ\"ד ע' רצט ואילך). נסמן בספר הערכים-חב\"ד כרך ד ערך אוא\"ס (ה) ס\"א סק\"א ח\"א)."],["3820","42","ראה המשך תרס\"ו ע' קפג."],["3821","43","להעיר מהידוע (לקו\"ת תזריע כג, ג. ובכ\"מ) שגם חו\"ג דאצילות, עם היות שמאיר בהם אוא\"ס ואיהו וגרמוהי חד, מ\"מ, הם שני הפכים, ובכדי שיהי' \"התכללות ויחוד המדות . . שלא יהיו ענפין מתפרדין\" הוא ע\"י שמאיר בהם אוא\"ס \"בגילוי רב <i>יותר מכפי מדתם</i>\". ועפ\"ז יש לומר, דענין \"מדון ופירוד\" בהדרגות שנאצלו הוא בשתים: דע\"י שהם בבחינת מציאות – הם נפרדים כביכול <i>מאוא\"ס</i>, כבפנים; ושהם נפרדים <i>זה מזה</i>, \"ענפין מתפרדין\". ועפ\"ז יומתק השייכות דדרגות הנאצלות ל\"מדין\", מדין מלשון <i>ריב</i> ומדון."],["3822","44","ראה זהר ח\"ב קסא, א. ח\"ג רסד, א."],["3823","45","להעיר מד\"ה וידעת תרנ\"ז (סה\"מ תרנ\"ז ע' נה ואילך) שבכדי שלא יהי' נתינת מקום לע\"ז צ\"ל הידיעה שהוי' ואלקים כולא חד."],["3824","46","ראה שער הגלגולים הקדמה יז. שער רוה\"ק בענין היחודים על קברי הצדיקים הקדמה ב (קח, ב). הל' ת\"ת שבהערה הבאה."],["3825","47","בהל' ת\"ת שלו פ\"א ה\"ד."],["3826","48","שם פ\"ב ה\"ב. ובאגה\"ק סכ\"ו (קמה, א) שזהו (החיוב לחדש) \"הן בנגלה והן בנסתר\"."],["3827","49","פרשתנו יט, ו."],["3828","50","ראה פרש\"י שם שפירוש כהנים הוא שרים."],["3829","51","אבות פ\"ד מ\"ט."],["3830","52","כי מחשבה טובה הקב\"ה מצרפה למעשה (קידושין מ, א), שהכוונה בזה (בפשטות) היא שזה נחשב כאילו עשה. ולהעיר משו\"ע או\"ח סתקע\"א ס\"ג."],["3831","53","קידושין שם, ב. ב\"ק יז, א."],["3832","54","רמב\"ם הל' מלכים ספי\"א."],["3833","55","עובדי' א, כא."]]],[1500370052,"<h3>בס\"ד. ש\"פ ויצא, ט' כסלו, ה'תשל\"ב<sup data-n=\"3834\">*</sup></h3>\n(הנחה בלתי מוגה)\n<b>אתה</b> אחד<sup data-n=\"3835\">1</sup> ושמך אחד ומי כעמך כישראל גוי אחד בארץ כו', הנה נוסח זה אומרים בתפלת מנחה דשבת, רעוא דרעוין. וצריך להבין מהי המעלה של תפלת מנחה דשבת על כל התפלות, גם על (שאר) התפלות דשבת גופא, שאז דוקא אומרים אתה אחד כו' דמדבר בקוב\"ה עצמו<sup data-n=\"3836\">2</sup>. ובפרט על פי המבואר בד\"ה זה לבעל ההילולא<sup data-n=\"3837\">3</sup> דבנוסח זה מבוארים כל המדריגות שבאצילות ולמעלה מאצילות, כל בחי' ההשתלשלות ושלמעלה מהשתלשלות.\nב) <b>והנה</b> בפרשת השבוע (פ' ויצא<sup data-n=\"3838\">4</sup>) נאמר<sup data-n=\"3839\">5</sup> והאבן הזאת אשר שמתי מצבה יהי' בית אלקים גו', דמ\"ש והאבן הזאת קאי אמ\"ש לפני זה<sup data-n=\"3840\">6</sup> ויקח את האבן אשר שם מראשותיו וישם אותה מצבה ויצק שמן על ראשה. וידוע הדקדוקים בזה (וראה גם כן מאמר בעל ההילולא ד\"ה וידר יעקב נדר שבתורת חיים<sup data-n=\"3841\">7</sup>), מהו החידוש ועילוי בזה ששם את האבן מצבה ובזה שיצק שמן על ראשה. גם צריך להבין מ\"ש<sup data-n=\"3842\">8</sup> וידר יעקב נדר לאמר אם גו' והאבן הזאת אשר שמתי מצבה יהי' בית אלקים, והיינו דכאשר יתקיימו כל התנאים שמונה לפני זה – יהי' אלקים עמדי וגו', הנה אז דוקא יהי' האבן בית אלקים, דנוסף על העילוי שמאבני המקום (לשון רבים) נעשית אבן אחת<sup data-n=\"3843\">9</sup>, ונוסף להעילוי דוישם אותה מצבה והעילוי דויצק שמן על ראשה, הנה נוסף על כל עילויים הנ\"ל, תהי' עלי' גדולה יותר בהאבן, אשר יהי' בית אלקים. והנה פירוש והאבן גו' יהי' בית אלקים הוא, דכמו שבית כפשוטו מוסיף עילוי ושלימות בהאדם הדר בהבית (כמבואר בכמה דרושים, ובפרט בהדרושים המבארים ענין ביהמ\"ק, ד\"ה מזמור שיר חנוכת הבית לדוד<sup data-n=\"3844\">10</sup>), כן גם האבן הזאת גו' תוסיף עילוי ושלימות כביכול באלקים. וצריך להבין, איך שייך שהאבן תוסיף עילוי באלקים. והנה כיון שוהאבן גו' יהי' בית אלקים בא בהמשך למ\"ש לפנ\"ז<sup data-n=\"3845\">11</sup> והי' הוי' לי לאלקים, מובן, שהכוונההיא שהאבן יהי' בית (לא לבחי' אלקים סתם, כ\"א) לבחי' אלקים, כמו שהוי' יהי' לאלקים. והיינו שהאבן תוסיף שלימות גם בבחי' הוי' שיהי' לאלקים. וגם צריך להבין (כמו שמקשה בתו\"ח שם) מ\"ש והאבן הזאת לשון נקבה, ואח\"כ יהי' בית כו', דהול\"ל תהי' בית גו', ואם אבן לשון זכר, הול\"ל האבן הזה כו'.\nג) <b>והנה</b> יום ההילולא (ט' כסלו) הוא ערב יום הגאולה<sup data-n=\"3846\">12</sup> (יו\"ד כסלו<sup data-n=\"3847\">13</sup>). וידוע שהגאולה שייכת להענין דפדה בשלום נפשי<sup data-n=\"3848\">14</sup>, וכמ\"ש כ\"ק אדמו\"ר הזקן באגה\"ק שלו<sup data-n=\"3849\">15</sup> (בנוגע להגאולה די\"ט כסלו) כשקראתי כו' פדה בשלום נפשי כו' יצאתי בשלום. דמזה מובן<sup data-n=\"3850\">16</sup> גם בנוגע להגאולה של כ\"ק אדמו\"ר האמצעי<sup data-n=\"3851\">17</sup>, שהגאולה שייכת להענין דפדה בשלום נפשי שאומרים זה בשיעור תהלים החדשי (ביום העשירי לחודש). ובפרט לפי הידוע<sup data-n=\"3852\">18</sup>, שהסדר המסודר אצל כ\"ק רבותינו נשיאינו הי' שהיו אומרים שיעור תהלים כפי שנחלק לימי החודש, ובזמנים ידועים היו אומרים תהלים בשופי<sup data-n=\"3853\">19</sup>, היינו שהיו מוסיפים לומר גם שיעור תהלים השבועי – שעפ\"ז מבאר כ\"ק מו\"ח אדמו\"ר<sup data-n=\"3847\">13</sup> מה שאדמו\"ר הזקן אמר בי\"ט כסלו הפסוק פדה בשלום נפשי, אף שפסוק זה אינו בשיעור החדשי דיום יט בחודש כ\"א במזמורי תהלים דיום השלישי בשבוע (ויט\"כ חל אז ביום השלישי), כי בהיות אדמו\"ר הזקן במאסר הוסיף לומר גם שיעור תהלים השבועי. הרי מזה מובנת עוד יותר השייכות של הגאולה לענין פדה בשלום נפשי. דהרי השיעור הקבוע הוא שיעור תהלים החדשי, והשיעור של יום יט בחודש הוא תפלה למשה, שגם ענין זה שייך להגאולה<sup data-n=\"3854\">20</sup>, ומ\"מ מקשר כ\"ק אדמו\"ר הזקן הגאולה שלו להפסוק פדה בשלום נפשי דוקא, הרי זה מכריח עוד יותר שייכות ענין הגאולה לפסוק זה. ומזה מובן שכ\"ה גם בנוגע להגאולה דיו\"ד כסלו, כנ\"ל.\n<b>והענין</b> הוא, דהנה עיקר החידוש בהכתוב פדה בשלום נפשי הוא (לא עצם ענין הפדי', כ\"א כמו שמבאר בעל ההילולא בד\"ה פדה בשלום נפשי<sup data-n=\"3855\">21</sup> (שבספרו שערי תשובה)) בזה שהפדי' היא בשלום. דאפשר להיות פדי' בדרך מלחמה,והחידוש שבפדי' זו היא אשר (אף שהיא מקרב לי, מ\"מ) פדה בשלום (דוקא) נפשי. וזהו ג\"כ פי' המשך הכתוב כי ברבים היו עמדי, דתיבת כי היא נתינת טעם לתחלת דבריו שאמר פדה בשלום נפשי, שהטעם שפדה בשלום דוקא ולא במלחמה הוא – זה שברבים היו עמדי<sup data-n=\"3856\">22</sup>. דעי\"ז שגם אלו שהם בחי' רבים היו עמדי<sup data-n=\"3857\">23</sup>, וע\"ד מרז\"ל<sup data-n=\"3858\">24</sup> שגם אנשי אבשלום התפללו עבור דוד, הנה עי\"ז פדה בשלום נפשי.\n<b>ועפ\"ז</b> מובנת גם השייכות דפדה בשלום נפשי למ\"ש והאבן הזאת גו', כי זה שמאבני המקום לשון רבים נעשית אבן אחת הוא כענין ברבים היו עמדי. ועד\"ז הוא גם הענין דאתה אחד כו' ומי כעמך כישראל גוי אחד בארץ, כי החידוש דגוי אחד בארץ הוא כמ\"ש אדמו\"ר הזקן<sup data-n=\"3859\">25</sup> שישראל ממשיכים בחי' אחד גם בעניני ארץ. דאף שעניני ארץ הם בחי' רבים, ועד אפילו בבריאת אדה\"ר אמרז\"ל<sup data-n=\"3860\">26</sup> עה\"פ<sup data-n=\"3861\">27</sup> נעשה (לשון רבים) אדם, מה אתה נותן פתחון פה כו' והרוצה לטעות כו', והיינו שהוא העלם כזה שאפילו משה רבינו חכמה דקדושה אמר מה אתה נותן כו', הנה גם בבחי' ריבוי זה נעשה בחי' אחד.\nד) <b>ויובן</b> כל זה בהקדים המאמר (נמצא בביכל שנגאל לאחרונה מהשבי') של בעל ההילולא ד\"ה אתם נצבים<sup data-n=\"3862\">28</sup>, שמבאר<sup data-n=\"3863\">29</sup> שם שמנין הסוגים שבישראל נחלק לב' מדריגות (כדלקמן). ובהקדמה, שבתחלה נאמר בפסוק<sup data-n=\"3864\">30</sup> ראשיכם שבטיכם גו' כל איש ישראל, ואח\"כ נאמר בפסוק בפ\"ע<sup data-n=\"3865\">31</sup> טפכם נשיכם גו', והרי חלוקת הפסוקים מורה גם על חלוקת הענינים<sup data-n=\"3866\">32</sup>, ולכאורה צריך להבין, למה מחלקם לב' פסוקים נפרדים. גם צריך להבין, דכיון שנאמר אתם נצבים היום כולכם, למה מונה את כל עשר הדרגות והסוגים שבישראל, ואינו מסתפק במ\"ש כולכם. גם צריך ביאור במ\"ש וגרך אשר בקרב מחניך, למה מוסיף בגר דוקא שהוא בקרב מחניך.ה) <b>ומבאר</b> שם, שעשר הסוגים שבישראל הם כנגד ע\"ס דאצילות, ולכן מחלקם לב' מדריגות כלליות, כשם שבספירות יש ב' מדריגות כלליות, הספירות הראשונות שבבחינת הגדלות, והספירות האחרונות שבבחינת הקטנות. ויש להוסיף, שעפ\"ז יל\"פ מה שמדריגה הראשונה שבחלוקה הראשונה היא ראשיכם, והמדריגה הראשונה בחלוקה השני' היא טפכם, כי, מדריגה הראשונה שבכל חלוקה מורה על כללות כל הבחינות שבחלוקה זו (וע\"ד האות הראשונה שבתיבה שהיא כוללת כל האותיות של התיבה, כמבואר בשער היחוד והאמונה<sup data-n=\"3867\">33</sup>), והרי ראשיכם הוא כללות ענין הגדלות, וטפכם הוא כללות ענין הקטנות (כדלקמן). ומבאר שם, שראשיכם הוא בחי' כתר שבכתר, שכולל כל הראשים הפרטיים, והוא בחינת רצון הפשוט ועצמי שבכנסת ישראל בכלל ובכל ניצוץ אלקי בפרט, שאין טעם כלל לרצון, אפילו טעם כמוס כו', כמו במ\"ת דכתיב<sup data-n=\"3868\">34</sup> ויחן שם ישראל גו'. [ויש להוסיף, שגם ענין המשכת בחי' הרצון העליון בכל ישראל, מובן ע\"פ מ\"ש במתן תורה אנכי הוי' אלקיך<sup data-n=\"3869\">35</sup>, כמבואר בכ\"מ<sup data-n=\"3870\">36</sup> שאז נעשה בחי' אנכי הוי' כוחו וחיותו של כאו\"א מישראל]. ואח\"כ אמר שבטיכם, שנקראו שבטי י\"ה, כמ\"ש<sup data-n=\"3871\">37</sup> ששם עלו שבטים שבטי י\"ה, והוא בחי' אור הכתר שמתפשט בחו\"ב שבכתר עצמו ונק' חו\"ב שבכתר כו', והוא גילוי הרצון העצמי המאיר בהעלם השכל שנקרא טעם כמוס לרצון. [ולהעיר, שהמבואר כאן הוא דלא כמבואר במ\"א<sup data-n=\"3872\">38</sup> דמ\"ש ששם עלו שבטים שבטי י\"ה קאי על חו\"ב כפי שהם במקומם]. ואח\"כ אמר זקניכם, זקן שקנה חכמה<sup data-n=\"3873\">39</sup> ממקורה להביאה מן ההעלם כו' לבוא בהתפשטות בבינה, והן הסנהדרין שהן השופטים ודיינים כו'. ואח\"כ אמר שוטריכם, שהוא בחי' נצח והוד דחו\"ב (שזהו\"ע כליות<sup data-n=\"3874\">40</sup> יועצות<sup data-n=\"3875\">41</sup>), שהן תוקף וחוזק אור השכל להיות המוח שליט על הלב<sup data-n=\"3876\">42</sup> כו', והן כמו שלוחי הדיינין שרודים את העם במקל להכניעם שלא יטו ממשפט התורה ימין ושמאל, כמ\"ש<sup data-n=\"3877\">43</sup> שופטים ושוטרים כו'. ואח\"כ אמר כל איש ישראל, שהוא בחי' הדעת המתפשט במדות שמתחלק לס\"ר דעות, וכידוע בענין ברכת חכם הרזים על ס\"ר מישראל שאין דעתם דומה זה לזה<sup data-n=\"3878\">44</sup>, ועד שהדעת מתפשט במדות חג\"ת, כמבואר בתניא<sup data-n=\"3879\">45</sup> שע\"י ענין הדעת באים לאהבה וענפי' ויראה וענפי', שהאהבה היא שורש כל רמ\"ח מ\"ע, והיראה היא שורש כל שס\"ה מל\"ת<sup data-n=\"3880\">46</sup>.<b>ואח\"כ</b> מבאר בפסוק השני את החלוקה הב', שהיא בבחי' הקטנות. ומתחיל בענין טפכם, שהוא בבחי' קטנות הדעת המצומצם מאד בקטנות המדות שהם בחי' אנפי זוטרא, כמו הטף באדם שאינם בני דעה גמורה. ונשיכם הוא בחי' הקטנות דבחי' מקבל כו'. ואח\"כ אומר וגרך אשר בקרב מחניך מחוטב עציך עד שואב מימיך, שג' מדריגות האלה הן בחי' מדריגות החיצוניות ביותר שהוא הנפש הבהמית והטבעית כו', בדוגמת הגר שנמשך מאוה\"ע כו' (נוסף לכך שענין הגר בפשטות הוא בבחי' הקטנות, וכמארז\"ל<sup data-n=\"3881\">47</sup> גר שנתגייר כקטן שנולד דמי), שמצד עצמה היא רחוקה מאלקות, ומ\"מ מתקרבת תחת כנפי השכינה כגר שנתגייר ממש. ועז\"נ וגרך אשר בקרב מחניך, שנבדל מפנימיות האלקות שבנש\"י שנק' איש ישראל דלעילא, רק נתפס ונגרר בקרב מחניך כטפל לגבי העיקר. וזהו מה שעובד עבודה גשמית כמו לחטוב עצים ולשאוב מים, שחטיבת עצים הוא רק כמו הכנה לבישול, וכן שאיבת מים היא רק כמו טפל ומסייע לאכילה, וכמובן מהמבואר במ\"א<sup data-n=\"3882\">48</sup> דכל ענין השתי' הוא רק כדי שהדם הנוצר ע\"י האכילה יתפשט באברים (וזהו ביאור מארז\"ל<sup data-n=\"3883\">49</sup> אכל ולא שתה אכילתו דם), וכן הוא לענין האכילה הרוחניות שהם המצוות. ונמצא, שג' הדרגות האחרונות המנויות כאן הם כפי שהנה\"א ירד ונתלבש למטה מטה בנה\"ב, למצרים ירדתם וכו'<sup data-n=\"3884\">50</sup>. וגם על מדריגות אלו כתיב אתם נצבים היום כולכם לפני הוי' גו'.\nו) <b>וממשיך</b> שם<sup data-n=\"3885\">51</sup>, אך הנה לכאורה זהו פלא גדול, דבשלמא הנשמות יכולים לעמוד לפני הוי', אבל גרך אשר בקרב מחניך, איך גם הם יעמדו לפני הוי'. ומבאר בזה, דזהו ענין אתם נצבים דייקא, דפירוש נצבים הוא ענין הקמה והגבהה, כמו קמה אלומתי וגם נצבה<sup data-n=\"3886\">52</sup>, וכמו מצבת אבן שמונחת בארץ שמקים אותה ומציבה למצבה, כמו המצבה דיעקב דכתיב&lt;6&gt; ויקח את האבן גו' וישם אותה מצבה. וכך הענין כאן, דמ\"ש אתם נצבים היום קאי על ראש השנה<sup data-n=\"3887\">53</sup>, שאז נצבים כולכם היום, וכמ\"ש<sup data-n=\"3888\">54</sup> ויהי בישורון מלך בהתאסף ראשי עם יחד שבטי ישראל, דבראש השנה הרי נשמות ישראל עולים לשרשם ששם הרי כולכם לאחדים כאחד (כמבואר בלקו\"ת פ' נצבים<sup data-n=\"3889\">55</sup>), וכמבואר בתניא פל\"ב שבהיותם בשרשם הרי כולם מתאימות ואב אחד לכולנה ומי יודע גדולתן ומעלתן בשרשן ומקורן כו'. וממשיך שם<sup data-n=\"3890\">56</sup>, ועוד יתפרש ענין נצבים לשון ממשלה ושררה, כמו וישם באדום נציבים<sup data-n=\"3891\">57</sup>,וכמו נציב פלשתים<sup data-n=\"3892\">58</sup>, שהוא שר המושל על המדינה, וכן המתמנה על העובדים במלאכה נקרא נציב, כמו הנער הנצב על הקוצרים<sup data-n=\"3893\">59</sup>. ובזה יובן איך אפשר שגם גרך וחוטב עציך גו' יהיו נצבים לפני הוי' ממש, דכיון שנש\"י מתעלים במקורם הראשון כו', הרי משם יכול להאיר גם לחלק אור הנשמה אלקית שמלובשת בלבוש גס כו', שגם הם יהיו קמים ועומדים לפני הוי' ממש. ויש לומר, שזהו הטעם שמביא בהמאמר פסוקים אלו [ולא הפסוק נציב שנאמר בשלמה<sup data-n=\"3894\">60</sup>, וגם לא הפסוק נצב מלך<sup data-n=\"3895\">61</sup>, כרגיל בכ\"מ], בכדי לרמז שהעילוי דנצבים ישנו גם בגרך (נה\"ב הנמשכת מבחי' אוה\"ע), וכמו וישם באדום נציבים ונציב פלשתים, שגם ה\"נצבים\" הם מאדום ופלשתים, ומ\"מ הם נצבים [ולא הביא הפסוק ומלך אין <i>באדום</i> נצב מלך, כי פירושו הוא שהנצב הוא במקום מלך, וזה <i>שולל</i> בהמאמר בנוגע לגרך]. וגם בחוטב עציך ושואב מימיך, וכמו הנער הנצב על הקוצרים, שעם היותו גם הוא מהעובדים במלאכה, מ\"מ (להיותו ממונה עליהם) הוא נצב.\nז) <b>וממשיך</b> שם<sup data-n=\"3896\">62</sup>, דעדיין צריך להבין מ\"ש לשון כולכם, דמשמע שכל ישראל נצבים בהתכללות כולם כאיש אחד, משא\"כ בפסוק ויהי בישורון מלך בהתאסף ראשי עם גו' משמע שעיקר ההתכללות הוא בראשי עם דוקא, שהתאספות היא ע\"י הראשים. וגם מהו הלשון בהתאסף, שמשמע שיתאספו ממילא, ולא שצריך לאספם ולחברם יחד. ומבאר בזה, דמ\"ש אתם נצבים כולכם, הגם שקאי על ר\"ה שאז מתכללים יחד כללות נש\"י כו', הנה זהו ענין ההתכללות כפי שהוא מצד המקבלים, שמתעלים מלמטה למעלה, ועז\"נ<sup data-n=\"3897\">63</sup> שמאלו תחת לראשי (דכנס\"י), להגבי' אותם ולהעלותם למעלה. אך יש בחי' אחדות הנפעלת מצד הגילוי מלמעלה, באופן דימינו תחבקני<sup data-n=\"3897\">63</sup>, שזהו ביוהכ\"פ, וכמ\"ש<sup data-n=\"3898\">64</sup> ביום השלישי יקימנו ונחי' לפניו, שהתאחדות זו היא מצד גילוי המשפיע, שזה פועל בתחילה בראשי עם, וגם בזה כתיב בהתאסף בדרך ממילא, כי נעשה בדרך ממילא מצד גילוי המשפיע. ושני ענינים אלו היו גם בשעת מתן תורה, דבתחילה כתיב<sup data-n=\"3899\">65</sup> ויחן שם ישראל, כאיש אחד בלב אחד, שזהו ענין האחדות שמצד המקבל, שזה הי' בראש חודש סיון<sup data-n=\"3900\">66</sup>, ואח\"כ הי' ענין האחדות שנפעל ביום מתן תורה עצמו, שאז כתיב<sup data-n=\"3901\">67</sup> וירד הוי' על הר סיני, שהי' גילוי העצמות<sup data-n=\"3902\">68</sup>, ומזה נעשה ענין האחדות בתכלית, בהתאסף ראשי עם. ועד\"ז הואביום הכיפורים שהוא ג\"כ זמן מתן תורה, יום שבו ניתנו לוחות האחרונות<sup data-n=\"3903\">69</sup>. וזהו אמיתית הענין דאתם נצבים כולכם לפני הוי', היינו לפני הוי' ממש, שעז\"נ&lt;64&gt; ביום השלישי יקימנו ונחי' לפניו.\nח) <b>ועפ\"ז</b><sup data-n=\"3904\">70</sup> י\"ל השייכות דאתה אחד לתפלת מנחה דשבת רעוא דרעוין, דהנה ידוע<sup data-n=\"3905\">71</sup> בענין ג' הסעודות דשבת, דסעודה השלישית דשבת היא בחי' תענוג העצמי שאין לו אחיזה בשום דבר, שלכן נאמר בה<sup data-n=\"3906\">72</sup> היום לא, דוגמת הבחי' דעוה\"ב שאין בו לא אכילה ולא שתי'<sup data-n=\"3907\">73</sup>. ועפ\"ז יובן מה שאומרים אז דוקא אתה אחד כו' ומי כעמך כישראל גוי אחד בארץ, כי ע\"י המשכת בחי' תענוג העצמי, דוגמת בחי' לפני הוי', נעשה אמיתית ענין ההתכללות בנש\"י, ועי\"ז ממשיכים בחי' אחד גם בארץ. וזהו ג\"כ מ\"ש וישם אותה מצבה ויצק שמן על ראשה, דהנה נת\"ל (בד\"ה אתם נצבים לעיל<sup data-n=\"3908\">74</sup> פ\"ו) שבענין ההתכללות ישנם ב' אופנים, מלמטה למעלה ומלמעלה למטה. וזהו ויקח את האבן גו' וישם אותה מצבה, ויקח גו' וישם אותה מצבה הוא בדרך העלאה<sup data-n=\"3909\">75</sup> מלמטלמ\"ע (בדוגמת אתם נצבים שבר\"ה), דלאחרי זה שמאבני המקום ל' רבים נעשית אבן אחת, העלה אותה מלמטלמ\"ע עד שנעשית מצבה, ואח\"כ ויצק שמן על ראשה, המשכה מלמעלמ\"ט (בדוגמת ההתכללות שמצד העילוי דיוהכ\"פ), שעי\"ז נמשכת בחי' האחדות וההתכללות גם למטה מטה ביותר<sup data-n=\"3910\">76</sup>, דזהו\"ע ויצק שמן על ראשה, ששמן מפעפע בכולו<sup data-n=\"3911\">77</sup>. וע\"י המשכת האחדות גם למקום התחתון ביותר, והיינו בירור הניצוצות שבדברים התחתונים [שזהו ג\"כ ענין התנאי, אם יהי' אלקים עמדי וגו', שכ\"ז נוגע לענין הבירורים, כמבואר בתו\"ח שם פ\"ט], הנה עי\"ז והאבן הזאת גו' יהי' בית אלקים, שבירורים אלו יוסיפו עילוי ושלימות בשם אלקים, וגם בשם הוי' כמו שיהי' לו לאלקים, כי עי\"ז תושלם הכוונה דנתאווה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"3912\">78</sup>. ולהיות שכוונה זו היא בעצמותו ית' [דזהו מה שאמר כ\"ק אדמו\"ר הזקן אויף אַ תאוה איז קיין קשיא<sup data-n=\"3913\">79</sup>, כי בעצמותו ית' אינו שייך ענין הטעם כו'], לכן השלמת כוונה זו מוסיפה גם בבחי' הוי' כמו שיהי' לו לאלקים.ט) <b>ועפ\"ז</b> י\"ל השייכות של אתה אחד כו' לט' ויו\"ד כסלו<sup data-n=\"3914\">80</sup>. דהנה ידועים<sup data-n=\"3915\">81</sup> דברי הצ\"צ בנוגע להסתלקות כ\"ק אדמו\"ר האמצעי \"שהסתלקות כזו לא מצינו מיום פטירת הרשב\"י ע\"ה\", וכמסופר בהקדמה לתו\"ח מבנו של כ\"ק אדמו\"ר האמצעי ש\"דרש כשעה ויותר עד שהגיע לפסוק<sup data-n=\"3916\">82</sup> כי עמך מקור חיים . . . לא סיים בוצינא קדישא למימר חיים\" (כמו שנאמר<sup data-n=\"3917\">83</sup> בהסתלקות הרשב\"י). והנה ידוע<sup data-n=\"3918\">84</sup> בפי' הכתוב כי עמך מקור חיים, שבחי' מקור חיים הוא רק עמך, טפל ובטל לך. דמזה מובן שמה שאמר אז בעל ההילולא הפסוק כי עמך מקור חיים הוא בדוגמת בחד קטירא אתקטרנא<sup data-n=\"3919\">85</sup>, שלגבי בחינה זו, הבחי' דמקור חיים היא טפל ובטל. ועפ\"ז יובן השייכות דאתה אחד כו' גוי אחד בארץ לט' כסלו, כי הכח להמשכת בחי' אחד גם בעניני ארץ, הוא מבחי' לפני הוי' (כנ\"ל בד\"ה אתם נצבים), וגם עניני ארץ המתבררים ונכללים בבחי' אחד מגיעים בעצמותו ית' (כנ\"ל בפי' והאבן הזאת גו' יהי' בית אלקים). וזהו ג\"כ השייכות דאתה אחד כו' לענין הגאולה, כידוע<sup data-n=\"3920\">86</sup> \"שהבשורה מהגאולה באה בשבת ט' כסלו לעת המנחה בעת שאמר כ\"ק אדמו\"ר האמצעי דא\"ח ד\"ה אתה אחד\", כי ע\"י (אמירת דרוש זה בשבת לעת המנחה, רעוא דרעוין) שפועל המשכת אחד בארץ, בחי' ברבים היו עמדי, הנה עי\"ז נעשה פדה בשלום נפשי.\nי) <b>וזהו</b> ג\"כ הוראה לכאו\"א ההולכים באורחותיו, ובפרט לאלו העוסקים בהעבודה דיפוצו מעינותיך חוצה, שזה הי' ענינו של כ\"ק אדמו\"ר האמצעי, וכידוע<sup data-n=\"3921\">87</sup> שאדמו\"ר האמצעי – הו\"ע ספירת הבינה, שלכן אמר דא\"ח באופן של התפשטות והתרחבות, רחובות הנהר דבינה<sup data-n=\"3922\">88</sup>, וגילוי עתיק הוא בבינה<sup data-n=\"3923\">89</sup>. ומצד ההתרחבות דבינה (ובפרט מצד גילוי עתיק שבבינה), נמשך הגילוי גם למטה<sup data-n=\"3924\">90</sup>, הפצת המעינות <i>חוצה</i>, המשכת בחי' אחד <i>בארץ</i> [ועפ\"ז יש לבאר בדא\"פ מה שבעת שאמר אדמו\"ר האמצעי הדרוש אתה אחד הנ\"ל, הפסיק באמירתו ואמר \"שַא, פנו מקום דער טאַטע איז דאָ\"<sup data-n=\"3920\">86</sup>, כי אדמו\"ר הזקן הו\"ע ספירת החכמה<sup data-n=\"3925\">91</sup>, והחכמה ובינה הן תרין רעין דלא מתפרשין<sup data-n=\"3926\">92</sup>, לכן בעת שאמר הדרוש אתה אחד כו' אחד בארץ, ענין ההתרחבות דבינה,הי' אז גם אדמו\"ר הזקן, ספירת החכמה], הנה ע\"י העבודה דיפוצו מעינותיך חוצה, וכידוע<sup data-n=\"3927\">93</sup> אַז דער מיטעלער רבי האָט געוואָלט, אַז ווען צוויי יונגעלייט טרעפן זיך זאָלן זיי ריידן בענין אריך ועתיק כו', שזהו ענין הפצת המעיינות חוצה, שגם כשהמעיינות באים חוצה בלייבן זיי \"מעיינות\", הנה עי\"ז נעשה פדה בשלום נפשי, גאולה פרטית, ומזה באים אח\"כ גם לגאולה כללית, ועד לגאולה האמיתית והשלימה, שאז יהי' אמיתית האחדות וההתכללות, וכמ\"ש<sup data-n=\"3928\">94</sup> ולא ילמדו עוד איש את רעהו (וכמבואר בד\"ה אתם נצבים הנ\"ל<sup data-n=\"3929\">95</sup>), כי מלאה הארץ דיעה את הוי' כמים לים מכסים.\n**********",[["3834","*","התחלת וסיום המאמר – הוגה ע\"י כ\"ק אדמו\"ר שליט\"א. וראה לקמן הערה 28."],["3835","1","ראה לקמן הערה 74."],["3836","2","ראה אבודרהם."],["3837","3","נדפס (ברוקלין, תשכ\"ה [ולאח\"ז במאמרי אדמו\"ר האמצעי קונטרסים ע' ג ואילך])."],["3838","4","להעיר שהקביעות דט' כסלו חל [בכו\"כ שנים כמו בשנה זו ובשנת הגאולה – תקפ\"ז] בפ' ויצא. ראה של\"ה חלק תושב\"כ ר\"פ וישב שבפרשת השבוע מרומז הענין שבהשבוע. וראה לקמן בפנים ובהערה 75."],["3839","5","כח, כב."],["3840","6","שם, יח."],["3841","7","ריש פרשתנו."],["3842","8","שם, כ."],["3843","9","חולין צא, ב. פרש\"י שם, יא."],["3844","10","לקו\"ת ברכה צח, ג ואילך."],["3845","11","שם, כא."],["3846","12","וראה לקמן (בסיום המאמר) שבשורת הגאולה היתה בט' כסלו."],["3847","13","בשנת תקפ\"ז, וההסתלקות – בשנת תקפ\"ח."],["3848","14","כמבואר בכמה מאמרי ד\"ה פדה בשלום גו' השייכות לפנימיות התורה, תורת החסידות."],["3849","15","נדפס בס' בד קודש (ווארשא תרל\"ב. ועוד [ולאח\"ז באגרות-קודש אדמו\"ר האמצעי ע' רפט]). בית רבי ח\"א פי\"ח [ולאח\"ז באגרות-קודש אדה\"ז ח\"א ע' צח]. ועוד."],["3850","16","ובפרט, לפי המבואר לקמן (בסיום המאמר) השייכות של אדמו\"ר האמצעי ואדמו\"ר הזקן. ולהעיר, שגם הגאולה די\"ב-י\"ג תמוז שייכת לענין זה, כמובן מזה שכמה מאמרים די\"ב-י\"ג תמוז התחלתם הוא פדה בשלום נפשי. (ולהעיר, שבשנת המאסר והגאולה (תרפ\"ז) חל י\"ב תמוז ביום השלישי) – [ראה גם לעיל ע' קמב]."],["3851","17","ובפרט לפי המסופר בבית רבי ח\"ב פ\"ה בהערה, שהגאולה היתה בעת אמרו תהלים (כפי שנחלק לימי החודש) פסוק פדה בשלום נפשי."],["3852","18","קובץ מכתבים (נדפס ב\"ספר תהלים אהל יוסף יצחק\") ע' 200."],["3853","19","לשונו של כ\"ק אדמו\"ר מהר\"ש – הובא בקובץ מכתבים שם. (ומפרש שם, שהכוונה הוא להוספת שיעור תהלים השבועי)."],["3854","20","ראה שיחת ליל כ' כסלו תרצ\"ד (נדפסה בלקו\"ד ח\"א צז, א ואילך)."],["3855","21","פי\"א."],["3856","22","כמבואר בד\"ה פדה בשלום שם פי\"ב."],["3857","23","ראה עד\"ז המשך פדה בשלום תש\"ד בסופו: דבחי' רבים שהם הסט\"א היו עמדי שנכללו בקדושה.\nבד\"ה פדה בשלום לבעל ההילולא שם מפרש \"ברבים בתוך רבים בחי' המקיף דיחידה שנק' מקיף כללי שכולל לכל מקיפים פרטים כו'\". ע\"ש. ויש לקשר זה עם הפירוש שבפנים, כי הכח לפעול שגם בחי' רבים יהיו עמדי (כהפירוש שבפנים), הוא מבחי' מקיף הכללי שלמעלה מהתחלקות, כמבואר לקמן בפנים. וראה רשימות הצ\"צ לתהלים עה\"פ כמה פי' בתיבת רבים."],["3858","24","ירושלמי סוטה פ\"א סה\"ח. במדב\"ר פ\"ט, כד."],["3859","25","אגה\"ק סי' ט'. תו\"א לה, א."],["3860","26","ב\"ר פ\"ח, ח."],["3861","27","בראשית א, כו."],["3862","28","יצא לאור בקונטרס בפ\"ע – \"<i>יד כסלו</i>, <i>ה'תשל\"ב</i>\" (ונדפס אח\"כ במאמרי אדמו\"ר האמצעי דברים ח\"ג ע' תשלט ואילך). ובפתח דבר: \"כ\"ק אדמו\"ר שליט\"א הואיל לאמר מאמר זה (לבד חלק המדבר בתק\"ש מלכיות זכרונות ושופרות וכו') – בהוספת התחלה וסיום (ובאיזה שינויים) – בהתוועדות דש\"ק ויצא, ט' כסלו (יום הולדת ויום ההילולא של כ\"ק אדמו\"ר האמצעי, וערב יום חג הגאולה – יו\"ד כסלו)\" תשל\"ב."],["3863","29","מכאן עד סוס\"ז – הנחה בלתי מוגה."],["3864","30","נצבים כט, ט."],["3865","31","שם, י."],["3866","32","ראה מגילה כב, א: \"כל פסוקא דלא פסקי' משה אנן לא פסקינן לי'\", ושו\"ע אדה\"ז חאו\"ח סתצ\"ד סי\"א."],["3867","33","פרק יב."],["3868","34","יתרו יט, ב."],["3869","35","שם כ, ב."],["3870","36","ראה לקו\"ת ר\"פ ראה."],["3871","37","תהלים קכב, ד."],["3872","38","ראה אוה\"ת (יהל אור) עה\"פ."],["3873","39","תו\"כ קדושים יט, לב. קידושין לב, ב."],["3874","40","ברכות סא, סע\"א. וראה אגה\"ק סט\"ו (קכב, ב). ובכ\"מ."],["3875","41","ראה מאורי אור מערכת י אות יט. מערכת כ אות מא."],["3876","42","ראה זהר ח\"ג רכד, סע\"א. תניא פי\"ב."],["3877","43","שופטים טז, יח ובפרש\"י. פרש\"י סנהדרין טז, ב – ד\"ה שוטרים."],["3878","44","ברכות נח, א."],["3879","45","פ\"ג."],["3880","46","תניא פ\"ד."],["3881","47","יבמות כב, א."],["3882","48","תו\"א משפטים עח, סע\"ג. ומציין שם לפירוש המשניות להרמב\"ם עירובין רפ\"ג (ושם: והמים והמלח אינם מהמזונות אבל הם מוליכים המזון). וראה גם סה\"מ תר\"ל ע' יז. תרנ\"ה ע' לג. ועוד."],["3883","49","שבת מא, א."],["3884","50","ע\"פ שבת פח, ב ואילך."],["3885","51","פ\"ג (ע' תשמג ואילך)."],["3886","52","וישב לז, ז."],["3887","53","ראה זהר ח\"ב לב, ב וברמ\"ז שם. ח\"ג רלא, א. מגלה עמוקות נצבים ד\"ה בעשירי (ס, ד). פענח רזא ס\"פ נצבים."],["3888","54","ברכה לג, ה."],["3889","55","מד, א."],["3890","56","פ\"ה (ע' תשמה)."],["3891","57","שמואל-ב ח, יד."],["3892","58","שמואל-א יג, ג."],["3893","59","רות ב, ו."],["3894","60","מלכים-א ד, יט."],["3895","61","שם כב, מח."],["3896","62","פ\"ו (ע' תשמו)."],["3897","63","שה\"ש ב, ו. וראה גם מאמרי אדמו\"ר האמצעי דברים ח\"ב ע' תקכט. ע' תרסו."],["3898","64","הושע ו, ב. וראה לקו\"ת דרושי ר\"ה סג, סע\"ב."],["3899","65","יתרו יט, ב ובפרש\"י שם."],["3900","66","יתרו שם, א ובפרש\"י."],["3901","67","יתרו שם, כ."],["3902","68","ראה סה\"מ תרצ\"ז ס\"ע 272. שם ע' 281. <i>ובכ\"מ</i>."],["3903","69","תענית כו, ב. ל, ב."],["3904","70","מכאן עד סוף המאמר הוגה ע\"י כ\"ק אדמו\"ר שליט\"א."],["3905","71","המשך תרס\"ו ע' תקמב ואילך."],["3906","72","בשלח, טז, כה. וראה אוה\"ת בשלח ס\"ע תרג ואילך. ס\"ע תרה ואילך. ע' תרלא. המשך תער\"ב ח\"ב ס\"ע א'קכז ואילך. לקו\"ש חכ\"א ע' 84."],["3907","73","ברכות יז, א."],["3908","74","מאמרי אדמו\"ר האמצעי שם ע' תשמו ואילך. <i>המו\"ל</i>."],["3909","75","תו\"א ויצא כב א-ב (ודלא כהפי' שם כא, ב. ובתו\"ח מבאר ע\"פ פי' זה) וראה לעיל ד\"ה אתם נצבים (פ\"ד) בפי' וירימה מצבה – הובא בתו\"א שם. (וי\"ל דב' הפי' הם בהמשך לב' הפי' באבן אחת שעשה יעקב נקודה תתאה או נקודה עילאה – ראה אוה\"ת ויצא ד\"ה בת\"א ד\"ה ושבתי פ\"ג ואילך)."],["3910","76","ראה גם תו\"ח שם פ\"ה."],["3911","77","ראה חולין צז, א."],["3912","78","ראה תנחומא בחוקותי ג. נשא טז. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו. ובכ\"מ."],["3913","79","המשך תרס\"ו סוף ע' ז. ובכ\"מ."],["3914","80","כמובן מהסיפור המובא לקמן בפנים. ולהעיר שכמה מאמרים מט' ויו\"ד כסלו התחלתם – אתה אחד."],["3915","81","הובא בבית רבי ח\"ב פ\"ו (ע' 204 בהערה). וראה לקו\"ש ט' כסלו (תש\"ל [לקו\"ש ח\"ה ע' 129 ואילך]) שזה מרומז גם בזה שהפסוק \"עד הגל הזה\" הרומז לל\"ג בעומר – יום הסתלקות הרשב\"י, נאמר בפ' ויצא, בה חל (בכו\"כ שנים) הקביעות דט' כסלו. ע\"ש באריכות."],["3916","82","תהלים לו, י."],["3917","83","אד\"ז (זח\"ג רצו, ב)."],["3918","84","תו\"א לה, ב. לקו\"ת תזריע כ, סע\"א. ובכ\"מ."],["3919","85","לשון הרשב\"י באד\"ז שם רפח, א."],["3920","86","\"מסורת בבית הרב\" – הובא בהוספה לבד קודש ע' 22 בהערה."],["3921","87","התמים ח\"ב ע' עח. סה\"ש תש\"ה ע' 60."],["3922","88","ראה זח\"ג קמב, א. עץ חיים שער ח (שער דרושי נקודות) פ\"ד. וראה לקו\"ת פ' ראה יח, ב."],["3923","89","ראה זח\"ג קעח, ב."],["3924","90","תו\"א ר\"פ לך. תו\"ח שם."],["3925","91","סה\"ש שם."],["3926","92","ראה זהר ח\"ב נו, א. ח\"ג ד, א. לקו\"ת שם."],["3927","93","בית רבי ח\"ב פ\"א הערה ה'. סה\"ש תש\"א ע' 52. (הלשון שם: \"ריידן <i>חסידות</i>\"). וראה סה\"ש תש\"ג ע' 13 (\"זאָלן יונגעלייט פאַרשטעהן אין כתר ווי די 5 פינגער, וועט ער זיין צופרידען\")."],["3928","94","ירמי' לא, לג. ישעי' יא, ט. וראה רמב\"ם בסופו, סוף הל' מלכים."],["3929","95","מאמרי אדמו\"ר האמצעי שם ע' תשמו. תשנא."]]],[1500370053,"<h3>בס\"ד. ש\"פ וישב, כ\"ף כסלו, ה'תשכ\"ז<sup data-n=\"3930\">*</sup></h3>\n<b>וישב</b> יעקב בארץ מגורי אביו בארץ כנען, ומבאר רבינו הזקן בעל הגאולה והשמחה בספרו תו\"א<sup data-n=\"3931\">1</sup>, להבין כפל לשון בארץ מגורי אביו בארץ כנען, שכנען פירושו סוחר, כמ\"ש<sup data-n=\"3932\">2</sup> כנעני' נכבדי ארץ, וכתיב<sup data-n=\"3933\">3</sup> כנען בידו מאזני מרמה, וכמו הסוחר שמפזר ממון בכדי להרויח ולהשתכר, וכל עיקר כוונתו היא להיות מפזר ונוסף עוד<sup data-n=\"3934\">4</sup> [דתכלית ענין המסחר הוא הריוח, וכמארז\"ל<sup data-n=\"3935\">5</sup> זבון וזבין תגרא איקרי בתמי'], כ\"ה גם ענין ירידת הנשמה למטה שתכלית הירידה היא בשביל העלי', שע\"י ירידתה למטה והתלבשותה בגוף ונה\"ב דוקא באה לבחי' עליונה יותר מכמו שהיתה קודם ירידתה.\n<b>ולהבין</b> זה בביאור יותר ובאריכות יותר, גם להבין מ\"ש רש\"י עה\"פ וישב יעקב, אחר שכתב לך ישובי עשו ותולדותיו בדרך קצרה, שלא היו ספונים וחשובים לפרש כו' פירש לך ישובי יעקב ותולדותיו בדרך ארוכה כו'. דלכאורה מכיון שישובי עשו ותולדותיו אינם ספונים וחשובים לא הוצרך לכתבם כלל, גם לא בדרך קצרה. וצריך לומר, דהגם שישובי עשו, מצ\"ע, אינם ספונים וחשובים, מ\"מ, מכיון שעל ידם באים לישובי יעקב, כתבם בקרא. אלא דלהיות שכל ענינם הוא מה שע\"י באים לישובי יעקב, כתבם בדרך קצרה. משא\"כ ישובי יעקב ותולדותיו, שהם ספונים וחשובים מצד עצמם, פירש אותם בדרך ארוכה. וצריך להבין מהו ענין מה שע\"י ישובי עשו באים לישובי יעקב, וגם צ\"ל דיוק הלשון דרך קצרה ודרך ארוכה.\nב) <b>ויובן</b> כ\"ז בהקדים מ\"ש<sup data-n=\"3936\">6</sup> פדה בשלום נפשי מקרב לי כי ברבים היו עמדי, וידוע הדיוק מ\"ש פדה בשלום, שמלשון זה משמע שאפשר להיות פדי' שאינה באופן של שלום, ולכן אומר כאן פדה בשלום דוקא, שפדי' זו היא בשלום. וגם צריך להבין מ\"ש מקרב לי, דאומר מקרב ולא השם מלחמה, כלשון הרגיל בכמה מקומות. דהנה לשון הקודש אינה לשון הסכמי<sup data-n=\"3937\">7</sup>, כ\"א הוא הלשון שבו נברא העולם<sup data-n=\"3938\">8</sup>, והיינו ששמו של כל דבר מורה על תוכנו וענינו הפנימי של הדבר, שזו היא חכמתו של אדה\"ר, ויתירה מזו, אשר השם מורה על החיות אלקי של הדבר הנקרא בשם זה,כמ\"ש רבינו הזקן בעל הגאולה והשמחה בשעהיוה\"א<sup data-n=\"3939\">9</sup>. דמזה מובן בענין שמות הנרדפים שבלה\"ק, אשר עם היות שכל השמות מורים, בכללות, לאותו הדבר, מ\"מ כל שם ושם, מורה און בריינגט אַרויס תוכן אחר. דכן הוא גם בהשמות קרב ומלחמה, שעם היות אשר גם קרב פירושו מלחמה, מ\"מ הנה בהכרח לומר, אשר תיבת קרב מורה על אופן מיוחד במלחמה, שמלחמה כזו דוקא נקראת בשם קרב. וצריך להבין מ\"ש כאן מקרב דוקא. וביותר אינו מובן עפ\"י מ\"ש בירושלמי<sup data-n=\"3940\">10</sup> שפדה בשלום נפשי מקרב לי קאי על מלחמות אבשלום, והרי מלחמה זו נקראת בתנ\"ך בשם מלחמה, ולמה קורא אותה כאן בשם קרב דוקא. והנה במ\"ש מקרב לי, ישנם שני פירושים. פי' א' הוא, דכאשר דוד הי' במצב של קרב, הנה אז, פדה בשלום נפשי. ופירוש הב' הוא, שפדה והוציא אותו מהקרב, דזהו מ\"ש מקרב במ\"ם (וכמו ממצרים פדיתנו, שפירושו הוא, הפדי' והיציאה ממצרים). וצ\"ל מהו\"ע ב\"פ אלו. והנה בסיום הענין אומר, כי ברבים היו עמדי. דכי הוא נתינת טעם, דמה שפדה בשלום גו' הוא לפי שרבים היו עמדי, וכמ\"ש בירושלמי<sup data-n=\"3940\">10</sup> שגם אנשי אבשלום התפללו עבור דוד, עי\"ז פדה בשלום נפשי. ועוד יש לפרש, שכי הוא מלשון אשר<sup data-n=\"3941\">11</sup>, והיינו שברבים היו עמדי הוא הפי' דפדה בשלום נפשי גו', שענין הפדי' בשלום הוא זה אשר ברבים היו עמדי, וממוצא דבר [משני פירושים אלו] מובן בפירוש כי ברבים היו עמדי, שע\"י אשר ברבים היו עמדי, הנה עי\"ז נעשה הפדי' בשלום גו' ושברבים היו עמדי.\nג) <b>ולהבין</b> כל זה, יש להקדים מ\"ש<sup data-n=\"3942\">12</sup> ואלה המלכים אשר מלכו בארץ אדום לפני מלך מלך לבני ישראל<sup data-n=\"3943\">13</sup>, ואיתא<sup data-n=\"3944\">14</sup> במד\"ר<sup data-n=\"3945\">15</sup> א\"ל הקב\"ה ליעקב אתה השפלת עצמך וקראת לעשו אדוני ח' פעמים, חייך שאני מעמיד מבניו ח' מלכים קודם לבניך, שנאמר ואלה המלכים כו' לפני מלך מלך לבנ\"י כו'. וצריך להבין, דהנה ידוע ומפורסם בקבלה ובחסידות שמלכין דתהו הן ז' מלכין, ובמדרש חשיב שמונה מלכים. וגם צריך להבין מה שבכתוב חשיב שמונה מלכים. וידוע הביאור בזה, שמלך השמיני, הדר, לא נאמר בו וימת, שלא הי' בו ענין השבירה, ואדרבה, ממנו הוא התחלת שורש התיקון<sup data-n=\"3946\">16</sup>. אבל צריך להבין, שהרי בדברי הימים<sup data-n=\"3947\">17</sup> נאמר וימת גםבהדר. וידוע הביאור בזה, כדאיתא בזהר הרקיע<sup data-n=\"3948\">18</sup> שבכתובים שהו\"ע המלכות, ובפרט דה\"י שקשור עם זמן, ספירת המלכות<sup data-n=\"3949\">19</sup>, מדובר בבחי' מלכים דנוקבא, היינו כמו שהספירות הם במלכות, ששם הי' ענין השבירה גם במלך השמיני, משא\"כ בתורה שהיא בחי' ז\"א, מדובר אודות מלכין דדכורא, שבבחי' זו לא הי' ענין השבירה במלך השמיני, בחי' יסוד<sup data-n=\"3950\">20</sup>, ואדרבה, ממנו הוא התחלת שורש התיקון. והנה, המלך הראשון (שבו היא התחלת השבירה) הוא בלע בן בעור, שהוא בחי' הדעת<sup data-n=\"3951\">21</sup> (ואין זה סתירה להמבואר במ\"א<sup data-n=\"3952\">22</sup> שההתחלה היא מן החסד, כמ\"ש באוצ\"ח<sup data-n=\"3953\">23</sup>). ולכאורה צריך להבין, שהרי מבואר שכל ענין השבירה הי' בהמדות<sup data-n=\"3954\">24</sup>. אבל מ\"מ צריך לומר שהשבירה היא מצד בחי' הדעת, וכמובן בפשטות מזה שענין השבירה למטה הו\"ע החטא דאדה\"ר שאכל מעץ הדעת, ענין הדעת דוקא.\nד) <b>וביאור</b> הענין הוא<sup data-n=\"3955\">25</sup>, דהנה, חטא עה\"ד ענינו הוא שהי' ההרגש בגשמיות, וכמ\"ש<sup data-n=\"3956\">26</sup> ותרא גו' כי טוב העץ למאכל וכי תאוה הוא לעינים, והיינו, שלפני חטא עה\"ד הי' החיך של אדה\"ר מרגיש טעם רוחני, והחטא הי' שהרגיש טעם גשמי. והענין הוא, דהנה ידוע שלפני החטא הי' אדה\"ר כלול מבי\"ע, ראשו בבריאה וגופו ביצירה ורגליו בעשי'<sup data-n=\"3957\">27</sup>, ומובן, שגם רגליו היו במדריגה נעלית יותר, שהרי הרגלים קשורים עם שאר הגוף, שהוא גוף אחד. ועוד זאת, שבתחלת הבריאה עולם על מילואו נברא<sup data-n=\"3958\">28</sup>. ולכן גם במדריגת רגליו של אדה\"ר הי' החיך הגשמי שלו מרגיש טעם רוחני. וזהו שאמרו רז\"ל<sup data-n=\"3959\">29</sup> שעקבו של אדה\"ר מכהה גלגל חמה, דעקב הוא מדריגה התחתונה שברגל, ואעפ\"כ הי' מכהה גלגל חמה, שזהו\"ע המזלות, והיינו, שעקבו של אדה\"ר הי' למעלה מהמזלות. וענין המזלות הוא כמארז\"ל<sup data-n=\"3960\">30</sup> אין לך עשב מלמטה שאין לו מזל מלמעלה המכה בו ואומר לו גדל, וכפי שמדייק אדה\"ז<sup data-n=\"3961\">31</sup> הלשון אומר לו <i>גדל</i>, שאין הכוונה שעצם ההתהוות נעשה מהמזל, אלא שלאחר שנתהווה המציאות, אזי נעשה ע\"י המזל הגדלות שלו, בטעם ומתיקות ובשאר הענינים. ומובן שכיון שהמזל הוא רוחני, הרי לא שייך בו מתיקות גשמי. ועד\"ז יובן באדה\"ר שעקבו הי' מכהה גלגל חמה, שהי' למעלה מהמזלות, שהחיך שלו הי' טועם טעם רוחני. והחטא הי' שטעם טעם גשמי, והפירוש בזה, שרצונו הי'לטעום טעם גשמי, ולכן הרגיש את הטעם הגשמי. ואין הכוונה שעי\"ז נעשה הטעם הגשמי, שהרי גם כפי שעולם על מילואו נברא הי' הטעם גשמי, אלא שלפני החטא טעם אדה\"ר את הטעם הרוחני, ואילו הטעם הגשמי הי' נבלע ונכלל בתוך הרוחני, שלא הי' מציאות בפ\"ע. וענין החטא הי' שרצה להרגיש את הגשמי כמו שהוא מצד עצמו. וזהו שקודם החטא הי' גופו ביצירה, ששם הי' טועם מתיקות התורה, ובמדרגת רגליו בעשי', הי' הרגש המתיקות רק מתיקות רוחני, והגשמי הי' נגרר אחר הרוחני. והחטא הי' שרצה להרגיש את הגשמי. וזהו גם הפירוש במ\"ש<sup data-n=\"3962\">32</sup> וידעו כי ערומים הם, שאין הכוונה שמתחלה לא ידעו, דא\"כ מהו החידוש שלא יתבוששו<sup data-n=\"3963\">33</sup>, אלא מ\"ש וידעו הו\"ע ההכרה וההרגשה, והיינו, שבתחילה לא הי' בענין זה ההרגש והתאוה, וכמ\"ש בראשית חכמה<sup data-n=\"3964\">34</sup> שקודם החטא הי' ההרגש שכשם שע\"י היד מקיימים מצות תפילין (שהוקשה כל התורה כולה לתפילין<sup data-n=\"3965\">35</sup>), כמו\"כ ע\"י אבר זה מקיימים מצות פרו ורבו, שהיא מצוה רמה ונשאה, וכמ\"ש<sup data-n=\"3966\">36</sup> לא תהו בראה לשבת יצרה, והחטא פעל שנעשה אצלם ההרגש והתאוה בענין זה. ולכן הי' צריך להיות הענין של כתנות<sup data-n=\"3967\">37</sup>, ומזה נשתלשל להלכה בפועל שצריכים ענין הלבושים. וכמו\"כ הוא בענין חטא עה\"ד, שסיבתו הוא הדעת וההרגשה, והיינו שהחטא הי' מה שנעשה אצלו ההרגש של הדבר הגשמי כפי שהוא מצד עצמו, ולא כמו שהוא נגרר אחר הרוחני. ומזה מובן גם למעלה, שסיבת השבירה בהמדות הו\"ע ההרגש, בחי' הדעת.\nה) <b>והנה</b> חטא עה\"ד פעל ירידה בכל סדר ההשתלשלות, כשם שבאדה\"ר פעל החטא ירידה לא רק ברגליו בעשי', שהרגיש טעם גשמי, אלא גם בגופו שביצירה, דעולם היצירה הו\"ע המדות, דז\"א מקננא ביצירה<sup data-n=\"3968\">38</sup>, והיינו, שהחטא פעל ירידה גם בהמדות שביצירה, שהמדות כפי שהם לאחרי החטא אינם דומים להמדות כפי שהיו לפני החטא. וכשם שהירידה ברגליו שבעשי' היתה ע\"י הדעת וההרגש, כמו\"כ גם הירידה במדות באה ע\"י ההרגש.\n<b>וביאור</b> הענין הוא, דהנה התחלת המדות הו\"ע חסד, ובחסד יש חסדים המכוסים וחסדים המגולים<sup data-n=\"3969\">39</sup>. חסדים מגולים הו\"ע החסד כפי שבא בגילוי, וחסדים המכוסים היינו כפי שהחסד הוא בהעלם מצד השכל. ואין הכוונה בחסדים המכוסים להמדות הכלולים בשכל, כי, בהיותם כלולים בשכל אינם מדות שבלב אלא מדות שבשכל, ואז לא שייך לחלק בין חסדים המכוסים לחסדים המגולים, וא\"כ, הכוונה בחסדים המכוסים היא להמדות כפי שהם במקומם בלב, אלא שהם בטלים מצדהשכל שמאיר בלב. והענין בזה, דהנה, עם היות שהמדות נמצאים מהשכל, וכמ\"ש בתניא<sup data-n=\"3970\">40</sup> שחב\"ד נקרא אמות ומקור למדות, שע\"י שמתבונן במה רבו מעשיך הוי'<sup data-n=\"3971\">41</sup> ומה גדלו מעשיך הוי'<sup data-n=\"3972\">42</sup> מתגלים המדות, אהבת הוי' ופחדו ויראתו ולפארו כו', וכמ\"ש הרמב\"ם<sup data-n=\"3973\">43</sup> והיאך היא הדרך לאהבתו ויראתו בשעה שיתבונן כו', שע\"י ההתבוננות המתאימה לאהבה נולד מדת האהבה, וע\"י ההתבוננות המתאימה ליראה נולד מדת היראה, מ\"מ, בשעה שמאיר תוקף השכל, אי אפשר להיות מציאות המדות בהתגלות, ורק בשעה שמסתלקים המוחין, שאינו מאיר כלום, או שהשכל מאיר בדרך מקיף עכ\"פ, אזי יכול להיות מציאות המדה בהתגלות. אמנם, יש דרגה במדות שאפילו בשעה שהשכל הוא בגלוי, ופועל ביטול בהמדות, מ\"מ ישנם המדות במציאותם בלב. וענין זה הוא כאשר מתבונן בעומק ופנימיות השכל ומבין את השכל שלא ע\"י כלי ההבנה והשגה, שהם כלי המוח, אזי יכול אור השכל להאיר גם בלב. והיינו, שכאשר ההתבוננות היא ע\"י כלי המוח בלבד, הרי זה מאיר רק במוח ולא בלב, משא\"כ כאשר ההתבוננות היא בפנימיות ובעומק השכל למעלה מכלי המוח, אזי אין שם הגבלות המוח, ויכול להאיר גם בלב (ואדרבה, עיקר מציאותן הוא בלב), ובשעה שהשכל מאיר בלב הרי זה פועל ביטול בהמדות, והיינו שהעיקר הוא השכל, ואדרבה, פנימיות השכל, ומ\"מ יש מציאות של מדה בלב, אלא שהמדה אינה מורגשת, להיותה בטלה אל השכל שמאיר בלב, והו\"ע פנימיות המדות. והנה, מצד פנימיות המדות שבהם מאירים פנימיות המוחין, לא יכול להיות יניקה לחיצונים, כיון שהמדות אינם ניכרים ונרגשים, משא\"כ מצד חיצוניות המוחין שמהם נעשים חיצוניות המדות, יכול להיות יניקה לחיצונים. וזהו ענין חטא עה\"ד, שנעשה ענין ההרגשה בהמדות שהם ניכרים ונרגשים, והו\"ע חסדים המגולים.\n<b>והענין</b> בזה בעבודת הוי'<sup data-n=\"3974\">44</sup>, דהנה, ישנו הענין דקרבת אלקים טוב, וישנו הענין דקרבת אלקים <i>לי</i> טוב<sup data-n=\"3975\">45</sup>. קרבת אלקים טוב היינו שאלקות הוא טוב מצד עצמו, ומזה אין יניקה ללעו\"ז. והו\"ע עץ החיים, שעז\"נ<sup data-n=\"3976\">46</sup> ואכל וחי לעולם, שאין מזה יניקה ללעו\"ז. משא\"כ קרבת אלקים <i>לי</i> טוב הוא באופן שנעשה מורגש, שמערב בזה מציאותו, עד שיכול להיות שהעיקר הוא מה שמרגיש את עצמו, והאלקות הוא רק בדרך טפל, ולכן אם אינו מרגיש את עצמו, היינו שאינו מרגיש איך שאלקות <i>לי</i> טוב, אזי יכול להיות שתתבטל האהבה, וזהו\"ע חסדים המגולים, שהוא בבחי' הרגש עצמו. ומזה יכול להיות יניקה ללעו\"ז, והיינו, דעם היות שגם ההרגש דקרבת אלקים לי טוב הו\"ע של קדושה, מ\"מ, יכול להיות מזה יניקה ללעו\"ז, כידוע שמחסדדאברהם יכול להיות אהבה דפלשתים (כמבואר בענין קליפת פלשתים<sup data-n=\"3977\">47</sup>). ואע\"פ שגם בבחי' חיצוניות המוחין (שמהם נמשכים חיצוניות המדות, חסדים המגולים) יכולה להיות שמירה מהיניקה ללעו\"ז, עי\"ז שהשכל מאיר בבחי' מקיף, מ\"מ, הרי יש צורך בזהירות ועצה כו' (אַ באַוואָרעניש), משא\"כ בפנימיות המוחין, ששם אין צריך על זה זהירות כלל.\nו) <b>והנה</b> ידוע שחטא עה\"ד פעל הענין דתערובות טוב ורע, וכמבואר בשיחה של כ\"ק מו\"ח אדמו\"ר מי\"ט כסלו<sup data-n=\"3978\">48</sup> דבכל דבר ודבר יש תערובות טוב ורע ואין טוב בלא רע, ואין רע בלא טוב, כידוע<sup data-n=\"3979\">49</sup> שלאחר חטא עה\"ד כל דבר שבעולם הוא באופן של התערבות טו\"ר. וענין זה הוא מצד הדעת, דהנה, מי שאין לו דעת כלל או שיש לו רק קטנות הדעת, הולך לפי תומו, היינו, שכל דבר שעושה הוא בתכלית התמימות ללא התערבות דבר הפכי, דכאשר עושה דבר טוב אין מעורב בו רע, וכאשר עושה דבר רע אין מעורב בו טוב, מפני שאין לו דעת וערמומיות, משא\"כ מי שיש לו דעת וערמומיות, שיכול להסתיר את עצמו (ער קען זיך אויסבאַהאַלטן), אזי אפשר שבעשיית הדבר תהי' לו איזה כוונה ופני' וכיו\"ב, שאז הנה גם כאשר בחיצוניות עושה דבר טוב, מ\"מ, יכול להיות שבפנימיות הרי זה דבר רע, וכן להיפך שבחיצוניות הוא רע ובפנימיות הוא טוב. וע\"ד מ\"ש<sup data-n=\"3980\">50</sup> חושך שבטו שונא בנו, שאף שבגלוי הו\"ע של גבורה שמייסר את בנו, הרי מצד הכוונה שבזה הו\"ע של חסד, שעושה זאת מצד אהבתו אל בנו, והיינו, שאע\"פ שמצד אהבתו אל בנו רוצה רק להטיב לו בטוב הגלוי, מ\"מ, ע\"י הדעת נעשה התגברות השכל להטות את המדה, כיון שמעמיק ומבין שאע\"פ שאוהב את בנו, מ\"מ, לטובתו צריך לייסרו, ועי\"ז נעשית אצלו נטי' לגבורה, ומצד הנטי' למדת הגבורה, בא אח\"כ בגלוי שמייסר את בנו. וזהו ענין חטא עה\"ד, שענין הדעת פועל תערובות טו\"ר.\n<b>אך</b> צריך להבין, שהרי הקליפות אין להם מוח הדעת, וכמ\"ש בזהר<sup data-n=\"3981\">51</sup> אל אחר אסתריס ולא עביד פירין כו'. והביאור בזה, שזה שאין להם דעת היינו פנימיות הדעת, שפועל ביטול בהמדות, שמזה אין יניקה ללעו\"ז, אבל יש להם חיצוניות הדעת, שמזה יכול להיות יניקה ללעו\"ז, ועי\"ז נעשה תערובות טו\"ר. והענין הוא, דהנה, ענין ההתערבות שייך רק כשיש פרטים, וכמ\"ש אדמו\"ר האמצעי<sup data-n=\"3982\">52</sup> שד' היסודות כמו שהן מצד עצמן לא שייך בהם ענין ההתכללות, ורק מצד זה שיסוד האש יש בו ג\"כ יסוד המים ויסוד המים יש בו ג\"כ יסוד האש כו', לכן שייך ענין ההתכללות. וכן הוא בענין הדעת, שלהיותו ענין ההעמקה שעי\"ז בא השכל בריבויפרטים, לכן פועל ענין ההתכללות וההתערבות. ואין זה סתירה להמבואר במ\"א<sup data-n=\"3983\">53</sup> שריבוי הפרטים שבשכל באים ע\"י הבינה, כי, מצד הבינה נמצאים הפרטים רק בדרך כלל, משא\"כ כשמבין ע\"י ההעמקה שבכח הדעת, אזי בא הענין בפרטי פרטיות כו'. וזהו מעלת הדעת על המוחין חו\"ב, דהנה בכללות השכל יש אורך רוחב ועומק, אורך הו\"ע נקודת החכמה, היינו שעצם הסברא כמו שהיא נמשכת ויורדת ממדריגה למדריגה, רק שהיא בבחי' התלבשות כו'. ורוחב הו\"ע הבינה שמפרט את הפרטים שבשכל, אבל זהו בכללות עדיין. ואח\"כ בא ענין העומק שהו\"ע הדעת, שמצד העומק נעשה אמיתית ענין הפרטים, שמוצא בהשכל כל הפרטי פרטים שבו, ומצד זה יכול להיות ההתכללות וההתערבות.\nז) <b>אמנם</b> עפ\"ז צריך להבין מ\"ש התרגום עה\"פ<sup data-n=\"3984\">54</sup> עץ הדעת טוב ורע, דאכלין מיני' חכימין בין טב לביש, היינו, שע\"י הדעת יכול להבחין להבדיל ולהפריש בין טוב לרע. וכדאיתא בגמרא<sup data-n=\"3985\">55</sup> שמפני זה קבעו הבדלה בחונן הדעת, שאם אין דיעה הבדלה מניין כו'. וכאן מבואר להיפך, שע\"י הדעת נעשה תערובות טו\"ר. אך הענין הוא, דהנה, כאשר הרע הוא בגלוי ובגסות, אזי העבודה להבחין בו כו' אינה קשה כ\"כ, ואין צריכים על זה למוח הדעת דוקא. אמנם, כיון שע\"י חטא עה\"ד נעשה תערובות טוב ורע בעולם, ונעשה גם דקות הרע, הנה על זה יש צורך בעבודה ביגיעה דוקא (ועי\"ז ומצאת<sup data-n=\"3986\">56</sup>), להבחין גם בדקות הרע ולברר הטוב מהרע. והענין בזה, דהנה כתיב<sup data-n=\"3987\">57</sup> חבלי השוא וכעבות העגלה חטאה, היינו, שאם מתחילה לא יהי' חבלי השוא, אי אפשר שיבוא לידי חטא שהוא כעבותות העגלה, דאיך שייך שיעשה דבר כזה, ורק עי\"ז שבתחילה הי' חבלי השוא, שהו\"ע דקות הרע, הנה מזה בא אח\"כ לעבותות העגלה חטאה, גסות הרע. אך כדי להבחין בדקות הרע ולבררו צריך להתייגע יותר, וכידוע<sup data-n=\"3988\">58</sup> שיעקב הי' בבית לבן כ' שנה בכדי לברר גם דקות הרע, משא\"כ גבי עשו לא הי' צריך ריבוי זמן, משום שבעשו הי' רק גסות הרע. וענין זה נעשה ע\"י מוח הדעת, והיינו, מצד המרחב שבדעת, שנכנס בעומק הדבר ויודע כל הפרטים שבו (שמצד זה גופא נעשה התכללות והתערבות טו\"ר כנ\"ל), יש בכחו להבחין גם בדקות הרע ולברר הטוב מן הרע.\nח) <b>ועיקר</b> ענין הדעת הוא שעל ידו נעשה החלטת הדבר, והיינו, שההבחנה בין טוב לרע, חכימין בין טב לביש, יכולה להיות גם מצד חו\"ב, אבל מ\"מ, לא יהי' אצלו ההחלט מה לעשות, שהרי מצד השכל יכול להיות סברות לכאן ולכאן. וכידוע<sup data-n=\"3989\">59</sup> הראי' מדור המבול, שמצד אותה סברה עצמה שחייבה שיהי' מבול, כי יצרלב האדם רע מנעוריו<sup data-n=\"3990\">60</sup>, היתה אח\"כ המסקנא שלא אוסיף עוד להכות גו', ולא יהי' עוד מבול לשחת הארץ. והיינו, שמצד השכל עצמו לא יכול לבוא לידי החלט, ורק ע\"י הדעת שנכנס בעומק הדבר, אזי יכול לבוא לידי החלט איך לעשות. וזהו מ\"ש<sup data-n=\"3991\">61</sup> ובחרת בחיים, והיינו, דאף שכבר נאמר<sup data-n=\"3992\">62</sup> ראה נתתי לפניך גו' את החיים ואת הטוב ואת ההיפך, מ\"מ, אינו מסתפק בזה, ואומר ובחרת בחיים, ובפרט עפמ\"ש אדה\"ז<sup data-n=\"3993\">63</sup> שהאותיות של ובחרת בחיים הם נתינת כח שיוכל להיות הבחירה בחיים, שמזה מובן שלא מספיק מה שיודעים שיש החיים וההיפך, כיון שמצד זה גופא יכול להיות שיבחור בההיפך ח\"ו, ולכן צ\"ל הציווי ובחרת בחיים, שזהו ע\"י ענין הדעת כנ\"ל. אך עדיין צריך להבין, איך זה שע\"י הדעת יכול לבחור בהטוב, דכיון שמצד השכל, הנה אף שחכימין בין טב לביש, מ\"מ יכול להיות שאעפ\"כ יבחור בההיפך, וכמ\"ש<sup data-n=\"3994\">64</sup> חכמים המה להרע, א\"כ, איך יהי' ובחרת בחיים ע\"י הדעת. והענין בזה, דהנה דעת מחבר חו\"ב, וא\"כ הדעת עצמו הוא למעלה מחו\"ב, והיינו, שדעת מקבל מבחי' הכתר, כידוע שבמקום שהדעת נמנה אין הכתר נמנה<sup data-n=\"3995\">65</sup>, היינו, שדעת הוא במקום הכתר, ולכן מצד בחי' זו יכול להיות ובחרת בחיים.\nט) <b>וביאור</b> הענין, דהנה ידוע שתכלית הידיעה שלא נדעך<sup data-n=\"3996\">66</sup>, והפירוש הפשוט בזה הוא, שמתחלה צריכים להבין כל מה שאפשר ואח\"כ באים אל תכלית הידיעה, שמבינים שבאמת אין יודעים כו'. אבל הפירוש הפנימי בזה הוא, שתכלית הידיעה היא שתהי' הידיעה במה שלא נדע, היינו, שגם הבחי' דלא נדעך תהי' בבחי' ידיעה. והענין בזה, דהנה, יש ידיעת החיוב וידיעת השלילה. ידיעת החיוב היא בבינה, שבאה באופן של השגה, שמשיג את השכל ע\"י תפיסא והתלבשות בהו' קצוות כו'. וידיעת השלילה היא בחכמה, דהיינו שמבין את השכל ע\"י ששולל ממנו הענינים שמנגדים וסותרים אותו. ומ\"מ מובן, שגם הדבר המושג בידיעת השלילה יש לו שייכות אל הענינים שהוא מושלל מהם, שהם בגדרו עכ\"פ, ולכן אפשר לשלול אותו מהם. אך יש עוד בחי' בידיעה שאינה באה גם ע\"י שלילה, מפני שאין הענין בגדר ידיעה כלל שנוכל לתופסו ע\"י שלילה, וזהו\"ע שלא נדעך. והענין בזה בהשגת אלקות, דהנה, יש בחי' ממכ\"ע ובחי' סוכ\"ע, בחי' ממכ\"ע שייך בה ידיעת החיוב, משא\"כ בבחי' סוכ\"ע שייך רק ידיעת השלילה, אבל מ\"מ הרי זה בגדר עלמין, שהרי נקרא סובב כל עלמין. אך יש בחי' שלמעלה מסוכ\"ע, גם מסובב הכללי, ואפילו מאמיתית ענין הסובב, ששם לא שייך אפילו ידיעת השלילה. וע\"ד מ\"ש בשער היחוד והאמונה<sup data-n=\"3997\">67</sup> שזהו כמי שאומר על איזה חכמה רמה ועמוקה שאי אפשר למששה בידיםמפני עומק המושג, שכל השומע יצחק לו, לפי שענין החכמה אינו בגדר מישוש כלל, אפילו לא בדרך שלילה. ועז\"נ תכלית הידיעה שלא נדעך, שגם בהבחי' דלא נדעך צ\"ל ענין הידיעה, והוא מה שעצם הנפש מכיר בעצם א\"ס (עצם נעמט עצם). וכמו עד\"מ<sup data-n=\"3998\">68</sup> תינוק קטן שיש לו עדיין קטנות הדעת או שאין לו דעת כלל, ומ\"מ נמשך לאביו, שאין זה מצד איזה טעם שמבין איך הוא אביו וכו', והוא רק בהכרה עצמית מפני שממנו נולד. וענין זה נמשך גם בכחות הגלוים, והו\"ע דעת אלקי שהוא למעלה מחו\"ב, ומצד דעת אלקי יכול להיות ההחלט לבחור בטוב, אף שמצד השכל יכול להיות באופן דחכמים המה להרע. וכיון שהציווי ובחרת בחיים הוא לכאו\"א מישראל, הרי מובן שהכח על זה ניתן לכאו\"א מישראל, גם לאנשים פשוטים שאין להם הבנה והשגה, והיינו, שהדעת אלקי שמצד העצם נמשך למטה מטה לכאו\"א מישראל, גם לאנשים פשוטים, שגם להם יש הנתינת כח שיהי' ובחרת בחיים.\nי) <b>והנה</b> כל זה הוא מצד פנימיות הדעת, משא\"כ מצד חיצוניות הדעת יכול להיות תערובות טו\"ר, וזהו שהתחלת השבירה הי' בבחי' הדעת, כי כל סיבת ההתערבות דטו\"ר הוא מצד הדעת, כנ\"ל. אמנם, גם ענין ההבדלה בין טו\"ר והבירור שבוחר בטוב ומפריד הרע הוא ע\"י הדעת, אלא שזהו מבחי' העליונה שבדעת, שהו\"ע ההכרה העצמית בעצמות אוא\"ס, שבחי' ומדריגה זו היא רק בקדושה. וזהו ענין מלך השמיני, הדר, שלא נאמר בו וימת, לפי שלא הי' בו ענין השבירה, והוא שרש ומקור התיקון. והענין הוא, דהנה מלך השמיני הוא יסוד, ויסוד הוא מקו האמצעי שנמשך מהדעת, וכמאמר אין קישוי אלא לדעת<sup data-n=\"3999\">69</sup>, ולמעלה יותר, שממשיך מבחי' הכתר, שהרי הכתר נמשך עד סיום הקו, ולכן אנו רואים שבהשפעת הטפה נמשך העצם יותר מאשר בהשפעת דעת ושכל, וכמבואר הראי' מזה שסומא מוליד שלם וכו'<sup data-n=\"4000\">70</sup>. ומשו\"ז לא נאמר בהדר וימת, מפני שביסוד לא הי' ענין השבירה, ואדרבה הוא שרש ומקור התיקון, שזהו\"ע הבירור. ובפרטיות יותר, הנה בענין הבירור גופא יש ב' אופנים, בירור מלמעלה למטה, ובירור מלמטה למעלה. והנה, כשהבירור הוא בדרך גילוי אור מלמעלה, יכול להיות שניצוצות דקדושה שנכבו יודחו ולא יתבררו, ועוד זאת, דכיון שהבירור אינו מכח התחתון, יכול להיות שלאחרי שיסתלק האור ישאר התחתון במדריגתו ולא יתברר. ולכן צריך להיות הבירור בדרך עבודה מלמטה למעלה. וזהו שיצחק רצה לברך את עשו, והיינו שרצה להמשיך עליו אור עליון שעי\"ז יתברר בדרך ממילא, וטעה בזה, כי הי' מתבטל לגמרי, וצריך להיות התיקון שלו ע\"י יעקב, שאז הוא בדרך בירור. ואף שביעקב כתיב ויתן גו'<sup data-n=\"4001\">71</sup>, יתן ויחזור ויתן<sup data-n=\"4002\">72</sup>, הרי אין הכוונה שהבירור הוא ע\"י גילוי אור מלמעלה, אלא שזה הי' רק בדרך נתינת כח, ואח\"כ צ\"ל הבירור בדרך של עבודה מלמטה למעלה. וענין זה נעשה ע\"י הדעת דוקא.יא) <b>וזהו</b> מ\"ש פדה בשלום נפשי מקרב לי כי ברבים היו עמדי. דהנה<sup data-n=\"4003\">73</sup>, יש אופן של פדי' בשלום שאינה בדרך מלחמה כלל, אלא בדרך מנוחה, כפי שמצינו בשלמה שהי' איש מנוחה<sup data-n=\"4004\">74</sup>, והניצוצות באו אליו בדרך ממילא, וכמו מלכת שבא שהביאה אליו את הניצוצות כו'<sup data-n=\"4005\">75</sup>, ומ\"מ, כאשר מלכת שבא חזרה למקומה נשארה כמקודם ולא נתבררה. משא\"כ בדוד, שאצלו הי' הבירור באופן של קרב, באופן של מלחמה. ובפרטיות יותר, יש במלחמה גופא ב' דרגות. יש מלחמה שהיא מרחוק, שאין רואים את האויב ואין יודעים מהנעשה אתו, שאז אין יכולים לבררו. אבל יש מלחמה שהיא באופן של קרב שמורה על הקירוב, שזהו מש\"נ בדוד מקרב לי. ועל זה אמר כי ברבים היו עמדי, וכמ\"ש בירושלמי שגם אנשי אבשלום התפללו לנצחונו של דוד, וכמ\"ש<sup data-n=\"4006\">76</sup> גם אויביו ישלים אתו, שבתיבת ישלים יש ב' פירושים, מלשון שלום, וגם מלשון שלימות. וענין זה נעשה ע\"י העבודה בבחי' קרב, מלחמה באופן של קירוב, שעי\"ז פועלים שברבים היו עמדי, דרבים הו\"ע רה\"ר, וכמ\"ש<sup data-n=\"4007\">77</sup> נעשה לשון רבים, וכמארז\"ל<sup data-n=\"4008\">78</sup> כתוב והרוצה לטעות וכו', ומהרבים נעשה עמדי, רשות היחיד דיחידו של עולם<sup data-n=\"4009\">79</sup>. וזהו פדה בשלום נפשי מקרב לי גו', שזוהי תפלת דוד, בחי' המלכות, כללות כנס\"י, היינו, שנותנים כח לכאו\"א מישראל שיוכל להיות אצלו הפדי' מקרב, שע\"י הבירור בבחי' קרב נעשה הפיכת התחתון, היינו, שאין זה באופן שמתבטל ממציאותו, אלא שמציאות התחתון גופא נהפך לאלקות, וכמ\"ש<sup data-n=\"4010\">80</sup> בכל לבבך בשני יצריך, שאין זה באופן שהרגו בתענית<sup data-n=\"4011\">81</sup>, אלא שגם הנה\"ב יהי' לו אהבה לאלקות. וכללות הענין בזה, שהבירור באופן דקרב אינו כמו אור השמש שמאיר בבית ע\"י שפותחים את החלונות, שאור השמש אינו מתערב ומתאחד בעניני הבית, ולכן לאחר שנסתלק אור השמש נשאר הבית אפל, ואין יודעים מהנעשה שם, אלא הבירור באופן דקרב הוא ע\"ד שהנשמה מתלבשת בגוף שהיא מתאחדת עם הגוף, שהרי קודם התלבשותה בגוף היתה הנשמה למעלה והשיגה שם מהות אלקות, ובהתלבשותה בגוף השגתה באלקות היא בבחי' המציאות דאלקות בלבד, והשגת המהות שלה הוא בענינים גשמיים, שזהו מפני שהנשמה מתאחדת עם הגוף ונה\"ב, והיינו, שנה\"א מרגשת את נה\"ב. וכמו\"כ לאידך גיסא, שנפש הבהמית עלי' נאמר<sup data-n=\"4012\">82</sup> רוח הבהמה היורדת למטה, מרגשת את נפש האלקית, ועי\"ז פועלת נה\"א על נה\"ב שיהי' אצלה השגת אלקות באופן שהשכל הטבעי משיג את האלקות, והיינו, לא רק באופן שהוא מקבל דבר שלמעלה הימנו, אלא באופן שהשכל הטבעי דנה\"ב נעשה כמו שכל התורה.<b>והנה</b> ב' אופני בירור הנ\"ל ישנם בכל ג' הקוין דתורה עבודה וגמ\"ח, אבל בכללות הרי זה ההפרש בין תורה לתפלה, שתורה הוא בבחי' קרב, שעי\"ז מתהפכת נה\"ב לאלקות, משא\"כ תפלה, שעז\"נ<sup data-n=\"4013\">83</sup> בחרבי ובקשתי, שתרגומו בצלותי ובבעותי, הו\"ע מלחמה סתם<sup data-n=\"4014\">84</sup>. וכיון שע\"י התורה נעשה שלימות הבירור, לכן בתורה לא נאמר וימת בהדר, משא\"כ בדה\"י שזהו בבחי' מלכות, שרגלי' יורדות כו'<sup data-n=\"4015\">85</sup>, במקום של היפך החיים, לכן נאמר וימת, כיון ששם לא נעשה ענין הבירור כו'. ואף שידוע שהבירורים הם בבחי' מלכות, שעז\"נ<sup data-n=\"4016\">86</sup> ותקם גו' ותתן טרף לביתה, שהו\"ע ירידת המלכות בבי\"ע לברר בירורים, יש לתרץ זה בב' אופנים, הא', שע\"י המלכות נעשה רק בירור ראשון ולא בירור שני<sup data-n=\"4017\">87</sup>, והב', שגם הבירורים שמבררת המלכות הם ג\"כ ע\"י שנמשך בה מבחי' היסוד כו'.\nיב) <b>וזהו</b> מ\"ש וישב יעקב בארץ מגורי אביו בארץ כנען, דכנען הוא לשון סוחר, שמפזר את ממונו בכדי להרויח, והו\"ע עליית הנשמה שע\"י ירידתה למטה והתלבשותה בגוף ונה\"ב. והנה ידוע<sup data-n=\"4018\">88</sup> שירידת הנשמה למטה אינה בשביל עצמה, כי הנשמה עצמה אינה צריכה תיקון, וירידתה למטה היא בכדי לברר את הניצוצות דתהו שנפלו למטה בדברים הגשמיים. וע\"י שמבררת את הניצוצות, מתעלית היא למעלה יותר מכמו שהיתה קודם ירידתה. וזהו מה שענין ישובי עשו ותולדותיו הוא הקדמה לוישב יעקב גו' בארץ כנען, כי ישובי עשו הו\"ע ז' מלכין דתהו, וכל ענין המסחר (כנען) של ירידת הנשמה למטה הוא מצד הניצוצות דתהו שנפלו בשבה\"כ, שזוהי הסיבה לירידת הנשמה (פיזור ממון), וכנ\"ל שהנשמה לא ירדה בשביל עצמה רק בכדי לברר את הניצוצות, וזוהי גם הסיבה להעלי' שנעשית ע\"י הירידה (הריוח שע\"י הפיזור), וכנ\"ל שעליית הנשמה היא ע\"י בירור הניצוצות דתהו.\n<b>והנה</b> מה שנקראים בשם ישובי עשו, אף שענין ההתיישבות היא בתיקון דוקא, כי גם בתהו ישנם בחי' הכלים, ובחי' הכלים הו\"ע ההתיישבות, אלא שישובי עשו הם בדרך קצרה, היינו, שענין ההתיישבות שבתהו היא בבחי' קיצור ומיעוט, כי בתהו היו אורות מרובים וכלים מועטים, שהכלים לא היו לפי ערך האורות כלל, כי לא הי' מזיגה נכונה בין האורות והכלים<sup data-n=\"4019\">89</sup> (נוסף לכך שגם הכלים מצד עצמם הם מועטים, היינו, שענין הכלי בהם הוא במיעוט), שזו היתה הסיבה לשבירת הכלים, שהאורות נסתלקו למעלה והכלים נשברו ונפלו למטה. וזהו מה שנתחדש בענין התיקון, שנעשה מזיגה נכונה בין האורות והכלים, אורות מועטים וכלים מרובים, שמצד זה הנה בתיקון ההתיישבות היא בריבוי, ישובי יעקב בדרך ארוכה.<b>והנה</b> אף שבחי' התהו מצד עצמה אינה כפי הכוונה, וכמאמר<sup data-n=\"4020\">90</sup> דין לא הניין לי', שזהו שישובי עשו ותולדותיו לא היו ספונים וחשובים, מ\"מ, הם הקדמה לענין וישב יעקב גו' בארץ כנען, שהרי כל ענין המסחר של ירידת הנשמה למטה הוא מצד שבה\"כ דתהו, כנ\"ל. וזהו שאחר שכתב לך ישובי עשו בדרך קצרה כתיב וישב יעקב בארץ מגורי אביו בארץ כנען, כי ירידת הנשמה למטה היא בכדי לברר את הניצוצות דתהו כנ\"ל, וזהו\"ע וישב יעקב בארץ מגורי אביו, שמגורי הוא לשון אוצר<sup data-n=\"4021\">91</sup>, וכמו אוגר בקיץ<sup data-n=\"4022\">92</sup>, והו\"ע אסיפת ובירור הניצוצות דתהו שנתפזרו ע\"י שבה\"כ. דהנה ידוע<sup data-n=\"4023\">93</sup> שענין שבה\"כ הוא שהכלים נפרדו מחיבורם, וכהמשל בזה מענין האותיות, שכאשר הם מחוברים בתיבה אחת, אזי נושאים הם בתוכם פירוש התיבה. וכמו בהאותיות ב'ר'ו'ך', שבהיותם מחוברים יחד בהצירוף דברוך נושאים הם ההשכלה שבתיבת ברוך, וכאשר הם מתפזרים זה מזה, אזי נשאר בכל אות רק רושם מההשכלה. וכמו\"כ הוא ענין שבה\"כ דתהו, שהכלים נפרדו מחיבורם כו'. וזהו\"ע מגורי אביו, שהנשמה בירידתה למטה אוספת ומבררת את הניצוצות דתהו שנתפזרו כו'. והנה, יש עוד פירוש במגורי אביו, שמגורי הוא מלשון יראה, וכמו שפירש הרב המגיד<sup data-n=\"4024\">94</sup> (שיום הילולא שלו בי\"ט כסלו, וגם ענין גאולת רבינו הזקן בי\"ט כסלו שייכת לענין ההילולא של הרב המגיד<sup data-n=\"4025\">95</sup>) שמגורי אביו הו\"ע היראה מאבינו שבשמים. ויש לבאר שייכות ב' הפירושים, ע\"פ משנת\"ל (ס\"ח ואילך) שעיקר הבירור שבתיקון הוא ע\"י בחי' הדעת האלקי, שהיא ההכרה עצמית שלמעלה מהשכל, שזהו\"ע תכלית הידיעה שלא נדע. וזהו\"ע מגורי אביו מלשון יראה (כפירוש הב'), בחי' יראת בושת, שבאה מצד ההכרה ברוממות הא\"ס שלמעלה מהשגה<sup data-n=\"4026\">96</sup>, בחי' תכלית הידיעה שלא נדע. ומצד הכרה זו נעשית הבחירה בטוב (כנ\"ל), שעי\"ז הוא עיקר אסיפת ובירור הניצוצות (פירוש הא' דמגורי). וזהו ג\"כ מה שארץ ישראל נקראת כאן בשם ארץ כנען, דענין כנען הוא כמ\"ש כנען בידו מאזני מרמה, שמצד המרמה נעשה תערובות טו\"ר, וכנ\"ל (ס\"ו) שמצד ענין הערמומית נעשה תערובות טו\"ר, והו\"ע חיצוניות הדעת, שזוהי הסיבה לשבה\"כ דתהו. אך התכלית של ירידה זו היא לעשות מארץ כנען ארץ ישראל, שזוהי העלי' הנעשית ע\"י הירידה, וכפי' השני שבכנען לשון סוחר, שהו\"ע הריוח שע\"י הפיזור.\n<b>וזהו</b> גם ענין המאסר והגאולה די\"ט כסלו, שבעת המאסר היתה הירידה בתכלית, וכידוע<sup data-n=\"4027\">97</sup> שרבינו הזקן סבל אז יסורי הגוף ויסורי הנפש כו'. אך תכלית ירידההלזו היא בשביל העלי', שזהו שבעת הגאולה ראו כל אפסי ארץ כו'<sup data-n=\"4028\">98</sup>, והו\"ע גילוי אלקות בהאותות ומופתים שע\"י הצדיקים, ואז הותחל עיקר הענין דיפוצו<sup data-n=\"4029\">99</sup> מעינותיך חוצה<sup data-n=\"4030\">100</sup>, והרי ע\"י הפצת המעינות דפנימיות התורה יהי' קאתי מר&lt;93&gt;, שאז יהי' גילוי פנימיות הדעת, כמ\"ש<sup data-n=\"4031\">101</sup> כי מלאה הארץ דעה את הוי' וגו', בקרוב ממש.\nיג) <b>והנה</b><sup data-n=\"4032\">102</sup> ענין המסחר, כנען הנ\"ל, הוא ע\"י וישב יעקב, השפלה<sup data-n=\"4033\">103</sup> וירידת הנשמה למטה לברר הגוף ונה\"ב וחלקו בעולם, בירור וזיכוך והעלאת ניצוצות דקדושה שנפלו בשבה\"כ דתוהו, וזהו שישובי יעקב באו ע\"י ישובי עשו ותולדותיו לפני מלך מלך לבנ\"י וישובי עשו הם בדרך קצרה דוקא, ע\"ד מחז\"ל<sup data-n=\"4034\">104</sup> (בקדושה) ישנה אדם לתלמידו דרך קצרה, כלים מועטין דתוהו, והם לא היו ספונים (וטמונים), כי בשרשם יעקב קדם, ולא היו חשובים, כי דין לא הניין לי'&lt;90&gt;, והבירור הנרצה הוא באופן דקרב, קירוב והרגשה דוקא (וכמשי\"ת לקמן בארוכה), שאז ברבים, נפשות עשו ל' רבים, היו עמדי, שלא יודחה כל ניצוץ דקדושה כנ\"ל, ועד אשר גם אויביו ישלים עמו זה הנחש, חויא דגרים מיתה בעלמא, בחי' רב, יהי' שלום, ורב שלום בניך<sup data-n=\"4035\">105</sup>, פדה בשלום.\n**********",[["3930","*","התחלת וסיום המאמר – הוגה ע\"י כ\"ק אדמו\"ר שליט\"א. וראה לקמן הערה 13."],["3931","1","ר\"פ וישב."],["3932","2","ישעי' כג, ח."],["3933","3","הושע יב, ח."],["3934","4","משלי יא, כד. וראה שער המצות להאריז\"ל פ' ראה (מצות הצדקה), וראה ספר הלקוטים פ' תצוה."],["3935","5","ב\"מ מ, ב."],["3936","6","תהלים נה, יט."],["3937","7","ב\"ר יח, ד."],["3938","8","ראה פרדס שער כב (שער הכינויים) פ\"א."],["3939","9","פ\"א."],["3940","10","סוטה פ\"ק סוף ה\"ח. וגם לפרש\"י בתהלים שמביא ע\"ז הכתוב וכל ישראל ויהודא גו' (שמואל-א יח, טז) – הרי מסיים שם (יח, יז): והלחם מלחמות ה'."],["3941","11","ראה ר\"ה ג, א."],["3942","12","וישלח לו, לא."],["3943","13","בהבא לקמן – ראה ד\"ה פדה בשלום עזר\"ת – יצא לאור בקונטרס בפ\"ע – <i>ערב חנוכה ה'תשכ\"ז</i> (ולאח\"ז בסה\"מ עזר\"ת ע' פח ואילך; שם ע' רמד ואילך). ובפתח דבר שם: \"כ\"ק אדמו\"ר שליט\"א הואיל לומר מאמר זה בהתוועדות חג הגאולה י\"ט כסלו שנה זו (עם הוספות ושינויים). ובהתוועדות דש\"ק כ' כסלו (ש\"פ וישב) אמר מאמר זה עוה\"פ ובאריכות יותר, בהוספת התחלה וסיום\"."],["3944","14","מכאן עד סוסי\"ב – הנחה בלתי מוגה."],["3945","15","ב\"ר פע\"ה, יא."],["3946","16","עץ חיים שער י (שער התיקון) פ\"ג. וראה זהר הרקיע שבהערה 18."],["3947","17","א א, נא."],["3948","18","פ' תרומה דרוש ז' מלכים (קעג, א ואילך)."],["3949","19","ראה תניא שעהיוה\"א פ\"ז (פב, א)."],["3950","20","עץ חיים שער ט (שער שבירת הכלים) פ\"ח. וראה זהר הרקיע שם."],["3951","21","עץ חיים שער ח (שער דרושי נקודות) פ\"ד. שער ט (שער שבירת הכלים) פ\"א."],["3952","22","שם פ\"ב."],["3953","23","שער הנקודים פ\"ה. פ\"ז [בדפוס קארעץ תקמ\"ג – כב, ג. כו, ג]."],["3954","24","ראה עץ חיים שער ח (שער דרושי נקודות) פ\"א. מאמרי אדה\"ז תקס\"ח ח\"א ע' א ואילך. ובכ\"מ."],["3955","25","ראה מאמרי אדה\"ז אתהלך לאזניא ס\"ע נה ואילך."],["3956","26","בראשית ג, ו."],["3957","27","ראה שער מאמרי רשב\"י לזח\"ג פג, א."],["3958","28","ראה ב\"ר פי\"ד, ז. וראה שם פי\"ב, ו. פי\"ג, ג (וביפ\"ת שם)."],["3959","29","ראה ויק\"ר פ\"כ, ב. זהר שם, ב (ברע\"מ)."],["3960","30","ראה ב\"ר פ\"י, ו. זהר ח\"א רנא, א (בהשמטות). ח\"ב קעא, ב. מו\"נ ח\"ב פ\"י."],["3961","31","תניא אגה\"ק סוס\"כ (קלב, א)."],["3962","32","בראשית ג, ז."],["3963","33","שם ב, כד."],["3964","34","שער הקדושה פט\"ז."],["3965","35","קידושין לה, א."],["3966","36","ישעי' מה, יח."],["3967","37","בראשית ג, כא."],["3968","38","תקוני זהר ת\"ו (כג, א)."],["3969","39","ראה גם סה\"מ עת\"ר ע' יג ואילך. המשך ר\"ה תרצ\"ב פי\"ד. ה'שי\"ת פי\"ג (סה\"מ ה'שי\"ת ע' 22 ואילך)."],["3970","40","פ\"ג."],["3971","41","תהלים קד, כד."],["3972","42","שם צב, ו."],["3973","43","הל' יסוה\"ת פ\"ב ה\"ב."],["3974","44","ראה המשך תער\"ב ח\"א ע' עט. ע' שסב. אגרות-קודש כ\"ק אדמו\"ר שליט\"א חי\"ח ע' שעא. ועוד."],["3975","45","תהלים עג, כח."],["3976","46","בראשית ג, כב."],["3977","47","תו\"ח תולדות קמג, ג ואילך."],["3978","48","תרצ\"ד סעיף ו (לקו\"ד ח\"א פז, א)."],["3979","49","ראה מאמרי אדמו\"ר האמצעי ויקרא ח\"ב ע' תשד. סה\"מ תרס\"ב ע' ש ואילך. ד\"ה אני חומה תר\"ץ. תרצ\"ב (סה\"מ קונטרסים ח\"ב ריג, א ואילך). ובכ\"מ."],["3980","50","משלי יג, כד."],["3981","51","ח\"ב קג, א. וראה לקו\"ת חוקת ס, ג. סה\"מ עת\"ר ע' קלח ואילך."],["3982","52","ראה ביאורי הזהר מקץ לב, סע\"ג ואילך. תו\"ח בראשית יג, א. נח עא, א. בד קודש ע' 14 (אגרות-קודש אדמו\"ר האמצעי ח\"א ע' רצד)."],["3983","53","ראה סה\"מ עת\"ר ע' רמז ואילך."],["3984","54","בראשית ב, ט. שם, יז."],["3985","55","ברכות לג, א. ירושלמי ברכות פ\"ה ה\"ב."],["3986","56","מגילה ו, ב."],["3987","57","ישעי' ה, יח."],["3988","58","ראה אוה\"ת ויצא רכו, א. וראה שם רכב, א. ועוד."],["3989","59","ראה תו\"ח בראשית יד, א."],["3990","60","נח ח, כא."],["3991","61","נצבים ל, יט."],["3992","62","שם, טו."],["3993","63","סה\"מ תרפ\"ט ע' 74."],["3994","64","ירמי' ד, כב."],["3995","65","עץ חיים שער כג (שער מוחין דצלם) פ\"ח. וראה תו\"א מג\"א צא, ג ואילך. לקו\"ת שלח מט, ג."],["3996","66","ראה בחינות עולם ח\"ח פ\"ב. ספר העיקרים מאמר ב ספ\"ל. של\"ה קצא, ב."],["3997","67","פ\"ט."],["3998","68","ראה גם סהמ\"צ להצ\"צ כג, סע\"א ואילך."],["3999","69","יבמות נג, ב."],["4000","70","ראה סה\"מ תרכ\"ט ע' שמה. ובכ\"מ."],["4001","71","תולדות כז, כח."],["4002","72","פרש\"י עה\"פ. ב\"ר פס\"ו, ג."],["4003","73","ראה ד\"ה פדה בשלום בשערי תשובה לאדמו\"ר האמצעי ח\"א פי\"א (נה, ד ואילך)."],["4004","74","דברי הימים-א כב, ט."],["4005","75","מלכים-א י, א-ב."],["4006","76","משלי טז, ז."],["4007","77","בראשית א, כו."],["4008","78","ב\"ר פ\"ח, ח."],["4009","79","ראה אוה\"ת (יהל אור) עה\"פ (ע' רח)."],["4010","80","ואתחנן ו, ה. משנה ברכות נד, א. ספרי ופרש\"י עה\"פ."],["4011","81","ירושלמי סוטה פ\"ה ה\"ה ובקה\"ע שם."],["4012","82","ע\"פ קהלת ג, כא."],["4013","83","ויחי מח, כב."],["4014","84","חסר קצת (<i>המו\"ל</i>)."],["4015","85","משלי ה, ה. וראה אוה\"ת נ\"ך ח\"א עה\"פ (ע' תקסד ואילך)."],["4016","86","משלי לא, טו."],["4017","87","ראה תו\"א פרשתנו (וישב) כח, סע\"א ואילך. ובכ\"מ."],["4018","88","תניא פל\"ז (מח, ב)."],["4019","89","ראה המשך תער\"ב ח\"א ע' תקצט ואילך."],["4020","90","ב\"ר פ\"ג, ז. שם פ\"ט, ב. וראה המשך תער\"ב ח\"ב ע' תרפא. סה\"מ פר\"ת ע' רצט ואילך. ספר השיחות תורת שלום ע' 134 ואילך. סה\"מ ה'ש\"ת ע' 55."],["4021","91","תו\"א פרשתנו כז, ב."],["4022","92","משלי י, ה."],["4023","93","ראה סה\"מ תרס\"ה ע' קג."],["4024","94","אור תורה פרשתנו (יז, ב)."],["4025","95","ראה שיחת כ' כסלו תרצ\"ד ס\"ג (לקו\"ד ח\"א קא, א)."],["4026","96","ראה סידור הערה לתיקון חצות (\"מה ששמעתי ממורי [הרב המגיד] ע\"ה\")."],["4027","97","שיחת י\"ט כסלו תרצ\"ג סכ\"א (לקו\"ד שם כט, א)."],["4028","98","ראה אגרות-קודש אדה\"ז ח\"א ע' צז ואילך."],["4029","99","ראה אגה\"ק דהבעש\"ט – נדפס בכתר שם טוב בתחילתו. ובכ\"מ."],["4030","100","ספר השיחות תורת שלום ס\"ע 112 ואילך."],["4031","101","ישעי' יא, ט."],["4032","102","מכאן ואילך – הוספת כ\"ק אדמו\"ר שליט\"א בכתי\"ק."],["4033","103","ראה תו\"א שם. תו\"ח ר\"פ וישב."],["4034","104","פסחים ג, ב."],["4035","105","עיין בכ\"ז אוה\"ת בראשית (מז, ב)."]]],[1500370054,"<h3>בס\"ד. י\"ט כסלו, ה'תשל\"א<sup data-n=\"4036\">*</sup></h3>\n(הנחה בלתי מוגה)\n<b>פדה</b> בשלום נפשי מקרב לי כי ברבים היו עמדי<sup data-n=\"4037\">1</sup>, וידוע מש\"כ<sup data-n=\"4038\">2</sup> כ\"ק אדמו\"ר הזקן להגאון החסיד רלי\"צ ז\"ל מבאַרדיטשוב<sup data-n=\"4039\">3</sup>, כשקראתי כו' פדה בשלום נפשי כו' יצאתי בשלום מהוי' שלום. ומזה מובן שענין השלום שבהפדי' הו\"ע עיקרי, שלכן מדגיש ענין זה (ג' פעמים<sup data-n=\"4040\">4</sup>) במכתבו: פדה בשלום, יצאתי בשלום, מהוי' שלום. וכן מובן גם מאגה\"ק שבתניא סי' ב' שכתבו אחר ביאתו מפ\"ב (לכללות אנ\"ש) שסיומו וחותמו שצ\"ל שלום כו', ההנהגה באופן אשר יתן ה' בלב אחיהם כמים הפנים וגו'. וכדמוכח ג\"כ מזה שבכו\"כ דרושי חסידות על פסוק זה<sup data-n=\"4041\">5</sup>, ובפרט בהדרושים די\"ט כסלו, מבואר שהענין והחידוש דפדי' זו הוא מה שהפדי' היא בשלום. וצריך להבין, דלכאורה הרי העיקר הוא עצם ענין הפדי' (בין בנוגע לדוד נעים זמירות ישראל (וכן בנוגע לדוד מלכא משיחא<sup data-n=\"4042\">6</sup>), ובין בנוגע לכ\"ק אדה\"ז בעל השמחה והגאולה, הרי עיקר הענין הוא מה שיצא מהמאסר לחירות), ומהי ההדגשה של בשלום דוקא. ועוד צריך להבין, הרי ההמשך דפדה בשלום נפשי הוא כנאמר בכתוב מקרב לי כי ברבים היו עמדי, ומכיון שהפדי' היא מקרב היינו מלחמה, וכן זה שישנם רבים (אלא שנהפוך הוא והרבים היו עמדי – כדאיתא בירושלמי<sup data-n=\"4043\">7</sup>), הרי מובן שהפדי' מצ\"ע הייתה צ\"ל באופן של מלחמה. וא\"כ צריך להבין מהו ההכרח דהפדי' תהי' בשלום דוקא. והנה נקודת הענין בזה, מבואר בד\"ה פדה בשלום אשר לכ\"ק אדמו\"ר האמצעי, ממלא מקומו של בעל השמחה והגאולה (בשערי תשובה – שער התפלה), דכאשר העבודה היא מצד בחי' יחידה, הנה אז הפדי' היא בשלום.\nב) <b>ויובן</b> זה בהקדים המאמר של בעל השמחה והגאולה<sup data-n=\"4044\">8</sup> ד\"ה להבין<sup data-n=\"4045\">9</sup> ענין מ\"ש בע\"ח בתחלתו דבחי'<sup data-n=\"4046\">10</sup> הנקודים המה יו\"ד אורות ביו\"ד כלים, ובחי'העקודים כל (עשר) האורות עקודים בכלי א', ומבאר, שלהבין זה יש להקדים תחלה להבין איך שייך למעלה באוא\"ס ענין של עשר ספירות, חכמה ובינה כו', הרי השם חכמה ובינה כו' מורה שהוא בחי' מציאות דבר מה באיזה מהות, ואילו אוא\"ס הוא אור פשוט, ועד שגם עולם האצילות הוא בבחי' בלי מה<sup data-n=\"4047\">11</sup>. וכמו\"כ בנוגע לבחי' הכתר שנקרא רצון, שהוא למעלה מעשר ספירות, וכמו בכחות הנפש, שכח הרצון הוא למעלה מכל הכחות פנימיים, ועד שמבואר בכ\"מ<sup data-n=\"4048\">12</sup> שהרצון אינו ענין נפרד מהנפש כמו חכמה ומה שלמטה הימנה, הרי כל ענין הרצון הוא שפועל ענין של שינוי, וכמו שאומרים יהי רצון, שפירושו רצון חדש, היינו שישתנה מכמו שהי' לפנ\"ז, ונמצא, שיש שינוי בין קודם שירצה, בעת שירצה, ולאחר שירצה, והרי אי אפשר לומר בשום אופן שימצא בחי' שינוי למעלה, שהרי נאמר בו<sup data-n=\"4049\">13</sup> אני הוי' לא שניתי. ונקודת הביאור בזה הוא החילוק שבין אורות וכלים, שמצד הכלים ישנו הענין דעשר ספירות, עד שנקראים בשם חכמה ובינה כו', וכן ענין הרצון שלמעלה מזה, משא\"כ מצד האורות הרי זה באופן של פשיטות דאחדות הפשוטה שלמעלה מכל ענינים אלו, ועז\"נ אני הוי' לא שניתי.\nג) <b>ויובן</b> ממה שרואים באדם למטה, מבשרי אחזה אלוקה<sup data-n=\"4050\">14</sup>, שישנו חילוק בין העלם וגילוי. דהנה, כל הענינים שישנם באדם בגילוי, הרי האפשרות להתגלות שלהם היא מפני שישנם לפנ\"ז בהעלם בנפשו. וכמו החכמה שהיא ראשית הכחות הפנימיים, הנה התגלותה באדם היא עי\"ז שישנה לפנ\"ז בעצם נפשו, אלא שבעצם נפשו אין זה באופן של חכמה גלוי' עד שאפשר לתפסה בכלי ההבנה וההשגה דבינה, אלא שם הוא כח היולי בלבד, שממנו יכול לבוא אח\"כ ענין החכמה והשכל. ואפילו כפי שבא אח\"כ לידי גילוי, הרי זה באופן שנמשך תחילה כח המשכיל, שבו לא שייך עדיין ענין ההשגה ותפיסא ע\"י כלי הבינה, להיותו כח המשכיל על כל מיני שכל וחכמה, ואח\"כ נמשך מכח המשכיל גם ענין של חכמה גלוי', חכמה מסויימת, שיכולה לבוא אח\"כ בהיכל הבינה, נקודה בהיכלא<sup data-n=\"4051\">15</sup>. והנה, כפי שהכחות הם בעצם הנפש אזי לא שייך לחלק בין כח א' לזולתו, שהרי הנפש היא פשוטה, וכמו\"כ לא שייך שם ענין של שינויים, להיותם שם בפשיטות, ואינם אלא מקור שמהם יוכל אח\"כ להיות נמשך (בנוגע לענין השכל) כח המשכיל ואח\"כ שכל וחכמה גלוי', ולכן נקרא בשם חכמה, ע\"ש היותו מקור לחכמה, אבל כל ענין החכמה והשכל נמצא שם באופן של העלם, ונקרא גם בשם אור. אמנם, כאשר נמשך אח\"כ בגלוי, הרי זה ע\"י ענין הכלים, ומצד עניןהכלים נעשה ענין של שינוי, שיש מי שאצלו משפיע כח המשכיל כו\"כ עניני חכמה ובריבוי הן בכמות והן באיכות, ויש מי שאצלו לא בא הגילוי בריבוי כ\"כ ולא בחכמות אלו, בכמה שינויים בין אחד לחבירו. ועאכו\"כ כשנמשך בחכמה הגלוי', אזי יש חילוק גדול יותר בין אחד לחבירו, ועד שאפילו באדם זה עצמו יש שינויים מזמן לזמן, והיינו, שנוסף על השינוי הכללי דרוב שנים יודיעו חכמה<sup data-n=\"4052\">16</sup>, יש גם שינוי מזמן לזמן בשנה זו עצמה וביום זה עצמו, אם שכלו הוא בצלילות ובזכות ובבהירות, אם לאו, ששינויים אלה יכולים להיות ביום אחד, מזמן אחד ביום לזמן שני ביום. וכל זה הוא מצד ענין הכלים, דכיון שיש שינוי בין הכלים (כלי המוח ועד\"ז הכלים דשאר הכחות) של אדם זה לכלים של אדם שני, הרי זה פועל גם על הגילוי, היינו, כפי שאור השכל נמשך ומתגלה מעצם הנפש בכח המשכיל ואח\"כ בגילוי יותר בשכל גלוי, שאז נעשים בו שינויים.\n<b>וממשיך</b> לבאר<sup data-n=\"4053\">17</sup> שהשינוי שנעשה בהתגלות הכחות אינו אלא מצד הכלים, שההוכחה בזה היא ממה שרואים בענין הגלגולים, שנפש האדם בעל שכל, בחי' המדבר, מתגלגלת בבהמה או אפילו בדומם, היינו, שמתגלגל ונמצא שם עצם הנפש עם כל הכחות שלה, ואעפ\"כ, לא נעשה שינוי בהחי ועאכו\"כ בהדומם שיהי' בהם ענין השכל ששייך למין המדבר. והביאור בזה, דכיון שאין שם כלי המתאימה לקבל את אור השכל, לכן נשאר האור בהעלם, והיינו, שאף שנמצא שם, מ\"מ, נשאר הוא באותו אופן כמו שנמצא בעצם הנפש, ואינו בא בגילוי. והנה, ענין הנ\"ל הוא כפי שהאור הוא בהעלם כ\"כ שאינו פועל מאומה. ויש עוד דוגמא לזה, מכתיבת דבר שכל ע\"י אצבעות היד. דהנה, אף שהכלי להשכל הוא המוח שבראש, הרי רואים שכאשר האדם כותב דבר שכל בידו, צ\"ל תנועת האצבעות באופן מסויים כדי שיתגלה בהכתב דבר חכמה ושכל, ולא ענין שאין בו חכמה ושכל או ענין הפכי. ונמצא, שאע\"פ שהיד והאצבעות אינם כלים כלל לכח השכל, והראי', שתיכף כשפוסק לכתוב לא ניכר ענין של שכל באצבעות היד, ולא נשאר בהם אלא כח התנועה בלבד, מ\"מ, בשעת הכתיבה רואים כיצד נמשך ענין השכל ע\"י אצבעות היד. וכדאיתא בכמה מאמרים<sup data-n=\"4054\">18</sup> דוגמא לזה אפילו בהרגל, כפי שרואים בענין הריקוד באופן שתנועת הרגלים היא מכוונת לטעמי הניגון, שיוכל לכוין הטאק (כהלשון במאמר<sup data-n=\"4055\">19</sup>), שענין זה נמשך מהשכל שבראש. ומ\"מ אין זה באופן שהיד או הרגל הם כלים להשכל, שהרי ענין זה שייך רק בכלי המוח, שבו הוא משכן השכל, אבל בשאר אברי הגוף נמצא השכל בהעלם, ע\"י גידי המוח שמתפשטים בכל אברי הגוף, ועל ידם יכול העלם השכל לפעול גם ביד או ברגל שתהי' הכתיבה באופן שיתגלה הענין השכלי באותיות הכתב, ועד\"ז בנוגע להריקוד שברגל.<b>וכשם</b> שהוא בכחות האדם, כמו\"כ ישנו גם למעלה הענין דהעלם וגילוי, שהו\"ע דאורות וכלים, והחילוק הוא, שמצד ההעלם (ענין האור), הרי זה באופן דאני הוי' לא שניתי, אבל כפי שנמשך אח\"כ בגלוי, אזי ישנם השמות דעשר ספירות, עשר ולא תשע עשר ולא אחד עשר<sup data-n=\"4056\">20</sup>, ועד שאפשר להיות ענין השינוי, שכל זה הוא מצד הגילוי, שבו פועל ענין הכלי.\nד) <b>וממשיך</b> בהמאמר<sup data-n=\"4057\">21</sup>, שעפ\"ז יובן גם איך נמשך שכל האדם מלמעלה הימנו. ובהקדם שענין גילוי השכל הוא ע\"י האותיות, כידוע<sup data-n=\"4058\">22</sup> שאותיות הם מלשון אתא בוקר<sup data-n=\"4059\">23</sup>, שעל ידם נמשך ומתגלה הבוקר דאור השכל. דהנה, בכדי שאור השכל יבוא בהתגלות אפילו לעצמו, היינו, שהשכל כפי שהוא בעצם הנפש, יומשך ממנו כח המשכיל, וממנו יומשך אח\"כ שכל וחכמה הגלוי', אזי צ\"ל ענין האותיות שבשכל, אותיות המחשבה. וכדי שיומשך ויתגלה גם אל הזולת, הרי זה צריך לבוא גם באותיות הדיבור, או למטה יותר באותיות הכתב. וכמו שרואים ברב ותלמיד, שהרב אומר דבר שכל באותיות הדיבור או שכותבו באותיות הכתב, והתלמיד שומע את אותיות הדיבור או לומד מתוך הכתב, והיינו, שהמשכת השכל מהרב אל התלמיד היא דוקא ע\"י האותיות, שעל ידם נמשך השכל בגלוי, שאז יכולים לקרותו בשם חכמה בינה ודעת, חכמה מסויימת, ואז שייך בו שינויים, קטנות וגדלות וכו'. ואח\"כ כאשר התלמיד לומד הענין מתוך האותיות שבהם נתגלה השכל אליו, אזי מגיע להבנת השכל באופן שאינו צריך עוד להאותיות, והיינו, שמגיע להשכל כפי שהוא למעלה מאותיות, ששם בטלים האותיות לגבי אור השכל, ועד שיש לזה השפעה גם בהבחי' שלמעלה מהכחות הפנימיים והגלויים שבאדם. והנה, כשם שהתגלות שכל האדם היא ע\"י האותיות, כמו\"כ גם בנוגע להמשכת שכל האדם שנשתלשל מכח החכמה שבע\"ס דעשי', שענין זה נעשה ע\"י האותיות שהם הכלים שבע\"ס דעשי'. ועד\"ז בנוגע לע\"ס דעשי' שנמשך להם מע\"ס דיצירה, וע\"ס דיצירה מע\"ס דבריאה, וע\"ס דבריאה מע\"ס דאצילות, שגם בהם ישנו הענין דאורות וכלים, שעי\"ז מקבלים מהאותיות והכלים שלמעלה מהם (כפי שיתבאר לקמן) נעשה בהם ענין האורות ואח\"כ גם ענין הכלים. ואז שייך הענין דעשר ספירות, עשר ולא תשע כו', וכן הענין דמהות חכמה ובינה וכו', וכן ענין הרצון שיש בו ענין של שינוי, שיומשך רצון חדש כו' [כמו שהוא באדם, שרק כאשר הכחות הם בהתגלות (לאחרי שנמשכים מעצם הנפש ששם נמצאים כל הענינים באופן שאינם בגלוי), אזי יש בהם אורך רוחב ועומק, ועד שמתחלקים למספר עשר, כמבואר בפרדס בתחלתו<sup data-n=\"4060\">24</sup> שכל עניני העולם הם במספר עשר]. אלא שבעולם האצילות הרי הם באופן של נקודה, שזהו כללות העניןדעולם הנקודים, שהם עשר אורות בעשר כלים, אבל הם בציור של נקודה, וכנ\"ל שענין זה נמשך מלמעלה הימנו, ע\"ד המשכת שכל האדם מע\"ס דעשי', עשי' מיצירה, יצירה מבריאה ובריאה מאצילות.\nה) <b>אמנם</b> כל האמור לעיל הוא בנוגע להעלם וגילוי, היינו, שהענינים שהם תחילה בהעלם, עם כל העילויים והמעלות שבהם, נמשכים ובאים בגילוי. אך עדיין צריך להבין, איך יוכל להיות התהוות בעל גבול מאור א\"ס שהוא בלתי בעל גבול. ועל זה ממשיך בהמאמר<sup data-n=\"4061\">25</sup>, שענין זה אינו יכול להיות באופן של השתלשלות מן ההעלם אל הגילוי, אפילו לא ע\"י השתלשלות כו\"כ מדריגות, כי אם, כמ\"ש בע\"ח בתחלתו שהוצרך להיות ענין הצמצום הנקרא מקום פנוי, שסילק אורו על הצד, והו\"ע צמצום הראשון שהוא בדרך סילוק לגמרי, ואח\"כ נמשך קו קצר, ועי\"ז יכול להיות ענין הגבול, והיינו, שאף שלפנ\"ז היו ספירות אין קץ<sup data-n=\"4062\">26</sup>, או למעלה לגמרי מגדר ספירות, הנה ע\"י הצמצום נעשה עכ\"פ מקור לענין הגבול, וכמבואר בכמה דרושים<sup data-n=\"4063\">27</sup>, שגם עולם האצילות עצמו הו\"ע של בל\"ג, אלא שנעשה בו ענין שמחוץ לאצילות הו\"ע הגבול.\n<b>והנה</b> כיון שענין זה נעשה ע\"י הצמצום באופן של סילוק האור לגמרי, הרי מובן, שכאשר נעשה ענין של התגלות, אי אפשר שיתגלה מיד סדר השתלשלות שלם, אלא באופן שמתגלה נקודה אחת בלבד, וזהו שלאחרי הצמצום ישנו תחילה ענין עולם העקודים, שבו עקודים כל האורות בכלי אחד, ורק לאח\"ז נעשה ענין עולם הנקודים, שבו ישנם עשר נקודות בעשר כלים. ויובן זה ע\"ד דוגמא מנפש האדם<sup data-n=\"4064\">28</sup> (כנ\"ל שמבשרי אחזה אלוקה), שישנם החמשה שמות שנקראו לה עד לבחי' היחידה<sup data-n=\"4065\">29</sup>, שנקראת בשם יחידה להיותה בבחי' אחדות הפשוטה, שלכן מקבלת מבחי' יחיד<sup data-n=\"4066\">30</sup>, ניצוץ בורא<sup data-n=\"4067\">31</sup>. והרי בבחי' היחידה לא שייך לומר שיש בה עשר ענינים (אפילו אם נאמר שאינם באופן של חכמה גלוי' וכו', אלא רק מקור לחכמה ומקור לבינה וכיו\"ב בכל העשר כחות), כי זהו היפך ענינה של יחידה, אלא שם ישנו רק אור אחד, נקודה אחת. והדוגמא מזה יובן למעלה, שהגילוי הראשון לאחר הצמצום הוא באופן של נקודה אחת, ומזה נעשה אח\"כ ענין של עשר נקודות, אבל כפי שהם עקודים בכלי אחד. אך לכאורה אינו מובן איך שייך בכלל הלשון כלי (אפילו כלי אחד), שזהו כבר ענין של גילוי כו', הרי זה מיד לאחרי הצמצום, עוד לפני עולם הנקודים, וא\"כ, לא הי' צריך להיות ענין של כלי כלל. והביאור בזה, שהענין דכלי אחד אינו כמו שהוא בעולם הנקודים,עשר נקודות בעשר כלים, ששם ענין הכלים הוא באופן של מקור למציאות הכלי למטה, אלא הענין דכלי אחד הוא רק אפשריות שמזה יוכל להיות אח\"כ מקור למקור לענין של אורות וכלים, ומה שנקרא בשם כלי הרי זה רק בגלל שאין על זה לשון ותואר אחר מלבד \"כלי\", ע\"ש שסוכ\"ס יומשך מזה מקור לכלים שיהיו תחילה בהעלם ואח\"כ יומשכו בגילוי. ומ\"מ, אין זה באופן שאינו שייך כלל לענין גילוי, שהרי אדרבה, בהכלי אחד ישנם עשר נקודות, ועוד זאת, כמבואר במ\"א<sup data-n=\"4068\">32</sup> בארוכה שהנקודה הראשונה לאחר הצמצום כוללת את כל סדר ההשתלשלות, ולכן נקרא בשם עקודים, כיון שמעקד את כל סדר ההשתלשלות.\n<b>ויובן</b> גם זה ע\"פ הדוגמא מבחי' היחידה בנפש האדם, שכאשר בחי' היחידה היא בהתגלות, כמו בחתונת בנו יחידו וכיו\"ב<sup data-n=\"4069\">33</sup>, אזי מתגלים פתאום כל כוחותיו בבת אחת, והיינו שאין זה בדרך של סדר השתלשלות, שתחילה מתגלה ענין אחד ואח\"כ מתגלה ענין נוסף, חכמה ואח\"כ בינה, וכל עשר הכחות שמשתלשלים זמ\"ז, אלא כל הכחות מתגלים בבת אחת, היינו, גילוי השכל, ועשיית החסד בריבוי, נגינה בריבוי, ודיבור וריקוד בריבוי, שזהו לפי שבחי' היחידה היא בגילוי, ולכן יוצאים ומתגלים כל הכחות כפי שהם בהעלם בבחי' היחידה, ששם אינם באופן של עשר כלים, כי אם בכלי אחד, ולכן מתגלים כולם בבת אחת. והיינו, שכאשר ההמשכה היא מעצם הנפש, למעלה אפילו מבחי' האור כפי שהוא בהעלם, הרי זה נמשך בגילוי עד למטה, אפילו בריקוד שברגל. וכן הוא כביכול למעלה בבחי' אדם העליון ולמעלה יותר, שהנקודה הראשונה לאחר הצמצום כוללת ומקיפה את כל סדר ההשתלשלות עד למטה כו'.\n<b>ועפ\"ז </b>מובן הטעות של אלו שטעו בדמיונם והקשו איך יתכן ענין של השגחה פרטית בכל פרטי הנבראים עד לעולם העשי' הזה הגשמי, דלכאורה הרי זה שלא בערך כלל שתהי' השגחה פרטית בכל פרט ופרט. אך הענין הוא, ששורש טעות זו היא מצד ההתחלקות לכלים נפרדים, אפילו כפי שהוא בעולם הנקודים, ועאכו\"כ כפי שנמשך למטה מזה בעולמות בי\"ע. אבל מצד זה שכל הענינים כלולים בכלי אחד, ששם כולם בהשוואה, ואינם באופן של מציאות כלל, כי אם רק מקור למקור דמקור כו', אזי גם ההתגלות היא באופן שמתגלים כל הפרטים בשוה, ולכן יכולה להיות השגחה פרטית בכל פרט ופרט.\nו) <b>וממשיך</b> בהמאמר<sup data-n=\"4070\">34</sup> לבאר ענין זה בתוספת ביאור (שמבחי' העקודים ששם נמצאים כל הענינים בהעלם, כמו בבחי' היחידה, נמשכים ובאים כל הענינים בגילוי, באופן שיש חילוק בין עולם האצילות לעולמות שלמטה ממנו עד לעולם העשי'), שיובן ממה שמצינו בעולם (כנ\"ל שמבשרי אחזה אלקה) שיש ד' מדריגות דצח\"מ, שכל אחד מהם כלול מזולתו, היינו, שהמדבר יש בו ג\"כ ג'המדריגות דחי וצומח ודומם, ומזה מובן שגם החי כלול בו לא רק בחי' צומח ודומם, אלא גם בחי' מדבר, ועד שיכול להיות דם ובשר מבשרו של המדבר, שאז מתגלה מה שהי' תחילה בהעלם. ומה שכל אחד מהם נקרא בשם בפ\"ע, הרי זה ע\"ש ההתגלות, שבנברא זה מתגלה בחי' המדבר, ובנברא זה מתגלה בחי' החי, ועד\"ז בצומח ובדומם, אבל מצד ההעלם, הנה כשם שבבחי' המדבר כלולים חי צומח ודומם, כן הוא גם בשאר הסוגים, שגם בסוג הדומם כלולים צומח חי ומדבר. והיינו, שהחילוק הוא רק בהגילוי שבהם, ולא בההעלם שלהם. ועד\"ז הוא גם בעולמות אבי\"ע שהם כנגד דצח\"מ<sup data-n=\"4071\">35</sup>, שהתחלקות שביניהם היא רק מצד הגילוי, אבל כפי שהם כלולים בתכלית ההעלם בבחי' העקודים, הרי הם בשוה ממש. ומבחי' זו יכול להיות הגילוי בבת אחת ובשוה בעולם האצילות ובעולם העשי', ע\"ד התגלות בחי' היחידה שבנפש בריבוי השכל ובריקוד שברגל בבת אחת, ולכן יכול להיות ענין ההשגחה בכל פרט ופרט, כיון שנמשך מעולם העקודים ולמעלה יותר. ומזה מובן, שזה שבחי' היחידה וכן עולם העקודים הו\"ע של מקיף, אין הכוונה שמקיף וסובב מבחוץ, שהרי אדרבה, מזה נמשך ענין ההשגחה פרטית על כל פרט ופרט, וכמבואר בתניא<sup data-n=\"4072\">36</sup> שהענין דהשגח\"פ קשור עם חיות והתהוות הנברא, ואתה מחי' את כולם<sup data-n=\"4073\">37</sup>, א\"ת מחי' אלא מהווה<sup data-n=\"4074\">38</sup>, שזהו אמיתית ענינו שנמצא בתוכו ותוך תוכו, אלא שנמצא בו בהעלם.\nז) <b>ומסיים</b> המאמר<sup data-n=\"4075\">39</sup> בדבר טוב, שזהו ענין הברכות שאומרים ברוך אתה, לשון נוכח, ואומרים זה אפילו תינוקות ונשים. דלכאורה, כיון שאמירה זו היא לעתיקא קדישא (כמבואר בזהר<sup data-n=\"4076\">40</sup>) ועד לעצמותו ית', אמיתית המציאות, שרק הוא יכול להקרא בשם אתה, א\"כ, איך אפשר לומר עליו ברוך שהוא לשון המשכה<sup data-n=\"4077\">41</sup>, ועד שאפילו תינוק אומר זה. אך הענין הוא, שזהו לפי שמצד בחי' היחידה, וכן בחי' היחידה למעלה בעולם הנקודים ולמעלה מזה, נמצאים כל הענינים בשוה, ואדרבה, מרום וקדוש (את מי) אשכון את דכא ושפל רוח<sup data-n=\"4078\">42</sup> (דוקא). והיינו, שאף שלכאורה אין חילוק, מ\"מ, כאשר ישנו ענין של יש ומציאות, הרי זה מעלים ועד לאופן שגם מסתיר ח\"ו, משא\"כ מי שהוא דכא ושפל רוח, ששם אין דבר המעלים, אזי מרום וקדוש אשכון בגלוי<sup data-n=\"4079\">43</sup>.ח) <b>ועל</b><sup data-n=\"4080\">44</sup> פי זה יובן מ\"ש בהמאמר ד\"ה פדה בשלום הנ\"ל שמצד העבודה דיחידה הפדי' היא בשלום, דמכיון שמצד עצמות אוא\"ס, ועד\"ז מצד בחינת יחידה שבנפש, הרי כל הענינים הם בהשוואה, לזאת הנה גם כשישנו בחי' רבים, עד לריבוי גדול ביותר, שמצד זה נעשה ענין של קרב ומלחמה, כי ענין הריבוי הוא שישנם לא רק נפרדים זה מזה אלא גם סותרים זה את זה, מ\"מ מצד העבודה דבחי' יחידה, שהיא העבודה דבכל מאדך<sup data-n=\"4081\">45</sup>, וכמבואר בד\"ה פדה בשלום הנ\"ל שבחי' בכל מאדך הו\"ע מסירת הנפש עצמה שהיא למעלה ממסירת הרצון, שהוא מצד בחי' היחידה דנפש האלקית, הנה אז הוא מהפך בחי' היחידה דנה\"ב, שכל העצמיות שלה מתבטלת בבחי' היחידה דנה\"א, וכאשר העצם שלה מתהפך הרי במילא אין לה שייכות לענינים של היפך ח\"ו (וכמבואר בהמאמר שם, שכאשר העצמיות שלה מתהפך כו' הרי במילא נלקח גם מקור החיות של כל רצון זר כו'), ובמילא לא יתכן אז ענין המלחמה כלל, והפדי' היא בשלום.\n<b>ועל</b> פי זה תובן גם השייכות של פדה בשלום נפשי גו' [שההדגשה בזה מה שהפדי' היא בשלום דוקא] להגאולה די\"ט כסלו (התגלות דתורת החסידות), דהנה מבואר בכ\"מ<sup data-n=\"4082\">46</sup> שענינה של תורת החסידות גילוי פנימיות התורה, פנימית החכ' פנימית אבא (הוא פנימית עתיק) היא בחי' יחידה, ומצד בחי' יחידה הנה גם כאשר ישנו בחי' רבים, הפדי' היא בשלום<sup data-n=\"4083\">47</sup> (וי\"ל שזהו עוד יותר מהענין דעושה שלום במרומיו<sup data-n=\"4084\">48</sup> ע\"פ פירוש הרב המגיד<sup data-n=\"4085\">49</sup>, שזהו בדוגמת עוצם ביטול השר בבואו לפני המלך, משא\"כ כאן שבטלו הרצונות מעיקרא), שאין צריך למלחמה כלל, ואדרבה העבודה היא דוקא בדרכי נועם ובדרכי שלום, ועי\"ז נעשה (כמו שמסיים באגה\"ק הנ\"ל) שיהי' כמים הפנים וגו', היינו כפי סיום הכתוב<sup data-n=\"4086\">50</sup> כן לב האדם לאדם, שהכוונה בזה הוא גם לבחי' אדם העליון<sup data-n=\"4087\">51</sup>, שיהי' באור<sup data-n=\"4088\">52</sup> פני מלך חיים<sup data-n=\"4089\">53</sup>, שמצד זה יהי' (כמרז\"ל<sup data-n=\"4090\">54</sup> עה\"פ פדה בשלום נפשי) פדאני לי ולבני מבין אוה\"ע, והוא שבקרוב ממש יהי' אתי מר דא מלכא משיחא, ע\"י העבודה<sup data-n=\"4091\">55</sup> דיפוצו מעינותיך<sup data-n=\"4092\">56</sup>חוצה, שבעיקר הותחלה<sup data-n=\"4093\">57</sup> לאחרי הגאולה די\"ט כסלו, שמתוך מנוחה ושמחה וטוב לבב ובאופן של שלום תהי' היציאה בשלום מן הגלות בגאולה האמתית והשלימה ובקרוב ממש מהוי' שלום.\n**********",[["4036","*","התחלת וסיום המאמר – הוגה ע\"י כ\"ק אדמו\"ר שליט\"א. וראה לקמן הערה 9."],["4037","1","תהלים נה, יט."],["4038","2","נדפס בס' בד קודש (ווארשא תרל\"ב. ועוד [ולאח\"ז באגרות-קודש אדמו\"ר האמצעי ע' רפט]). בית רבי ח\"א פי\"ח. ועוד [ולאח\"ז באגרות-קודש אדה\"ז ח\"א ע' צח]."],["4039","3","הל' במאמר יונתי (לקו\"ת שה\"ש יח, ג). ועיין התוארים באגרת הנ\"ל ובאגה\"ק סכ\"ח (וצ\"ע מי כתבם)."],["4040","4","בבד קודש (ששם כנראה המכתב בשלימותו – ולא שזהו נ\"א) פעם ד': יצאתי בשלום ואסיים בשלום מה' שלום."],["4041","5","ראה ג\"כ רשימות הצ\"צ עה\"פ. ד\"ה פדה בשלום ה'תש\"ד (ותרנ\"ט), ה'תש\"ג (סה\"מ תש\"ד ע' 66 ואילך (תרנ\"ט ס\"ע קמא ואילך). תש\"ג ע' 184)."],["4042","6","ראה שערי תשובה (לאדהאמ\"צ) ח\"א ש' התפלה ד\"ה פדה בשלום פי\"א."],["4043","7","סוטה פ\"א ה\"ח. וכ\"ה בבמדב\"ר פ\"ט, כד."],["4044","8","בא' הביכלאך שנמצא עתה בדפוס (וראה סד\"ה א\"ר אלכסנדרי דש\"פ וישב, כ\"א כסלו (לקמן ע' תעב))."],["4045","9","יצא לאור בקונטרס בפ\"ע – \"<i>חנוכה</i>, <i>ה'תשל\"א</i>\" (ונדפס אח\"כ בסה\"מ תקס\"ח ח\"א ע' קיד ואילך). ובפתח דבר: \"בהתוועדויות דחג הגאולה י\"ט כסלו ושבת שלאחריו (ש\"פ וישב) שנה זו [תשל\"א] – אמר כ\"ק אדמו\"ר שליט\"א מאמר זה (בשינויים ו)בתוספת התחלה וסיום\"."],["4046","10","מכאן עד סוס\"ז – הנחה בלתי מוגה."],["4047","11","ראה ספר יצירה פ\"א מ\"ב ואילך. אגה\"ק ס\"כ."],["4048","12","ראה ספר המצוות להצ\"צ טו, א."],["4049","13","מלאכי ג, ו."],["4050","14","איוב יט, כו."],["4051","15","ראה זח\"א ו, א. תקו\"ז ת\"ה (יט, א). לקו\"ת ר\"פ ראה. ובכ\"מ."],["4052","16","לשון הכתוב – איוב לב, ז."],["4053","17","מאמרי אדה\"ז שם ע' קטז."],["4054","18","ראה סה\"מ תרס\"ד ס\"ע קלא ואילך."],["4055","19","ספר המצוות להצ\"צ קעז, ב."],["4056","20","ספר יצירה פ\"א מ\"ד."],["4057","21","מאמרי אדה\"ז שם ס\"ע קיז ואילך."],["4058","22","תו\"א מקץ מב, ב. אוה\"ת בשלח ס\"ע שצא. ובכ\"מ. סה\"מ תש\"א ע' 5."],["4059","23","לשון הכתוב – ישעי' כא, יב."],["4060","24","שער ב פרק ו. וראה לקו\"ש ח\"כ ע' 87 הערה 13 בשוה\"ג. לקו\"ש ח\"ל ע' 3."],["4061","25","מאמרי אדה\"ז שם ע' קכא."],["4062","26","ראה מאמרי אדה\"ז הנחות הר\"פ ז\"ל ע' קסט. אוה\"ת שה\"ש כרך ג ע' תתקסה. ספר הערכים חב\"ד כרך ג ע' קצב ואילך. וש\"נ."],["4063","27","ראה הגהות כ\"ק אדמו\"ר מהורש\"ב נ\"ע לד\"ה פתח אלי' שבתו\"א (ע' ט ואילך)."],["4064","28","מאמרי אדה\"ז שם ע' קכב."],["4065","29","ב\"ר פי\"ד, ט."],["4066","30","לקו\"ת ראה כה, א. מאמרי אדה\"ז אתהלך לאזניא ע' קסט ואילך. סה\"מ תרצ\"ו ע' 57. ובכ\"מ."],["4067","31","ראה עץ חיים שער מב פרק א. הובא בלקו\"ת ראה כז, א. ובכ\"מ."],["4068","32","ראה גם סה\"מ ה'שי\"ת ע' 60. ובכ\"מ."],["4069","33","ראה המשך תרס\"ו ע' כה ואילך. ובכ\"מ."],["4070","34","מאמרי אדה\"ז שם ע' קכג."],["4071","35","ראה עץ חיים שער מב פרק א. שער נו\"ן פרק א ואילך."],["4072","36","ראה שער היחוד והאמונה פ\"ב. וראה תניא פמ\"ח. הובא בסה\"מ תרס\"ג ס\"ע לד ואילך. סה\"מ תרצ\"ו ס\"ע 120. קונטרס השגחה פרטית (אגרות-קודש כ\"ק אדמו\"ר שליט\"א ח\"א ע' קעה). שיחת אחש\"פ תשמ\"ה (התוועדויות תשמ\"ה ח\"ג ע' 1835)."],["4073","37","נחמי' ט, ו."],["4074","38","שער היחוד והאמונה שם. וראה פרדס שער ו פרק ח. ראשית חכמה שער הקדושה ספ\"ז. של\"ה מח, ב. ע, א."],["4075","39","מאמרי אדה\"ז שם ס\"ע קכד ואילך."],["4076","40","ראה זח\"ג רצ, א."],["4077","41","תו\"א מקץ לז, ג."],["4078","42","ישעי' נז, טו."],["4079","43","עד כאן תוכן המאמר, בקצת שינויים ובקצת הוספות, לקישור הענינים."],["4080","44","מכאן ועד סוף המאמר הוגה ע\"י כ\"ק אדמו\"ר שליט\"א."],["4081","45","ואתחנן ו, ה."],["4082","46","ראה ג\"כ ד\"ה פדה בשלום, תרע\"ה (המשך תער\"ב ח\"ב ע' תשסו ואילך)."],["4083","47","עייג\"כ המשך מים רבים – תרל\"ו פפ\"ב ואילך."],["4084","48","איוב כה, ב."],["4085","49","הובא בביאוה\"ז (לאדהאמ\"צ) ר\"פ לך. ולהעיר משעה\"פ להאריז\"ל עה\"פ באיוב, אבל ידוע ששלום הוא יסוד (וכבשה\"פ שם), ת\"ת וגם פני' הכתר (ראה פרדס שעה\"כ בערכו. סד\"ה שלום רב, ה'תש\"ד)."],["4086","50","משלי כז, יט."],["4087","51","ראה פי' כמים הפנים גו' לאדה\"ז (הובא ברשימות הצ\"צ למשלי עה\"פ (אוה\"ת נ\"ך ע' תרלד ואילך))."],["4088","52","שם טז, טו."],["4089","53","ראה רשימות הצ\"צ עה\"פ משלי (טז, טו). ס\"ט (שם ע' תרט)."],["4090","54","ברכות ח, רע\"א."],["4091","55","ראה אגה\"ק דכ\"ק הבעש\"ט (נדפסה בס' פורת יוסף. כתר שם טוב בתחלתו. ובכ\"מ)."],["4092","56","להעיר מזח\"ג רפ, א."],["4093","57","תורת שלום ע' קיב."]]],[1500370055,"<h3>בס\"ד. ש\"פ וישב, כ\"א כסלו, ה'תשל\"א<sup data-n=\"4094\">*</sup></h3>\n(הנחה בלתי מוגה)\n<b>אמר</b> ר' אלכסנדרי כל העוסק בתורה לשמה משים שלום בפמליא של מעלה ובפמליא של מטה<sup data-n=\"4095\">1</sup>. והנה במאמר ד\"ה זה שנאמר לפני שלשים שנה (כ\"א כסלו תש\"א)<sup data-n=\"4096\">2</sup> מביא גם ג' הדיעות (בענין פעולת עסק התורה לשמה) שלאח\"ז<sup data-n=\"4095\">1</sup>: כאילו בנה פלטרין של מעלה ושל מטה, אף מגין על כל העולם כולו, אף מקרב את הגאולה. ומבאר בהמאמר שם, ששלום הו\"ע ההתחברות (והיינו שישנם ב' ענינים נפרדים ומחולקים זמ\"ז, וישנו שלישי העושה שלום ביניהם), ופמליא ענינו חיילות, ובעבודה הו\"ע המדות, וזהו כל העוסק בתורה לשמה משים שלום בפמליא כו', שע\"י עסק התורה לשמה עושה התחברות בהמדות. ומוסיף בהמאמר שם: והיינו המדות שבלב הנולדות מהמדות שבשכל (שהכוונה בזה לבאר ב' הענינים שבפמליא, פמליא של מעלה ופמליא של מטה, דפמליא של מעלה הו\"ע המדות שבשכל, ופמליא של מטה הו\"ע המדות שבלב. דהנה, המדות הם שרש ומקור הנבראים, שבעת ימי הבנין, והמוחין הם למעלה מעולמות, כמאמר<sup data-n=\"4097\">3</sup> אלפיים שנה קדמה תורה לעולם, שלכן בכללות המדות הם בחי' מטה והמוחין הם בחי' מעלה, אמנם בענין המדות (פמליא) גופא, הנה המדות שבלב הן פמליא של מטה והמדות שבשכל הן פמליא של מעלה). וכ\"ז היא פעולה הא' שבעסק התורה לשמה. ופעולה הב' כאילו בנה פלטרין כו' הוא (כמו שמבאר בהמאמר שם) ענין המוחין, וגם בזה ישנם ב' בחינות, פלטרין של מעלה ופלטרין של מטה, פלטרין של מעלה הו\"ע השכל שבמוח, ופלטרין של מטה הו\"ע השכל שבמדות, כמבואר בהמאמר שם. וזהו ג\"כ מה שבפעולה הא' אמרו <i>משים</i> שלום בפמליא כו' (והיינו שהפמליא ישנו כבר גם לפנ\"ז ורק שמשים שלום בה), ובפעולה הב' אמרו <i>בנה</i> פלטרין שבונה דבר חדש, כי המדות, מכיון שהם שרש ומקור הנבראים, הרי ישנם הם בעולמות מצד עצמם (והפעולה שנעשה בהם ע\"י עסק התורה לשמה הוא ענין השלום), משא\"כ המוחין שהם למעלה מעולמות, הרי המשכת המוחין שע\"י עסק התורה לשמה הו\"ע בנין חדש. והנה ידוע<sup data-n=\"4098\">4</sup> שבריאת העולמות היתה בשביל ישראל ובשביל התורה, דישראל הו\"ע ז\"א, המדות (וכידוע<sup data-n=\"4099\">5</sup> שישראל הוא ר\"ת יש ששים רבוא אותיות לתורה, וידוע<sup data-n=\"4100\">6</sup> שהמספר ששים רבוא הוא מצד בחי' המדות, וא\"וכלול מיו\"ד ויו\"ד מיו\"ד כו') ותורה הו\"ע המוחין, ומזה מובן שע\"י ב' פעולות הנ\"ל הנעשים ע\"י עסק התורה לשמה [משים שלום בפמליא כו', בחי' מדות (ישראל), ובנה פלטרין כו', בחי' מוחין (תורה)], בא אח\"כ גם בהעולם שנברא בשביל ישראל ובשביל התורה. וזהו\"ע הג'&lt;1&gt; אף מגין על כל העולם כולו, וכמ\"ש בהמאמר: שהמוחין ומדות מגינים על העולם שהם הפעולות הנעשות ע\"י השגת המוח והמדות שבלב. אמנם פעולה זו שנעשית בהעולם, זה שהמוחין והמדות (בחי' תורה וישראל) מגינים עליו, הוא השלימות דעולם כמו שהוא מצד הבריאה, שהרי תחילת בריאת העולם היתה בשביל ישראל ובשביל התורה כנ\"ל, אמנם פעולה הד' שבעסק התורה לשמה, אף מקרב את הגאולה, הוא ענין השלימות שלמעלה מענין הבריאה, וכמ\"ש בהמאמר: שנשתנה <i>בעצם מהותו</i> כו'. וכידוע<sup data-n=\"4101\">7</sup> בפירוש מחז\"ל<sup data-n=\"4102\">8</sup> כל תולדות שבמקרא חסרים חוץ משנים אלה תולדות השמים והארץ<sup data-n=\"4103\">9</sup> ואלה תולדות פרץ<sup data-n=\"4104\">10</sup>, דהגם ששניהם הם מלאים, מ\"מ יש הפרש גדול ביניהם, שאלה תולדות השמים והארץ הו\"ע בחי' השלימות כמו שהיא מצד הבריאה, משא\"כ ואלה תולדות פרץ, ענין הגאולה, הוא בחי' שלימות שלמעלה מענין הבריאה.\nב) <b>והנה</b> ד' הפעולות הנעשות ע\"י עסק התורה לשמה שמונה בגמרא שם (ובפרט שמדגיש בהמאמר בתחלתו: וחשיב כאן ד' ענינים), י\"ל שד' ענינים אלו הם כנגד ד' העולמות אבי\"ע, וכנגד ד' הפלוגות בספירות (וכידוע<sup data-n=\"4105\">11</sup> שהע\"ס נחלקות בכלל לד' – כנגד ד' אותיות הוי' וכנגד ד' העולמות), וענין העוסק בתורה לשמה שפועל ד' ענינים אלו הוא בחינה שלמעלה מד' העולמות, שלכן פועל בהם. והענין הוא, דהנה ידוע שבריאה הוא בחי' חב\"ד, יצירה בחי' חג\"ת, ועשי' הו\"ע הלבושים מחדומ\"ע, ולמעלה יותר, בחי' נה\"י. אמנם אצילות הוא עולם האחדות, והיינו שגם מצד הכלים הוא עולם האחדות, וכידוע שבאצילות הנה איהו וחיוהי חד וגם איהו וגרמוהי חד<sup data-n=\"4106\">12</sup>. וזהו מה שד' ענינים הנ\"ל הם כנגד ד' העולמות אבי\"ע – משים שלום בפמליא כו' שהו\"ע המדות כנ\"ל, בחי' חג\"ת, יצירה. בנה פלטרין כו' שהו\"ע המוחין כנ\"ל, בריאה. מגין על כל העולם כו', הנהגה בפועל בעולם הבאה מצד המוחין והמדות, בחי' נה\"י ומחדומ\"ע, עשי'. מקרב את הגאולה שהו\"ע השלימות שלמעלה מענין הבריאה כנ\"ל, בחי' אצילות עולם האחדות. וזהו שבהביאור בהמאמר במקרב את הגאולה כ' שנשתנה בעצם מהותו לטוב, כי באצילות לא יגורך רע<sup data-n=\"4107\">13</sup>. אמנם ענין העוסק בתורה לשמה שפועל ד' ענינים אלו הוא למעלה גם מעולם האצילות, כנ\"ל.ג) <b>ויש</b> לקשר זה עם המבואר בהמאמר ד\"ה להבין מ\"ש בע\"ח לאדה\"ז<sup data-n=\"4108\">14</sup> (שנאמר בי\"ט כסלו<sup data-n=\"4109\">15</sup>), שמבאר שם בענין בחי' עקודים בכלי אחד, שהוא בחי' כתר וכו', מקיף הכללי שלמעלה מהתחלקות, שלכן כולל כל הספירות בשוה. דבכללות הוא בחי' עצמות אוא\"ס שמאיר בכל העולמות בשוה. וכמו שמבאר בהמאמר שם, דזהו מה שגם תינוקות ונשים אומרים על עצמות אוא\"ס אתה לנוכח, כי מצד עצמות אוא\"ס כולם הם בשוה, וההפרש הוא רק בבחי' ההתגלות, אבל מצד בחי' ההעלם הכל שוין כו'. וזהו\"ע העוסק בתורה לשמה, שע\"י עסק התורה לשמה ממשיך בחי' מקיף הנ\"ל שלמעלה מעולמות, ולכן הוא פועל בכל ד' העולמות.\nד) <b>ויש</b><sup data-n=\"4110\">16</sup> להוסיף ביאור במאמר הנ\"ל, ובהקדמה, שמאמר זה הוא מאמר יסודי שמבאר כל סדר ההשתלשלות, אלא שמבאר הענין בקיצור נמרץ, וכמרז\"ל<sup data-n=\"4111\">17</sup> לעולם ישנה אדם לתלמידו בדרך קצרה. וזהו גם סדר הענינים שבהמאמר, שבתחילת המאמר מבאר כללות הענין דאורות וכלים, ואח\"כ מבאר בפרטיות, בתחילה כמו שהוא מלמטה למעלה, ואח\"כ כמו שהוא מלמעלה למטה. דהנה, בתחלת המאמר מבאר <i>כללות </i>הענין דאורות וכלים [ולהעיר, שבהכת\"י<sup data-n=\"4112\">18</sup> הי' כתוב תחלה: \"ענין או\"כ למעלה\", ואח\"כ העביר קולמוס על תיבת למעלה], שהאורות מצד עצמם הם בחי' העלם, וענין הגילוי הוא מצד הכלים דוקא. ומבאר זה ע\"פ משל מנפש האדם, מבשרי אחזה גו'<sup data-n=\"4113\">19</sup>, שכחות הנפש מצד עצמם הם בהעלם, ורק ע\"י התלבשותם באברי הגוף, אזי הם באים בגילוי. ולכן כשנפש האדם מתגלגלת בגופי דצ\"ח הרי היא בהעלם, לפי שאינם כלים אלי', וכן באדם גופא כשהשכל מתלבש באבר אחר זולת המוח, הוא בהעלם. ועד\"ז הוא למעלה, שגילוי הע\"ס הוא מצד הכלים דוקא, אבל האורות מצד עצמם הם בבחי' פשיטות והעלם. ולאחרי שמבאר <i>כללות </i>הענין דאורות וכלים, ממשיך לבאר את הענין כמו שהוא מלמטה למעלה, וכמו שהוא מלמעלה למטה. בתחילה מבאר הענין מלמטה למעלה, היינו<sup data-n=\"4114\">20</sup> שהשכל שבנפש האדם מתהווה מבחי' הכלים דעשי', וכן האורות דעשי' נמשכים מבחי' הכלים דיצירה, וכן הוא בכל סדר ההשתלשלות, שבחי' האורות שבכל עולם נמשכים מבחי' הכלים דהעולם שלמעלה ממנו. ואח\"כ מבאר הענין מלמעלה למטה, היינו<sup data-n=\"4115\">21</sup> של' כלים דאצילות נעשים נר\"ן לבי\"ע. מבחי' יו\"ד כלים פנימיים, בחי' חב\"ד, נעשה בחי' נשמה לבריאה, מבחי' יו\"ד כלים תיכונים, בחי' חג\"ת, נעשה בחי' רוח ליצירה, ומבחי' יו\"ד כלים חיצוניים, בחי' נה\"י,נעשה בחי' נפש בעשי'. וממשיך בהמאמר, שבכל עולם (מג' עולמות בי\"ע) ישנם ג' הבחינות חב\"ד חג\"ת ונה\"י, ורק שעולם הבריאה עיקרו חב\"ד, עולם היצירה עיקרו חג\"ת, ועולם העשי' עיקרו נה\"י.\nה) <b>והנה</b> מה שנוגע בהמאמר לבאר שבכל עולם ישנם ג' הבחינות חב\"ד חג\"ת ונה\"י (בפשטות) הוא, לפי שבלאה\"כ אינו מובן ענין המספר למ\"ד כלים. דלכאורה, מכיון שבבריאה נמשך רק מבחי' חב\"ד שבכלים דאצילות, ביצירה רק מבחי' חג\"ת, ובעשי' רק מבחי' נה\"י, הרי ישנם רק ג' פעמים ג', ומהו\"ע ל' כלים. ולכן מבאר, שבכל עולם ישנם כל ג' הבחינות כו'. אמנם בעומק יותר, הנה ענין זה שבכל עולם ישנם כל הבחי', נוגע לכללות תוכן המאמר. דהנה, מה שבעולם הבריאה ישנם גם חג\"ת ונה\"י, וכן בחי' חב\"ד ונה\"י ביצירה, חב\"ד וחג\"ת בעשי', הוא דוגמת ההתכללות דדצח\"מ שמבאר בהמאמר להלן<sup data-n=\"4116\">22</sup>, שהשינוי והחילוק שבין ד' הסוגים דצח\"מ הוא רק מצד בחי' הגילוי, אבל מצד בחי' ההעלם, כולם שוין. ועפ\"ז מבאר<sup data-n=\"4117\">23</sup> ענין ההשגחה פרטית בכל חלקי דצח\"מ דעשי' [ועד\"ז בד' עולמות אבי\"ע שנמשלים לדצח\"מ<sup data-n=\"4118\">24</sup>], כי ההשגחה שמצד עצמות אוא\"ס שבבחי' העלם, היא בשוה בכולם. והיינו שבחי' ההתכללות דדצח\"מ, שבכל אחד מד' סוגים אלו כלולים בהעלם גם שאר ג' הסוגים, הנה העלם זה שייך לבחי' העלם העצמי [דבחי' עקודים ולמעלה יותר, שלמעלה מענין ההתחלקות]. ועפ\"ז מובן מה שמבאר בהמאמר (בהענין דל' כלים דאצילות נעשים נר\"נ לבי\"ע) שבכל עולם מהג' עולמות בי\"ע ישנם כל ג' הבחינות חב\"ד חג\"ת נה\"י, כי ההתכללות דבחי' חג\"ת ונה\"י בבריאה, וכן חב\"ד ונה\"י ביצירה, חב\"ד וחג\"ת בעשי', הוא מצד בחי' ההעלם שבבי\"ע, השייך לבחי' העלם העצמי (בדוגמת ההתכללות דדצח\"מ, כנ\"ל).\nו) <b>ועפ\"ז</b> יובן גם שלאחרי שמבאר הענין דלמ\"ד כלים דאצילות נעשים נר\"נ לבי\"ע, וענין ההתכללות שבבי\"ע, מקשה בהמאמר<sup data-n=\"4119\">25</sup>: אך הנה <i>מעתה </i>יש להבין איך יוכל להיות התהוות בע\"ג מאור א\"ס שהוא בלתי בע\"ג. דלכאורה הרי קושיא זו היא גם בנוגע לאצילות, שהרי גם אצילות הוא הגבלה, וגם בנוגע לבי\"ע, הרי הקושיא לכאורה הוא מצד עצם ענין ההגבלה שבבי\"ע, ולא מצד ענין ההתכללות כו', ולמה כותב <i>מעתה </i>יש להבין כו'. אך הענין הוא, כי אמיתית ענין ההגבלה הוא מצד ענין ההתכללות דוקא. דבאצילות, להיות שהע\"ס הם מחולקים זמ\"ז, הרי ההגבלה דאצילות היא בחי' גילוי (ואינה אמיתית ענין דהגבלה), משא\"כ כאשר ל' כלים דאצילות נעשים נר\"נ לבי\"ע, שבכל עולם נמשכים כל היו\"ד ספירות באופן של העלם כנ\"ל, הנה זהו אמיתית ענין ההגבלה. ולכן מקשה מעתה ישלהבין איך יוכל להיות התהוות בע\"ג מאור א\"ס שהוא בלתי בע\"ג. ועל זה מתרץ, שזהו מצד עצמות אוא\"ס שנמצא למטה כמו למעלה בשוה ממש, והיינו שדוקא בההגבלה דבי\"ע, בחי' העלם שלמטה מבחי' גילוי, מתבטא בחי' העלם העצמי שלמעלה מהגדרים דהעלם וגילוי. וכידוע<sup data-n=\"4120\">26</sup> שיש הנברא הוא בחי' יש האמיתי. וזהו ג\"כ מה שמסיים בהמאמר<sup data-n=\"4121\">27</sup> בענין מרום וקדוש אשכון את דכא ושפל רוח דוקא<sup data-n=\"4122\">28</sup>. ואח\"כ מבאר שההגבלה וההעלם שלמטה, שהוא בבחי' העדר ההתחלקות, היא דוגמת בחי' עקודים בכלי אחד, בחי' מקיף הכללי שלמעלה מהתחלקות.\nז) <b>ובזה</b><sup data-n=\"4123\">29</sup> יובן ג\"כ מה שאמרו כל העוסק בתורה לשמה כו', דלכאורה הרי עסק התורה לשמה היא מדריגה נעלית, והרי תורה על הרוב תדבר<sup data-n=\"4124\">30</sup>, ואיך שייך ענין העסק בתורה לשמה אצל אלו שהם במדריגה נמוכה, אך הענין הוא, דלהיות שעסק התורה לשמה הו\"ע המשכת בחי' העלם העצמי, הנה בזה כולם שוין, אף שיש בזה חילוקים בענין ההתגלות. וע\"ד המבואר בתו\"א<sup data-n=\"4125\">31</sup> שישנו מי שדי לו בפ\"א שחרית ופ\"א ערבית, ויש מי שצריך לקיים והגית בו יומם ולילה כפשוטו, שההפרש הוא רק בענין ההתגלות כו'. ועד שכהסיום בתו\"א שם בהחצע\"ג שסו\"ס נמשך גם בגילוי (כבהברכה הנ\"ל) דישלים לו הקב\"ה כו'.\nח) <b>והנה</b> המאמר ד\"ה להבין מ\"ש בע\"ח הנ\"ל לאדה\"ז, הי' עד עכשיו בהעלם, וע\"י סיבות מסיבות שונות יצא מן המיצר כו' ונמצא עכשיו בדפוס, וידועים דברי הצ\"צ<sup data-n=\"4126\">32</sup> שדבר שבדפוס הוא לדורי דורות. ויש לקשר זה עם מ\"ש<sup data-n=\"4127\">33</sup> מלחמה להוי' בעמלק מדור דור, שישנם בזה כמה פירושים ודרגות, דורו של משה ודורו של שמואל, דורו של משה ושמואל ודורו של משיח<sup data-n=\"4128\">34</sup>, שאז יהי' (לא רק תמחה<sup data-n=\"4129\">35</sup> אלא גם) מחה אמחה גו'<sup data-n=\"4130\">36</sup>, והוא שע\"י העבודה דיפוצו מעינותיך חוצה (שכל אחד מתעסק בזה, ומכאן ולהבא יתעסק עוד יותר) נזכה לביאת משיח צדקנו<sup data-n=\"4131\">37</sup> בקרוב בימינו ובעגלא דידן.\n**********",[["4094","*","התחלת וסיום המאמר – הוגה ע\"י כ\"ק אדמו\"ר שליט\"א. גוף המאמר – הוא המשך למאמר ד\"ה פדה בשלום נפשי די\"ט כסלו (לעיל ע' תסג. וראה שם הערות 9-8)."],["4095","1","סנהדרין צט, ב."],["4096","2","סה\"מ תש\"א ע' 53 ואילך."],["4097","3","ראה מדרש תהלים צ, ד. ב\"ר פ\"ח, ב. תנחומא וישב ד. זח\"ב מט, א. ועוד."],["4098","4","פרש\"י עה\"ת בתחלתו. ובכ\"מ."],["4099","5","מגלה עמוקות אופן קפו."],["4100","6","ראה ספר הליקוטים (דא\"ח להצ\"צ) ערך ישראל סכ\"ב. וש\"נ."],["4101","7","ראה גם מאמרי אדה\"ז הקצרים ע' תקנח."],["4102","8","שמו\"ר פ\"ל, ג."],["4103","9","בראשית ב, ד."],["4104","10","רות ד, יח."],["4105","11","ראה עץ חיים שער ג פ\"א. שער מב פ\"א-ב. אגה\"ת פ\"ד. ובכ\"מ."],["4106","12","ראה תקו\"ז בהקדמה (ג, סע\"ב). אגה\"ק רס\"כ. ובכ\"מ."],["4107","13","תהלים ה, ה. וראה תקו\"ז תנ\"ו (צ, רע\"ב). לקו\"ת במדבר ג, סע\"ג. וש\"נ."],["4108","14","נדפס בספר מאמרי אדה\"ז תקס\"ח ח\"א ע' קיד ואילך."],["4109","15","ד\"ה פדה בשלום (לעיל ע' תסג ואילך)."],["4110","16","מכאן עד סוס\"ו – הנחה בלתי מוגה."],["4111","17","פסחים ג, ב. וש\"נ."],["4112","18","בספריית ליובאוויטש כת\"י 632 (לב, ריש ע\"א)."],["4113","19","איוב יט, כו."],["4114","20","מאמרי אדה\"ז שם ס\"ע קיז ואילך."],["4115","21","שם ריש ע' קכ ואילך."],["4116","22","שם ע' קכד."],["4117","23","שם ריש ע' קכג."],["4118","24","ראה בארוכה ד\"ה חביבין ישראל תרצ\"ו (סה\"מ תרצ\"ו ע' 91 ואילך). איזהו חכם תש\"ב פ\"ה (סה\"מ תש\"ב ע' 127 ואילך). ובכ\"מ."],["4119","25","מאמרי אדה\"ז שם ע' קכא."],["4120","26","ראה ביאורי הזהר לאדמו\"ר האמצעי בשלח מג, ג ואילך. ובכ\"מ."],["4121","27","מאמרי אדה\"ז שם ע' קכה."],["4122","28","ישעי' נז, טו."],["4123","29","מכאן עד סוף המאמר הוגה ע\"י כ\"ק אדמו\"ר שליט\"א."],["4124","30","ראה מו\"נ ח\"ג פל\"ד."],["4125","31","מג\"א צח, סע\"ג."],["4126","32","אגרות-קודש אדמו\"ר מוהריי\"צ ח\"ב ע' שפב."],["4127","33","ס\"פ בשלח."],["4128","34","יל\"ש עה\"פ (רמז רסז)."],["4129","35","ס\"פ תצא."],["4130","36","בשלח יז, יד."],["4131","37","אגה\"ק דכ\"ק הבעש\"ט (נדפסה בס' פורת יוסף. כתר שם טוב בתחלתו. ובכ\"מ)."]]],[1500370056,"<h3>בס\"ד. ש\"פ שמות, כ\"ה טבת, מבה\"ח שבט, ה'תשל\"ז<sup data-n=\"4132\">*</sup></h3>\n(הנחה בלתי מוגה)\n<b>ואלה</b> שמות בני ישראל הבאים מצרימה גו' ראובן שמעון לוי ויהודה גו'<sup data-n=\"4133\">1</sup>. וידוע דיוק בעל ההילולא [דכ\"ד טבת – כ\"ק אדמו\"ר הזקן] בספרו תורה אור בד\"ה זה<sup data-n=\"4134\">2</sup>, דבפרשת ויגש<sup data-n=\"4135\">3</sup> נאמר ג\"כ ואלה שמות בני ישראל הבאים מצרימה גו', וצריך להבין למה הוכפל בתורה ענין בואם מצרימה. וכ\"ק אדמו\"ר האמצעי מוסיף עוד [בד\"ה זה שבתורת חיים<sup data-n=\"4136\">4</sup>, שהוא ביאור על מאמר הנ\"ל מכ\"ק אדמו\"ר הזקן וביאורו<sup data-n=\"4137\">5</sup>] דידוע<sup data-n=\"4138\">6</sup> שהתורה היא נצחית ומדברת בכל זמן ובכל דור, דהיינו שגם ענין הביאה למצרים וכו' ישנו בכל דור, וכן ישנה הוראה מזה לכאו\"א מישראל בכל זמן ובכל מקום, דתורה היא מלשון הוראה<sup data-n=\"4139\">7</sup>, וא\"כ ההוראה היא נצחית. והנה, כיון שהתורה היא נצחית מובן שגם פרטי הענינים דגלות מצרים וכו' ישנם בכל דור, ולכן גם פרטי הענינים דוימררו את חייהם בעבודה קשה ובלבנים גו' את כל עבודתם אשר עבדו בהם בפרך<sup data-n=\"4140\">8</sup>, ישנם ג\"כ בכל הזמנים. ואין הכוונה בהענין דוימררו את חייהם גו' בשביל עצמו ח\"ו, כ\"א זה שישנו ענין זה הוא רק בשביל הגאולה וכו' שלאח\"ז. וכמ\"ש<sup data-n=\"4141\">9</sup> אנכי ארד עמך מצרימה ואנכי אעלך גם עלה גו', והיינו דכל הכוונה בהירידה למצרים וכו' הוא רק בשביל שיהי' אח\"כ ואנכי אעלך גם עלה.\nב) <b>והענין</b> הוא<sup data-n=\"4142\">10</sup>, דהנה כתיב<sup data-n=\"4143\">11</sup>, ירוד ירדנו, שישנם ב' ירידות, וכן בענין הגאולה נאמר ואנכי אעלך גם עלה, ב' עליות, ובכללות ב' (ירידות ו)עליות אלו קאי על גאולת מצרים והגאולה העתידה. ולכאורה מהי השייכות בין הגאולה ממצרים להגאולה העתידה (שמקשרים אותם זל\"ז).\n<b>והענין</b> הוא<sup data-n=\"4144\">12</sup>, דהנה כתיב<sup data-n=\"4145\">13</sup> כימי צאתך מארץ מצרים אראנו נפלאות. דהפירוש הפשוט בהכתוב הוא, דכמו שבימי צאתך מארץ מצרים היו נפלאות הנהבדוגמא לזה אראנו נפלאות בגאולה העתידה, ובזהר<sup data-n=\"4146\">14</sup> פירש שהנפלאות דגאולה העתידה יהיו נפלאות אפילו לגבי הנפלאות שהיו בימי צאתך מארץ מצרים. אמנם מזה שמדמין ב' הנפלאות (דמצרים והגאולה העתידה) זל\"ז מובן שיש ביניהם שייכות בתוכנם הפנימי (ולא רק שדומין מצד זה שבשניהם ישנם נפלאות), ומפני שהם דומים בתוכנם הפנימי נמשך אח\"כ שהם דומים גם במה שבשני הגאולות ישנם נפלאות [וזהו קשר המשך המאמר (בתורה אור שם, וכן בתורת חיים שם) שלאחר שביאר דב' העליות (דאעלך גם עלה) קאי על גאולת מצרים והגאולה העתידה ממשיך דהנה כתיב כימי צאתך מארץ מצרים אראנו נפלאות, כי בזה בא לבאר את השייכות שבין ב' הגאולות (שמקשרים אותם בהכתוב דאעלך גם עלה)].\nג) <b>וביאור</b> השייכות בתוכן ב' הגאולות (דמצרים ודלע\"ל) הוא<sup data-n=\"4147\">15</sup>, דכמו שבגלות מצרים לא היתה הכוונה בהגלות עצמו ח\"ו, ונקודתו הפנימית היתה ענין הגאולה שלאח\"ז, שתכליתה הוא קבלת התורה כמ\"ש<sup data-n=\"4148\">16</sup> בהוציאך את העם ממצרים תעבדון את האלקים על ההר הזה, הנה כך כל הגלות הזה הוא כדי לזכות לגילוי פנימיות התורה שיהי' לע\"ל, שע\"ז נאמר<sup data-n=\"4149\">17</sup> ישקני מנשיקות פיהו גו'. דכמו שענין השעבוד דמצרים הי' בכדי לצרף את ישראל ולזככם ולטהרם בכדי שיוכלו לקבל את התורה, בדוגמא לכור הברזל<sup data-n=\"4150\">18</sup> שמצרף את הכסף מהפסולת והסיגים ונשאר הכסף נקי מכל סיג כו', הנה עד\"ז ע\"י גלות זה האחרון זוכים לגילוי פנימיות התורה [ונמשך באופן דמיני' יתפרנסון<sup data-n=\"4151\">19</sup>, והיינו באופן של פרנסה ומזון<sup data-n=\"4152\">20</sup>, דענין זה הוא אמיתית הפרנסה של (כל) א' מישראל, ועד שנמשך גם בהרגל שלו, ופועל בו התפשטות והתרחבות, וכמו שנת\"ל<sup data-n=\"4153\">21</sup>]. וזהו ביאור גודל אריכות גלות זה האחרון שהוא באין ערוך מגלות מצרים, דטעם הדבר הוא, כיון שתכלית כוונת גלות האחרון הוא בכדי לזכות עי\"ז לגילוי פנימיות התורה, משא\"כ גלות מצרים דכוונתו היתה בשביל גילוי נגלה דתורה, כנ\"ל, לכן כמו שפנימיות התורה, ישקני מנשיקות פיהו, הוא באין ערוך מנגלה דתורה, כמו\"כ הגלות (שע\"י באים לגילוי זה) הוא ג\"כ (בדוגמא להתורה שמתגלית ע\"י) באין ערוך מגלות מצרים שע\"י באו לגילוי נגלה דתורה. דנגלה דתורה הוא בחינת תורה שבאה בהגבלה, משא\"כ פנימיות התורה, שהיא באין ערוך למעלה ממדידה והגבלה. ואע\"פ שגם אריכות גלות זה האחרון באה בהגבלה בכמות (השנים), הנה אין הכוונה בגודל האריכות שבגלות זה על האריכות בזמן (בלבד), כ\"א (גם) על האריכות שבו בגודל היסוריםוהצרות ובפרט בחבלי משיח (חבלי לידה)<sup data-n=\"4154\">22</sup>, שצרות ויסורים אלו הם באין ערוך מהיסורים שבגלות מצרים. ואין הכוונה שצ\"ל ח\"ו צרות ויסורים וכו', כ\"א ענינים שאינם מתאימים לרגילותו של ישראל (וואָס איז ניט לויט די געוואוינהייט פון אַ אידן) בלבד, שג\"ז נחשב ליסורים. וכדאיתא בגמרא<sup data-n=\"4155\">23</sup> עה\"כ<sup data-n=\"4156\">24</sup> ויעבידו מצרים את בני ישראל בפרך שנתנו עבודת נשים לאנשים וכו', אע\"פ שעבודת נשים קלה מעבודת אנשים, דאשה תש כוחה<sup data-n=\"4157\">25</sup>, מ\"מ לגבי האנשים לעבודת פרך יחשב כיון שאינה לפי רגילותם. ועאכו\"כ בנוגע לענין של העדר הרגילות לגבי א' מישראל, שליסורים גדולים יחשב. ובמכש\"כ וק\"ו מנבוכדנצר<sup data-n=\"4158\">26</sup> שבזכות שפסע ג' פסיעות לכבוד ממה\"מ הקב\"ה זכה למלכות לו ולבנו ולבן בנו, ג' דורות<sup data-n=\"4159\">27</sup>, ומלכות בתכלית ההתרחבות וכו', דנבוכדנצר מולך בכפה הי'<sup data-n=\"4160\">28</sup>, הנה עאכו\"כ כשמדובר אודות א' מישראל, בני בכורי ישראל<sup data-n=\"4161\">29</sup>, בנים אתם לה' אלקיכם<sup data-n=\"4162\">30</sup>, הנה הטובה המגיע להם היא שלא לפי ערך כלל ממה שזכה נבוכדנצר, וכ\"א מישראל אפילו הפשוט שבפשוטים ביכולתו לתבוע מהקב\"ה כל ענינים טובים ברוחניות [שזהו העיקר של יהודי] ומזה נמשך גם בגשמיות, בכל עניני ברכה וכו' שכללותם היא בני חיי ומזוני רויחי, ובאופן דמולך בכפה. ומזה מובן שכל ענין של העדר הרגילות של יהודי ליסורים גדולים יחשב, <i>ובאין ערוך</i> לגבי מצרים שהי' לפני מ\"ת ודרגת מצווה ועושה<sup data-n=\"4163\">31</sup>, ועי\"ז מעבירים הכתמים הכי קטנים שנשארו לאחר כל היסורים וצרות וואָס מ'איז דורכגעגאַנגען.\nד) <b>והנה</b> כל הגילויים דלעתיד תלויים במעשינו ועבודתינו במשך השית אלפי שנין דהוה עלמא<sup data-n=\"4164\">32</sup>, וזהו הענין דוימררו את חייהם כמו שהוא ברוחניות, דבעבודה קשה דא קושיא, בחומר דא ק\"ו, ובלבנים דא ליבון הלכתא<sup data-n=\"4165\">33</sup>, וואָס ער מאַטערט זיך אין לימוד התורה להוציא הלכה ברורה ע\"י ריבוי שקו\"ט, ובמצב דבמחשכים הושיבני<sup data-n=\"4166\">34</sup> זה תלמוד בבלי<sup data-n=\"4167\">35</sup>, עד שמלבן (ער וואַשט אויס) את הקושיות ורמינהו וכו' עד שההלכה מאירה ומזהירה. דזהו עיקר ענין התורה, הלכה פסוקהוברורה, דזהו מעלת המשניות שהם הלכה פסוקה וכו'<sup data-n=\"4168\">36</sup>, ולכן ארז\"ל<sup data-n=\"4169\">37</sup> אין הגלויות מתכנסות אלא בזכות משניות שנאמר<sup data-n=\"4170\">38</sup> גם כי יתנו בגוים עתה אקבצם<sup data-n=\"4171\">39</sup>. ועד\"ז ענין הליבון גם בעבודת התפלה, וכמבואר בתורת חיים<sup data-n=\"4172\">40</sup>. וע\"י הענין דוימררו וגו' בתורה ותפלה כנ\"ל, הנה מחליפים (מ'פאַרבייט) יסורי גלות זה האחרון.\nה) <b>וזהו</b> מ\"ש ואלה שמות בני ישראל וגו', שע\"י הענין דשמות בנ\"י פועלים הגאולה שלאח\"ז. דענין שמות בנ\"י הוא, כדאיתא במדרש<sup data-n=\"4173\">41</sup> דראובן שמעון נחתין ראובן שמעון סלקין, שלא שינו את שמם, והיינו דלא רק שעמדו בתוקף על עיקרי התומ\"צ, ואפילו לא על תומ\"צ סתם, כ\"א גם על עניני זהירות וכו' עד שאפילו לא שינו את שמם. ועאכו\"כ שהי' אצלם עניני התומ\"צ עצמם כדבעי. ועד\"ז עכשיו בגלות זה שעומדים בתוקף אפילו על ענינים פשוטים כמו שלא לשנות השם וכו', ועאכו\"כ כו'.\n<b>וכן</b> הוא בתורה, שענינה הוא ג\"כ הענין דשמות, דכל התורה היא שמותיו של הקב\"ה<sup data-n=\"4174\">42</sup>, הנה פועלים המשכה דבחינת ואלה שמות, וכנ\"ל דכל התורה היא שמותיו של הקב\"ה. ויש ס\"ר אותיות לתורה<sup data-n=\"4175\">43</sup>, שמות דהקב\"ה, ומבין צירופים אלו – הקדוש יותר השבע שמות שאינם נמחקים<sup data-n=\"4176\">44</sup>, ומהם גופא – בחינת שמו הגדול<sup data-n=\"4177\">45</sup>, שזהו בחינת הגילוי דלעתיד שפועלים ע\"י העבודה דעכשיו (כנ\"ל). וההמשכה דבחינת שמו הגדול היתה כבר בימי חנוכה שאז הי' כמ\"ש (בועל הנסים) להודות ולהלל לשמך הגדול, ובאופן נצחי, דהנרות הללו אינן בטלין לעולם<sup data-n=\"4178\">46</sup>, אבל המשכה זו היא בהעלם, וגילוי בחינת שמו הגדול יהי' לעתיד.\nו) <b>והנה</b> בהירידה עצמה ב' מדריגות, וע\"ד דוגמא שישנו ירידת השכל באותיות המחשבה, ולמטה יותר מה שהשכל בא גם באותיות הדיבור<sup data-n=\"4179\">47</sup>. וכמו\"כ גם בעבודה דתורה ותפלה ישנם ב' בחינות אלו. דישנו ענין מחשבת התורה וגם הדיבור שבתורה<sup data-n=\"4180\">48</sup>, וכמ\"ש<sup data-n=\"4181\">49</sup> חיים הם למוצאיהם ודרז\"ל<sup data-n=\"4182\">50</sup> למוציאיהם בפה, ועודיותר בכל רמ\"ח אבריו, כמרז\"ל&lt;50&gt; אם ערוכה ברמ\"ח אברים שלך משתמרת. ועד\"ז גם בתפלה, דאע\"פ שתפלה היא עבודה שבלב<sup data-n=\"4183\">51</sup>, וכדאיתא בגמרא<sup data-n=\"4184\">52</sup> איזו היא עבודה שהיא בלב הוי אומר זו תפלה, מ\"מ צ\"ל ג\"כ הדיבור דאותיות התפלה, שעי\"ז מסירים המונעים ומעכבים. וע\"ד מה שמבאר כ\"ק אדמו\"ר הצ\"צ בספר המצוות שלו במצות וידוי תשובה<sup data-n=\"4185\">53</sup> בענין אמירת הכ\"ב אותיות בהוידוי.\n<b>וזהו</b> ענין הגאולה שהו\"ע ההמשכה (דשמו הגדול) בב' המדריגות, בעלמין סתימין דלא אתגליין, עלמא דאתכסיא, שהוא בדוגמת אותיות המחשבה, ובעלמא דאתגליא, שהוא בדוגמא לאותיות הדיבור, דההמשכה בהב' בחינות דעלמא דאתכסיא ועלמא דאתגליא הו\"ע מן העולם ועד העולם [וכמבואר בתו\"א שם<sup data-n=\"4186\">54</sup>]. ע\"י גואל ראשון הוא גואל אחרון<sup data-n=\"4187\">55</sup> בקרוב ממש.\n**********",[["4132","*","על רשימת ההנחה – תיקן כ\"ק אדמו\"ר שליט\"א כמה תיקונים בכתי\"ק (<i>המו\"ל</i>)."],["4133","1","ריש פרשתנו."],["4134","2","פרשתנו מט, א."],["4135","3","מו, ח."],["4136","4","פרשתנו א, א ואילך."],["4137","5","בתו\"א פרשתנו נ, א ואילך."],["4138","6","תניא רפי\"ז. ובכ\"מ."],["4139","7","רד\"ק לתהלים יט, ח. וראה זח\"ג נג, ב."],["4140","8","פרשתנו א, יד."],["4141","9","ויגש מו, ד."],["4142","10","ראה תו\"א שם מט, א."],["4143","11","מקץ מג, כ."],["4144","12","ראה תו\"א שם ותו\"ח שבהערה 4."],["4145","13","מיכה ז, טו."],["4146","14","ח\"א רסא, ב. וראה אוה\"ת נ\"ך ח\"א עה\"פ (ע' תפז)."],["4147","15","ראה תו\"א שם. תו\"ח שם א, ב ואילך."],["4148","16","פרשתנו ג, יב ובפרש\"י."],["4149","17","שה\"ש א, ב ובפרש\"י."],["4150","18","ואתחנן ד, כ. ירמי' יא, ד."],["4151","19","תקו\"ז ת\"ו בסופו."],["4152","20","ראה לקו\"ש ח\"ז ע' 206 ובהערה 3 שם."],["4153","21","שיחת כ\"ף כסלו שנה זו (תשל\"ז)."],["4154","22","ראה מאמרי אדמו\"ר האמצעי קונטרסים ע' רכג ואילך."],["4155","23","סוטה יא, ב."],["4156","24","פרשתנו א, יג."],["4157","25","ראה ברכות לב, א. ב\"ר פכ\"ב, א. פרש\"י ואתחנן ה, כד."],["4158","26","תו\"א מקץ לא, ג."],["4159","27","סנהדרין צו, א. ילקוט שמעוני מלכים רמז רמד."],["4160","28","מגילה יא, א."],["4161","29","פרשתנו ד, כב."],["4162","30","ראה יד, א."],["4163","31","ראה קידושין לא, א. וש\"נ."],["4164","32","תניא רפל\"ז."],["4165","33","זח\"ג קנג, א ברע\"מ."],["4166","34","איכה ג, ו."],["4167","35","סנהדרין כד, א. וראה שערי אורה שער החנוכה ד\"ה בכ\"ה בכסלו פנ\"ד ואילך."],["4168","36","תו\"א שם מט, ב ואילך."],["4169","37","ויק\"ר פ\"ז, ג."],["4170","38","הושע ח, י."],["4171","39","תו\"א שם, ג."],["4172","40","פרשתנו שם ג, א."],["4173","41","ויק\"ר פל\"ב, ה."],["4174","42","ראה זח\"ב פז, א. הקדמת הרמב\"ן לפירושו עה\"ת. פלח הרמון שער כב (שער הכינויים) פ\"א. יונת אלם פכ\"ט. של\"ה שטז, א."],["4175","43","מגלה עמוקות אופן קפו."],["4176","44","שבועות לה, סע\"א. רמב\"ם הל' יסוה\"ת פ\"ו ה\"ב."],["4177","45","בכ\"ז – ראה תו\"א שם מט, ד ואילך."],["4178","46","רמב\"ן ר\"פ בהעלותך."],["4179","47","ראה תו\"א שם נ, א."],["4180","48","ראה גם ד\"ה רני ושמחי וד\"ה מגילה נקראת שנה זו (סה\"מ תשל\"ז ע' 112. ע' 170)."],["4181","49","משלי ד, כב."],["4182","50","עירובין נד, רע\"א."],["4183","51","ראה לקו\"ת אחרי כה, סע\"ד ואילך. קונטרס העבודה פ\"א (ע' 10)."],["4184","52","תענית ב, א."],["4185","53","לח, ב."],["4186","54","נ, א."],["4187","55","ראה שמו\"ר פ\"ב, ד. זח\"א רנג, א. לקו\"ש חי\"א ע' 8 ואילך. וש\"נ."]]]]});
